INSERT INTO public.medicines (slug, generic_name, display_name, active_ingredient, salt, category, description, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, onset, duration, indications, contraindications, warnings, common_adverse_effects, serious_adverse_effects, drug_interactions, monitoring, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, status, verification_status, last_verified, data_version) VALUES
('sotalol', 'Sotalol', 'Sotalol Hydrochloride', 'Sotalol hydrochloride', 'Sotalol hydrochloride', 'Cardiovascular', 'A non-selective beta-blocker with Class III antiarrhythmic potassium channel-blocking properties, used for ventricular arrhythmias and maintaining sinus rhythm in atrial fibrillation.', '[''40 mg'', ''80 mg'', ''160 mg'']', '[''Tablet'']', '[''Oral'']', 'D- and L-isomers block beta-1 and beta-2 adrenergic receptors; D-isomer selectively blocks rapid delayed rectifier potassium current (IKr), prolonging myocardial action potential duration and effective refractory period.', 'Slows heart rate, decreases AV nodal conduction velocity, and prolongs ventricular refractory periods; carries high dose-dependent risk of Torsades de pointes.', 'Rapidly and completely absorbed (>90%); absorption reduced by 20% by food (especially dairy/calcium).', 'Widely distributed; does not cross blood-brain barrier significantly; zero plasma protein binding (0%).', 'Not metabolized by the liver; excreted completely unaltered by the kidneys.', 'Excreted entirely unchanged in urine via glomerular filtration (>80-90%).', '90% to 100%', '12 hours (prolonged significantly in renal failure)', '0%', '1 to 2 hours', '12 hours (dosed twice daily)', '[''Maintenance of normal sinus rhythm in patients with symptomatic atrial fibrillation or flutter'', ''Treatment of documented life-threatening ventricular tachyarrhythmias (sustained VT)'']', '[''Baseline QTc interval > 450 ms'', ''Severe bradycardia (<50 bpm)'', ''Second- or third-degree AV block without pacemaker'', ''CrCl < 40 mL/min for AF indication'', ''Bronchial asthma'', ''Cardiogenic shock'']', '[''Black box warning: Must be initiated in a facility with continuous cardiac monitoring and resuscitation capabilities for at least 3 days'', ''Proarrhythmic risk: Torsades de pointes occurs in 2-4% (highest in females, hypokalemia, renal dysfunction)'', ''Dose strictly based on creatinine clearance'']', '[''Bradycardia'', ''Fatigue'', ''Dyspnea'', ''Dizziness'', ''Nausea'', ''Headache'']', '[''Torsades de pointes / polymorphic ventricular tachycardia'', ''Complete heart block'', ''Severe symptomatic bradycardia'', ''Acute bronchospasm'']', '[''QT-prolonging drugs (amiodarone, macrolides, fluoroquinolones - avoid)'', ''Potassium-depleting diuretics (hypokalemia increases Torsades risk)'', ''Diltiazem / verapamil (severe bradycardia)'']', '[''Continuous ECG monitoring for at least 3 days during initiation or dose increase'', ''Calculate QTc interval before every dose (discontinue if QTc > 500 ms)'', ''Serum potassium and magnesium (maintain K+ > 4.0 mEq/L, Mg2+ > 2.0 mg/dL)'', ''Serum creatinine'']', 'Category B; crosses placenta; causes fetal bradycardia; use only if benefit justifies risk.', 'Excreted in high concentrations in breast milk; breastfeeding not recommended.', 'Approved in children with dose adjusted for body surface area.', 'Higher risk of proarrhythmia due to age-related decline in GFR; start at 80 mg daily.', 'Strict dose titration based on CrCl: CrCl 40-59 mL/min: q24h; CrCl < 40 mL/min: contraindicated for AF; if VT, dose q36-48h.', 'No dosage adjustment required (not metabolized by the liver).', '[''Dual Class II (beta-blocker) and Class III (potassium channel blocker) antiarrhythmic efficacy'', ''High oral bioavailability (100%) and zero hepatic metabolism'', ''Proven efficacy for maintaining sinus rhythm in recurrent atrial fibrillation'']', '[''High risk of Torsades de pointes requires mandatory 3-day inpatient cardiac telemetry for initiation'', ''Eliminated 100% by kidneys; toxic accumulation occurs in renal failure'']', '[''Must be started in the hospital under 3 days of telemetry monitoring'', ''Stop the drug immediately if QTc exceeds 500 ms or increases by >60 ms over baseline'']', 'SOTALOL: Slows AV node; QT prolongation triggers Torsades; Always hospitalize for initiation; Leaves via kidneys unchanged.', '-olol', 'SOE-ta-lol', 'सोटा-लोल', 'active', 'verified', NULL, NULL),
('pindolol', 'Pindolol', 'Pindolol', 'Pindolol', 'Pindolol', 'Cardiovascular', 'A non-selective beta-adrenergic blocker with potent intrinsic sympathomimetic activity (ISA), lowering blood pressure with minimal resting bradycardia or metabolic suppression.', '[''5 mg'', ''10 mg'']', '[''Tablet'']', '[''Oral'']', 'Partial agonist at beta-1 and beta-2 adrenergic receptors (intrinsic sympathomimetic activity - ISA); competitively blocks catecholamines during exercise/stress while providing low-level basal receptor stimulation at rest.', 'Reduces peripheral vascular resistance and systemic blood pressure without causing marked resting bradycardia, cardiac depression, or lipid elevation.', 'Rapidly and completely absorbed (approx. 90-100%); peak plasma levels in 1 to 2 hours; food has no effect.', 'Widely distributed into tissues; crosses blood-brain barrier; 40-50% bound to plasma proteins.', 'Metabolized extensively in the liver (approx. 60-65%) to inactive hydroxylated and glucuronide metabolites.', 'Excreted in urine (approx. 35-40% as unchanged parent drug, remainder as metabolites).', 'Approximately 90%', '3 to 4 hours', '40% to 50%', '1 to 2 hours', '12 to 24 hours', '[''Essential hypertension in patients prone to excessive resting bradycardia'', ''Mild to moderate angina pectoris'']', '[''Bronchial asthma or severe chronic obstructive pulmonary disease'', ''Severe cardiogenic shock or overt decompensated heart failure'', ''Second- or third-degree heart block'']', '[''Avoid abrupt cessation (taper over 1-2 weeks)'', ''May worsen angina or precipitate arrhythmias if withdrawn suddenly'', ''Caution in peripheral vascular disease'']', '[''Insomnia / vivid dreams'', ''Dizziness'', ''Fatigue'', ''Muscle cramps'', ''Nausea'']', '[''Heart failure exacerbation'', ''Severe bronchospasm in asthmatics'', ''Rebound hypertension upon sudden discontinuation'']', '[''Verapamil, diltiazem (additive negative dromotropic effects)'', ''NSAIDs (blunt blood pressure lowering)'', ''Digitalis glycosides'']', '[''Blood pressure and resting heart rate'', ''Assessment for sleep disturbances and bronchospasm'']', 'Category B; use with caution; beta-blockers may decrease placental perfusion.', 'Excreted in breast milk; compatible with close infant heart rate monitoring.', 'Safety and efficacy not established in pediatric patients.', 'Initiate with 5 mg daily; excellent tolerability in seniors prone to bradycardia.', 'No dosage adjustment required in mild to moderate renal disease; balance of renal and hepatic clearance.', 'Dose reduction may be required in severe hepatic cirrhosis.', '[''Intrinsic sympathomimetic activity prevents excessive resting bradycardia (ideal for patients with low baseline heart rate)'', ''Neutral effect on plasma triglycerides and HDL cholesterol'', ''Does not cause severe peripheral coldness compared to pure beta-blockers'']', '[''Not cardioprotective post-myocardial infarction (pure beta-blockers without ISA preferred)'', ''Can cause sleep disturbances and insomnia due to CNS penetration'']', '[''Beta-blocker with partial agonist activity (ISA) that does not drop resting heart rate excessively'', ''Ideal for hypertensive patients whose heart rate is already in the 50s'']', 'PINDO-lol: Partial Intrinsic agonist; Normalizes BP without Dropping resting heart rate excessively.', '-olol', 'PIN-doe-lol', 'पिन्डो-लोल', 'active', 'verified', NULL, NULL),
('fosinopril', 'Fosinopril', 'Fosinopril Sodium', 'Fosinopril sodium', 'Fosinopril sodium', 'Cardiovascular', 'A phosphinic acid-containing ACE inhibitor prodrug characterized by dual, compensatory hepatic and renal elimination, eliminating the need for dose reductions in renal impairment.', '[''10 mg'', ''20 mg'', ''40 mg'']', '[''Tablet'']', '[''Oral'']', 'Hydrolyzed in the liver and gastrointestinal mucosa to fosinoprilat, which competitively inhibits angiotensin-converting enzyme (ACE), blocking conversion of angiotensin I to angiotensin II and preventing bradykinin degradation.', 'Reduces systemic vascular resistance and blood pressure without reflex tachycardia; improves cardiac output in heart failure; demonstrates unique 50:50 compensatory hepatobiliary and renal clearance.', 'Slowly and incomently absorbed (approx. 36%); peak fosinoprilat in 3 hours; food delays absorption slightly.', 'High protein binding (>99% for fosinoprilat, primarily albumin); low volume of distribution.', 'Rapidly and completely cleaved by mucosal and hepatic esterases to active fosinoprilat; no cytochrome P450 involvement.', 'Eliminated equally by hepatic/biliary excretion (approx. 50%) and renal excretion (approx. 50%); in renal failure, biliary clearance increases compensatory up to 100%.', 'Approximately 36%', '12 hours (effective biological half-life of fosinoprilat)', '>99%', '1 hour (peak effect in 2 to 6 hours)', '24 hours', '[''Essential hypertension in adults and pediatric patients ≥6 years'', ''Congestive heart failure (adjunct to diuretics and digitalis)'', ''Proteinuric chronic kidney disease'']', '[''History of ACE inhibitor-associated or hereditary angioedema'', ''Pregnancy (all trimesters)'', ''Concomitant aliskiren in diabetic patients'', ''Concomitant sacubitril/valsartan (36h washout required)'']', '[''Black box warning: Fetal toxicity and death if used during pregnancy; discontinue immediately upon pregnancy confirmation'', ''Angioedema of head and neck'', ''Hyperkalemia and acute hypotension in salt/volume depleted patients'', ''Dry persistent cough'']', '[''Dry cough'', ''Dizziness'', ''Headache'', ''Fatigue'', ''Nausea'', ''Hyperkalemia'']', '[''Fatal airway angioedema'', ''Acute renal failure in bilateral renal artery stenosis'', ''Severe symptomatic hypotension'']', '[''Potassium-sparing diuretics, potassium supplements (hyperkalemia)'', ''NSAIDs (impair antihypertensive effect and renal function)'', ''Lithium (increases lithium toxicity)'']', '[''Serum creatinine and potassium at baseline and periodically'', ''Blood pressure'', ''Monitor for persistent cough'']', 'Strictly contraindicated (Category D); fetotoxic; causes neonatal skull hypoplasia, renal failure, and death.', 'Excreted in low levels in milk; avoid breastfeeding.', 'Approved for pediatric hypertension in children 6 to 16 years (weight-adjusted dosing).', 'No dosage adjustment required based on age alone.', 'NO DOSE ADJUSTMENT REQUIRED in any degree of renal impairment (unique compensatory hepatobiliary clearance).', 'No dosage adjustment required in mild to moderate hepatic impairment (compensatory renal elimination).', '[''Unique compensatory dual elimination: if kidneys fail, liver clears it; if liver fails, kidneys clear it'', ''No dose adjustment required across the entire spectrum of chronic kidney disease'', ''Phosphinic acid structure provides smooth 24-hour blood pressure control'']', '[''Dry persistent ACE inhibitor cough in 10-15% of patients'', ''Risk of angioedema'']', '[''Safest ACE inhibitor for kidney failure: zero dose adjustment required because the liver compensates 50:50'', ''Take once daily in the morning with or without food'']', 'FOSINO-pril: Failsafe dual clearance (50% Liver, 50% Kidney); Outstanding Safety In Nephropathy.', '-pril', 'foe-SIN-oh-pril', 'फ़ोसिनो-प्रिल', 'active', 'verified', NULL, NULL),
('quinapril', 'Quinapril', 'Quinapril Hydrochloride', 'Quinapril hydrochloride', 'Quinapril hydrochloride', 'Cardiovascular', 'A lipophilic bicyclic prodrug ACE inhibitor with high vascular tissue ACE affinity and endothelial protective actions, used for hypertension and heart failure.', '[''5 mg'', ''10 mg'', ''20 mg'', ''40 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'De-esterified in the liver to active quinaprilat, a potent competitive inhibitor of angiotensin-converting enzyme (ACE); exhibits extremely high affinity and binding to tissue-bound ACE in vascular endothelium.', 'Suppresses tissue and circulating angiotensin II, reduces systemic vascular resistance, preserves renal blood flow, and improves arterial compliance and endothelial dysfunction.', 'Rapidly absorbed (approx. 60%); peak quinapril in 1 hour; conversion to quinaprilat yields peak levels in 2 hours; high-fat meals reduce absorption by 25-30%.', 'Widely distributed into vascular tissue; quinaprilat is 97% bound to plasma proteins.', 'Extensively hydrolyzed in the liver to active quinaprilat and minor inactive diketopiperazine metabolites.', 'Excreted in urine (approx. 61%, primarily as quinaprilat) and faeces (approx. 37%).', 'Approximately 60% absorbed; active quinaprilat bioavailability is 38%', 'Parent 1 hour; active quinaprilat effective half-life 3 hours (terminal dissociation half-life 25 hours)', '97%', '1 hour', '24 hours', '[''Essential hypertension'', ''Congestive heart failure (adjunct therapy in NYHA Class II-IV)'', ''Hypertension with vascular endothelial dysfunction'']', '[''History of ACE inhibitor-induced or idiopathic angioedema'', ''Pregnancy (all trimesters)'', ''Concomitant sacubitril/valsartan or aliskiren in diabetics'']', '[''Black box warning: Fetal toxicity; strictly contraindicated in pregnancy'', ''Life-threatening angioedema of face and larynx'', ''Hyperkalemia and first-dose hypotension'', ''Persistent dry cough'']', '[''Headache'', ''Dizziness'', ''Dry persistent cough'', ''Fatigue'', ''Hyperkalemia'']', '[''Severe angioedema'', ''Acute renal failure'', ''Severe hypotension / syncope'', ''Agranulocytosis (rare)'']', '[''Potassium supplements, spironolactone (hyperkalemia risk)'', ''NSAIDs (blunt hypotensive effect)'', ''Tetracycline antibiotics (quinapril tablets contain magnesium carbonate excipient which chelates tetracyclines)'']', '[''Serum creatinine and eGFR at baseline and periodically'', ''Serum potassium'', ''Blood pressure'']', 'Category D; strictly contraindicated in pregnancy due to severe fetotoxicity and neonatal death.', 'Excreted in breast milk; avoid breastfeeding.', 'Safety and efficacy not established in pediatric patients.', 'Initiate with 5-10 mg daily; titrate carefully based on renal function.', 'Dose reduction required if CrCl < 60 mL/min: CrCl 30-60 mL/min: start at 5 mg daily; CrCl 10-30 mL/min: start at 2.5 mg daily; CrCl < 10 mL/min: insufficient data.', 'No dosage adjustment required in hepatic disease.', '[''Highest vascular tissue ACE binding affinity among classical ACE inhibitors, maximizing endothelial protection'', ''Rapid onset of action with consistent 24-hour hemodynamic benefits'', ''Proven reduction in left ventricular mass and arterial stiffness'']', '[''Class-wide dry hacking cough'', ''Magnesium excipient in tablets interacts with tetracycline antibiotics'']', '[''Potent tissue ACE inhibitor with strong vascular endothelial benefits'', ''Note that the tablet contains magnesium: separate from tetracycline antibiotics by 2 hours'']', 'QUIN-april: Quick-acting; Utmost In affinity for tissue-bound Vascular ACE; Inhibits Endothelial breakdown.', '-pril', 'KWIN-a-pril', 'क्विना-प्रिल', 'active', 'verified', NULL, NULL),
('trandolapril', 'Trandolapril', 'Trandolapril', 'Trandolapril', 'Trandolapril', 'Cardiovascular', 'An ultra-lipophilic, long-acting non-sulfhydryl ACE inhibitor prodrug proven in the TRACE trial to significantly reduce mortality, sudden cardiac death, and progression to severe heart failure post-MI.', '[''1 mg'', ''2 mg'', ''4 mg'']', '[''Capsule'']', '[''Oral'']', 'Bioactivated in the liver by ester cleavage to trandolaprilat, an exceptionally potent, slow-dissociating competitive inhibitor of ACE with high tissue affinity; blocks angiotensin II formation and promotes bradykinin-mediated vasodilation.', 'Reduces left ventricular dilatation and myocardial remodeling; significantly reduces all-cause mortality and sudden death in patients with left ventricular systolic dysfunction following acute myocardial infarction (TRACE trial).', 'Rapidly absorbed (approx. 40-60%); peak trandolapril in 0.5-1 hour; peak trandolaprilat in 4 to 10 hours; food does not alter AUC.', 'Highly lipophilic; penetrates deep into cardiac and vascular tissues; trandolaprilat is 80-94% bound to plasma proteins.', 'Extensively hydrolyzed in the liver to active trandolaprilat and inactive glucuronides; not dependent on CYP enzymes.', 'Excreted in faeces (approx. 66%) via biliary elimination and urine (approx. 33%).', 'Trandolapril 40-60%; absolute bioavailability of active trandolaprilat is 70%', 'Trandolapril 1 hour; active trandolaprilat terminal half-life 16 to 24 hours (tissue retention up to 96 hours)', '80% to 94%', '1 to 2 hours', '24 hours', '[''Essential hypertension (alone or combined with verapamil as Tarka)'', ''Post-myocardial infarction left ventricular dysfunction (TRACE trial: LVEF ≤35%)'', ''Stable chronic heart failure'']', '[''History of angioedema related to ACE inhibitors'', ''Pregnancy (all trimesters)'', ''Concomitant sacubitril/valsartan or aliskiren in diabetics'']', '[''Black box warning: Fetal toxicity; discontinue immediately when pregnancy detected'', ''Angioedema of airway'', ''Hyperkalemia and hypotension in salt-depleted patients'', ''Dry cough'']', '[''Dizziness'', ''Dry cough'', ''Headache'', ''Fatigue'', ''Hyperkalemia'']', '[''Fatal angioedema'', ''Severe acute hypotension / shock'', ''Acute kidney injury in renal artery stenosis'']', '[''Potassium-sparing diuretics, potassium supplements (severe hyperkalemia)'', ''NSAIDs (renal decline and loss of BP control)'', ''Lithium (lithium toxicity)'']', '[''Serum creatinine and eGFR at baseline and within 2 weeks'', ''Serum potassium levels'', ''Blood pressure sitting and standing'']', 'Strictly contraindicated (Category D); fetotoxic; causes oligohydramnios and neonatal skull defects.', 'Excretion in human milk unknown; breastfeeding not recommended.', 'Safety and efficacy not established in pediatric patients.', 'Initiate with 0.5 to 1 mg once daily; titrate cautiously.', 'If CrCl < 30 mL/min, initiate at 0.5 mg once daily; titrate up to maximum 2 mg daily.', 'Initiate at 0.5 mg once daily in patients with hepatic cirrhosis.', '[''Proven post-MI mortality reduction (TRACE trial: 22% reduction in overall mortality, 24% reduction in sudden death)'', ''Ultra-long biological half-life provides true once-daily 24-hour hemodynamic protection'', ''High lipophilicity provides deep cardiac tissue penetration'']', '[''Class-wide dry cough in up to 15% of patients'', ''Requires slow titration post-myocardial infarction'']', '[''Proven to reduce sudden cardiac death and mortality after heart attacks (TRACE trial)'', ''Take once daily in the morning; start at 0.5-1 mg and titrate up to 4 mg'']', 'TRANDO-lapril: TRACE trial proven; Transcends mortality After Myocardial Infarction; Deep cardiac tissue binding.', '-pril', 'tran-DOE-la-pril', 'ट्रैंडोला-प्रिल', 'active', 'verified', NULL, NULL),
('benazepril', 'Benazepril', 'Benazepril Hydrochloride', 'Benazepril hydrochloride', 'Benazepril hydrochloride', 'Cardiovascular', 'A potent non-sulfhydryl ACE inhibitor prodrug proven to slow the progression of chronic renal insufficiency in non-diabetic kidney disease (AIPRI trial).', '[''5 mg'', ''10 mg'', ''20 mg'', ''40 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Cleaved by hepatic esterases to active benazeprilat, which competitively inhibits ACE, preventing conversion of angiotensin I to angiotensin II and reducing sympathetic outflow and aldosterone production.', 'Decreases systemic vascular resistance, reduces intraglomerular capillary pressure, and slows the progression of chronic renal disease and proteinuria (AIPRI trial).', 'Rapidly absorbed (at least 37%); peak benazepril in 0.5 to 1 hour; peak benazeprilat in 1 to 2 hours; food delays absorption slightly but does not decrease extent.', 'Widely distributed; benazeprilat is 95% bound to human plasma proteins.', 'Extensively bioactivated in the liver by ester cleavage to benazeprilat; minor glucuronidation.', 'Benazeprilat is eliminated primarily by renal excretion (approx. 80%) and biliary excretion (approx. 20%).', 'Approximately 37% absorbed; active benazeprilat bioavailability is approx. 28%', 'Parent benazepril 0.6 hours; active benazeprilat effective half-life 10 to 11 hours (terminal half-life 22 hours)', '95%', '1 hour', '24 hours', '[''Essential hypertension in adults and children ≥6 years'', ''Chronic kidney disease with proteinuria (AIPRI trial: slows renal decline in non-diabetic CKD)'', ''Congestive heart failure adjunct'']', '[''History of ACE inhibitor-associated angioedema'', ''Pregnancy (all trimesters)'', ''Concomitant sacubitril/valsartan or aliskiren in diabetics'']', '[''Black box warning: Fetal toxicity; discontinue immediately if pregnancy occurs'', ''Angioedema of face, lips, glottis'', ''Hyperkalemia and acute renal failure in bilateral renal artery stenosis'', ''Dry persistent cough'']', '[''Headache'', ''Dizziness'', ''Dry cough'', ''Somnolence'', ''Postural lightheadedness'', ''Hyperkalemia'']', '[''Airway angioedema'', ''Severe acute hypotension'', ''Acute renal failure'', ''Stevens-Johnson syndrome (rare)'']', '[''Potassium supplements, potassium-sparing diuretics (severe hyperkalemia)'', ''NSAIDs (blunt BP reduction, acute renal failure)'', ''Lithium'']', '[''Serum creatinine and eGFR at baseline and within 1-2 weeks'', ''Serum potassium'', ''Urinary protein-to-creatinine ratio (monitors CKD benefit)'']', 'Category D; strictly contraindicated in pregnancy; causes fetal renal dysgenesis and death.', 'Excreted in low levels in breast milk; compatible with caution.', 'Approved for children 6 to 16 years (weight-adjusted dosing: 0.1 to 0.6 mg/kg once daily).', 'Initiate with 5-10 mg daily; monitor renal function.', 'If CrCl < 30 mL/min, initiate with 5 mg once daily; titrate up to maximum 40 mg daily.', 'No dosage adjustment required in hepatic impairment.', '[''Proven to slow the progression of chronic renal failure in non-diabetic kidney disease (AIPRI trial)'', ''Available in proven synergistic fixed-dose combination with amlodipine (Lotrel)'', ''Consistent 24-hour trough-to-peak control'']', '[''Dry persistent cough'', ''Requires dose reduction in advanced renal failure'']', '[''Excellent ACE inhibitor for slowing kidney disease progression (AIPRI trial)'', ''Take once daily; check potassium and creatinine within 2 weeks of starting'']', 'BENAZE-pril: Beneficial Effect on Non-diabetic Albuminuric renal disease (AIPRI trial); Avoid In Pregnancy.', '-pril', 'ben-AY-ze-pril', 'बेनाज़े-प्रिल', 'active', 'verified', NULL, NULL),
('irbesartan', 'Irbesartan', 'Irbesartan', 'Irbesartan', 'Irbesartan', 'Cardiovascular', 'A potent, non-peptide AT1-receptor blocker with insurmountable binding and high oral bioavailability (60-80%), proven to halt the progression of diabetic nephropathy (IDNT and IRMA-2 trials).', '[''75 mg'', ''150 mg'', ''300 mg'']', '[''Tablet'']', '[''Oral'']', 'Selectively and insurmountably blocks angiotensin II type 1 (AT1) receptors in vascular smooth muscle and the adrenal gland, blocking angiotensin II-mediated vasoconstriction and aldosterone synthesis.', 'Lowers systemic vascular resistance, reduces blood pressure, and reduces intraglomerular pressure, significantly slowing the doubling of serum creatinine, end-stage renal disease, and proteinuria in type 2 diabetic nephropathy.', 'Rapidly and well absorbed; peak plasma concentration in 1.5 to 2 hours; high oral bioavailability (60-80%); absorption is completely unaffected by food.', 'Apparent volume of distribution approx. 53 to 93 L; highly bound to plasma proteins (approx. 90%), predominantly albumin.', 'Metabolized in the liver by CYP2C9 via oxidation and glucuronidation; no active circulating metabolites (parent drug accounts for >80% of circulating radioactivity).', 'Eliminated by both biliary/fecal excretion (approx. 80%) and renal excretion (approx. 20%).', '60% to 80% (highest oral bioavailability among classical ARBs)', '11 to 15 hours', '90%', '1 to 2 hours', '24 hours', '[''Essential hypertension in adults'', ''Diabetic nephropathy in patients with type 2 diabetes and hypertension (IDNT and IRMA-2 trials: proven renoprotection)'', ''Microalbuminuria in hypertensive type 2 diabetic patients'']', '[''Hypersensitivity to irbesartan'', ''Pregnancy (all trimesters)'', ''Concomitant use with aliskiren in patients with diabetes mellitus'']', '[''Black box warning: Fetal toxicity; discontinue immediately when pregnancy is detected'', ''Hyperkalemia (especially in diabetics with renal impairment)'', ''Hypotension in volume- or salt-depleted patients'', ''Renal artery stenosis risk'']', '[''Dizziness'', ''Fatigue'', ''Hyperkalemia'', ''Diarrhoea'', ''Musculoskeletal pain'']', '[''Acute kidney injury / worsening renal failure'', ''Severe hyperkalemia (>5.5 mEq/L)'', ''Angioedema (rare compared to ACE inhibitors)'']', '[''Potassium supplements, potassium-sparing diuretics (hyperkalemia)'', ''NSAIDs (impair antihypertensive and renoprotective effects)'', ''Lithium (increases lithium levels)'', ''CYP2C9 inducers/inhibitors'']', '[''Serum potassium and serum creatinine at baseline, 2 weeks, and periodically'', ''Urinary albumin excretion rate'', ''Blood pressure'']', 'Black box warning: Strictly contraindicated throughout pregnancy (causes fetal renal failure, skull hypoplasia, and death).', 'Excreted in animal milk; avoid breastfeeding.', 'Safety and efficacy not established in pediatric patients under 6 years.', 'Initiate at 75-150 mg daily; titrate up to 300 mg daily for renal protection.', 'No dosage adjustment required in any degree of renal impairment (including hemodialysis).', 'No dosage adjustment required in mild to moderate hepatic impairment.', '[''Gold standard renoprotective ARB proven in landmark IDNT and IRMA-2 trials to prevent dialysis in diabetic kidney disease'', ''Highest oral bioavailability (60-80%) of any classical ARB, ensuring consistent absorption unaffected by food'', ''Dual renal and biliary excretion eliminates the need for renal dose adjustment'']', '[''Strictly contraindicated in pregnancy'', ''Requires full 300 mg daily dose for maximal diabetic kidney protection'']', '[''Drug of choice for diabetic kidney disease with protein in the urine (IDNT trial)'', ''Target dose for kidney protection is 300 mg once daily (taken with or without food)'']', 'IRBE-sartan: Invaluable Renoprotection in Both Early and late Diabetic nephropathy (IDNT trial).', '-sartan', 'ir-be-SAR-tan', 'इरबे-सारटन', 'active', 'verified', NULL, NULL),
('eprosartan', 'Eprosartan', 'Eprosartan Mesylate', 'Eprosartan mesylate', 'Eprosartan mesylate', 'Cardiovascular', 'A non-biphenyl, non-tetrazole AT1-receptor blocker with dual postsynaptic AT1 and presynaptic sympathoinhibitory properties, effective for isolated systolic hypertension and stroke prevention (MOSES trial).', '[''400 mg'', ''600 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Competitively and selectively blocks AT1 receptors postsynaptically, preventing angiotensin II vasoconstriction; uniquely blocks presynaptic AT1 receptors on sympathetic nerve terminals, inhibiting norepinephrine release and sympathetic tone.', 'Reduces peripheral vascular resistance and systemic blood pressure; reduces cardiovascular events and recurrent stroke in hypertensive patients with prior cerebrovascular events (MOSES trial).', 'Rapidly absorbed; peak plasma concentrations in 1 to 2 hours; absolute oral bioavailability approx. 13% due to limited absorption; take consistently with or without food.', 'Low volume of distribution (approx. 13 L); highly bound to plasma proteins (approx. 98%).', 'Minimal hepatic metabolism (<2%); does not utilize or inhibit cytochrome P450 enzymes.', 'Excreted predominantly unchanged in faeces (approx. 90% via biliary route) and urine (approx. 7%).', 'Approximately 13%', '5 to 9 hours', '98%', '1 to 2 hours (peak effect in 2 to 3 weeks)', '24 hours', '[''Essential hypertension (alone or in combination with other antihypertensives)'', ''Hypertension in patients with a history of stroke or transient ischemic attack (MOSES trial)'', ''Isolated systolic hypertension'']', '[''Hypersensitivity to eprosartan'', ''Pregnancy (all trimesters)'', ''Concomitant aliskiren in diabetic patients'']', '[''Black box warning: Fetal toxicity; discontinue immediately upon pregnancy confirmation'', ''Hyperkalemia and hypotension in salt-depleted patients'', ''Bilateral renal artery stenosis precautions'']', '[''Upper respiratory tract infection'', ''Headache'', ''Dizziness'', ''Fatigue'', ''Nausea'']', '[''Acute renal failure'', ''Severe symptomatic hypotension'', ''Hyperkalemia'', ''Angioedema (rare)'']', '[''Potassium supplements, potassium-sparing diuretics (additive hyperkalemia risk)'', ''NSAIDs (reduce antihypertensive efficacy)'', ''Lithium'']', '[''Serum potassium and creatinine at baseline and periodically'', ''Blood pressure sitting and standing'']', 'Black box warning: Strictly contraindicated in pregnancy (severe fetotoxicity, oligohydramnios, neonatal death).', 'Excreted in animal milk; avoid breastfeeding.', 'Safety and efficacy not established in pediatric patients.', 'Start at 600 mg once daily in elderly patients; well tolerated in isolated systolic hypertension.', 'No dosage adjustment required in mild to moderate renal failure; in severe renal failure (CrCl < 30 mL/min), maximum dose is 600 mg daily.', 'No dosage adjustment required in mild to moderate hepatic impairment.', '[''Dual mechanism: blocks postsynaptic vascular AT1 receptors AND presynaptic sympathetic nerve terminals, lowering stress-induced sympathetic spikes'', ''Non-biphenyl, non-tetrazole structure free of CYP450 drug interactions'', ''Proven secondary stroke reduction in the MOSES trial'']', '[''Low oral bioavailability (13%)'', ''Twice-daily dosing occasionally required for full 24-hour control at lower doses'']', '[''Blocks both angiotensin II and excess sympathetic nerve adrenaline release'', ''Proven to reduce recurrent strokes in hypertensive patients (MOSES trial)'']', 'EPRO-sartan: Extended Protection from Recurrent Occlusive stroke (MOSES trial); Presynaptic sympathetic block.', '-sartan', 'ep-roe-SAR-tan', 'एप्रो-सारटन', 'active', 'verified', NULL, NULL),
('azilsartan', 'Azilsartan', 'Azilsartan Medoxomil', 'Azilsartan medoxomil', 'Azilsartan medoxomil', 'Cardiovascular', 'An advanced ester prodrug ARB with the tightest, longest-lasting AT1-receptor binding kinetics in its class, delivering superior 24-hour blood pressure reduction compared to valsartan and olmesartan.', '[''40 mg'', ''80 mg'']', '[''Tablet'']', '[''Oral'']', 'Rapidly hydrolyzed by esterases in the gastrointestinal tract and liver to active azilsartan; binds with exceptional affinity and an extremely slow dissociation rate to the AT1 receptor, providing insurmountable and sustained receptor blockade.', 'Produces significantly greater reductions in 24-hour ambulatory, clinic, and nocturnal systolic blood pressure than maximal doses of valsartan (320 mg) and olmesartan (40 mg); promotes vascular remodeling and endothelial nitric oxide release.', 'Rapidly converted to active azilsartan during absorption; peak plasma concentration in 1.5 to 3 hours; 60% oral bioavailability; unaffected by food.', 'Volume of distribution approx. 16 L; highly bound to human plasma proteins (>99%, primarily albumin).', 'Metabolized in the liver primarily by CYP2C9 to an inactive metabolite M-II (O-dealkylation), and to a lesser extent by carboxylesterases to M-I (decarboxylation).', 'Excreted in faeces (approx. 55%) and urine (approx. 42%, with approx. 15% as unchanged active azilsartan).', 'Approximately 60%', '11 to 13 hours (receptor dissociation half-life is substantially longer)', '>99%', '1 to 2 hours', '24 hours', '[''Essential hypertension in adults (40 to 80 mg once daily)'', ''Resistant hypertension (in combination with chlorthalidone as Edarbyclor)'', ''Hypertension with elevated nocturnal or morning blood pressure surge'']', '[''Hypersensitivity to azilsartan medoxomil'', ''Pregnancy (all trimesters)'', ''Concomitant use of aliskiren in patients with diabetes'']', '[''Black box warning: Fetal toxicity; discontinue immediately when pregnancy is detected'', ''Hypotension in volume- or salt-depleted patients (correct volume before initiating)'', ''Hyperkalemia and renal impairment in bilateral renal artery stenosis'']', '[''Dizziness'', ''Diarrhoea'', ''Fatigue'', ''Asthenia'', ''Nausea'', ''Headache'']', '[''Acute kidney injury / elevation in serum creatinine'', ''Severe symptomatic hypotension / syncope'', ''Hyperkalemia (>5.5 mEq/L)'', ''Angioedema (rare)'']', '[''Potassium-sparing diuretics, potassium supplements (hyperkalemia risk)'', ''NSAIDs (blunt BP reduction, acute renal failure)'', ''Lithium'', ''CYP2C9 inhibitors/inducers'']', '[''Serum creatinine and eGFR at baseline and periodically'', ''Serum potassium levels'', ''24-hour ambulatory or home blood pressure monitoring'']', 'Black box warning: Strictly contraindicated in pregnancy (causes fetal hypotension, skull hypoplasia, and fetal demise).', 'Excreted in animal milk; breastfeeding not recommended.', 'Safety and efficacy not established in pediatric patients.', 'No initial dose adjustment required in elderly patients; monitor for orthostatic dizziness.', 'No dosage adjustment required in mild, moderate, or severe renal impairment or hemodialysis.', 'No dosage adjustment required in mild to moderate hepatic impairment; not studied in severe cirrhosis.', '[''Most potent 24-hour blood pressure reduction in the ARB class, superior to valsartan 320 mg and olmesartan 40 mg in head-to-head trials'', ''Exceptionally slow receptor dissociation provides sustained blood pressure control through the vulnerable morning surge period'', ''Zero dose adjustment needed across all stages of renal disease'']', '[''Significantly higher cost than generic telmisartan or losartan'', ''Strictly contraindicated in pregnancy'']', '[''Strongest blood pressure-lowering ARB on the market (superior to valsartan and olmesartan)'', ''Take once daily in the morning (40 mg or 80 mg) with or without food'']', 'AZIL-sartan: Absolute Zenith In Lowering blood pressure; Tightest AT1 binding; Zero morning surge.', '-sartan', 'a-ZIL-sar-tan', 'अज़िल-सारटन', 'active', 'verified', NULL, NULL),
('lercanidipine', 'Lercanidipine', 'Lercanidipine Hydrochloride', 'Lercanidipine hydrochloride', 'Lercanidipine hydrochloride', 'Cardiovascular', 'A highly lipophilic, third-generation dihydropyridine calcium channel blocker that integrates into the cell membrane lipid bilayer, providing smooth 24-hour vasodilation with minimal pedal oedema.', '[''10 mg'', ''20 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Inhibits transmembrane calcium influx through L-type calcium channels in vascular smooth muscle; high lipophilicity causes it to dissolve in the membrane lipid bilayer, creating a local drug reservoir that diffuses slowly to receptor sites.', 'Produces gradual, sustained peripheral arterial vasodilation without triggering reflex sympathetic activation or tachycardia; significantly lower incidence of dependent ankle oedema compared to amlodipine.', 'Completely absorbed from GI tract; undergoes substantial hepatic first-pass metabolism; peak plasma level in 1.5 to 3 hours; high-fat meals increase absorption 3- to 4-fold (take 15 minutes before meals).', 'Extensively distributed into vascular tissue; highly bound to plasma proteins (>98%).', 'Extensively metabolized in the liver by CYP3A4 to inactive metabolites; no active parent drug excreted.', 'Excreted predominantly as inactive metabolites in urine (approx. 50%) and faeces (approx. 50%).', 'Approximately 10% (fasting); increased significantly with meals', '8 to 10 hours in plasma; membrane lipid reservoir duration exceeds 24 hours', '>98%', '2 to 3 hours', '24 hours', '[''Mild to moderate essential hypertension'', ''Hypertension in patients who develop unacceptable ankle oedema on amlodipine'', ''Isolated systolic hypertension in the elderly'']', '[''Hypersensitivity to lercanidipine or dihydropyridines'', ''Severe left ventricular outflow obstruction (aortic stenosis)'', ''Unstable angina or within 1 month of myocardial infarction'', ''Severe renal (eGFR < 30 mL/min) or severe hepatic impairment'', ''Co-administration with strong CYP3A4 inhibitors'']', '[''Must be taken at least 15 minutes before meals (food drastically increases bioavailability)'', ''Avoid grapefruit juice (inhibits CYP3A4 metabolism)'', ''Gradually titrate dose'']', '[''Headache'', ''Facial flushing'', ''Dizziness'', ''Palpitations (rare)'', ''Peripheral oedema (much less than amlodipine)'']', '[''Severe hypotension / syncope'', ''Paradoxical angina in severe coronary artery disease'', ''Hepatotoxicity'']', '[''Strong CYP3A4 inhibitors (ketoconazole, itraconazole, clarithromycin - strictly contraindicated)'', ''Cyclosporine (increases levels of both drugs - avoid)'', ''Grapefruit juice (significantly elevates lercanidipine levels)'', ''Anticonvulsants (inducers decrease efficacy)'']', '[''Blood pressure sitting and standing'', ''Heart rate'', ''Inspection of ankles for pedal oedema'']', 'Contraindicated in pregnancy; animal studies demonstrate embryotoxicity and delayed labor.', 'Contraindicated during breastfeeding; high lipophilicity suggests excretion into breast milk.', 'Safety and efficacy not established in children under 18 years.', 'Initiate at 10 mg once daily; titrate cautiously; well tolerated in elderly hypertensives.', 'Use with caution in moderate renal impairment; contraindicated if eGFR < 30 mL/min.', 'Contraindicated in severe hepatic impairment; start at 10 mg in moderate liver disease.', '[''Significantly lower incidence of ankle pedal oedema compared to amlodipine (up to 50% fewer oedema dropouts)'', ''Lipophilic membrane reservoir provides smooth 24-hour blood pressure reduction without reflex tachycardia'', ''Renoprotective profile in hypertensive nephrosclerosis'']', '[''Bioavailability is heavily dependent on meals (must be taken 15 minutes before meals)'', ''Strictly contraindicated with strong CYP3A4 inhibitors and in severe renal/hepatic impairment'']', '[''Best alternative to amlodipine when patients suffer from swollen feet and ankles'', ''Always take 15 minutes before breakfast; avoid grapefruit juice'']', 'LERCA-nidipine: Lipophilic Embedding in cell membrane; Reduces Calf Ankle-oedema.', '-dipine', 'ler-ka-NI-di-peen', 'लेरका-निडिपिन', 'active', 'verified', NULL, NULL),
('felodipine', 'Felodipine', 'Felodipine', 'Felodipine', 'Felodipine', 'Cardiovascular', 'A second-generation dihydropyridine calcium channel blocker with exceptional vascular selectivity (100:1 vascular to cardiac smooth muscle ratio), used once daily in extended-release form for hypertension and angina.', '[''2.5 mg ER'', ''5 mg ER'', ''10 mg ER'']', '[''Extended-Release Tablet'']', '[''Oral'']', 'Selectively blocks voltage-gated L-type calcium channels in vascular smooth muscle cells, inhibiting calcium influx and causing arteriolar dilation; has 100-fold higher selectivity for vascular smooth muscle than myocardial tissue.', 'Reduces systemic vascular resistance and blood pressure without exerting negative inotropic effects on myocardial contractility; does not impair AV nodal conduction; causes mild natriuresis and diuresis without reflex renin stimulation.', 'Completely absorbed from GI tract; extended-release tablet provides smooth 24-hour plasma concentrations; extensive hepatic first-pass metabolism yields approx. 15% bioavailability; food does not affect bioavailability.', 'Apparent volume of distribution approx. 10 L/kg; extensively bound to plasma proteins (>99%, primarily albumin).', 'Extensively metabolized in the liver by CYP3A4 to inactive pyridine and carboxylic acid metabolites; no active metabolites.', 'Excreted in urine (approx. 70% as inactive metabolites) and faeces (approx. 10%); less than 0.5% unchanged in urine.', 'Approximately 15% (extended-release)', '11 to 16 hours', '>99%', '2 to 5 hours (extended release)', '24 hours', '[''Essential hypertension (alone or combined with beta-blockers or ACE inhibitors)'', ''Stable chronic angina pectoris'', ''Hypertension in elderly patients with isolated systolic hypertension'']', '[''Hypersensitivity to felodipine or dihydropyridine calcium channel blockers'', ''Cardiogenic shock or severe aortic stenosis'', ''Unstable angina or acute myocardial infarction'']', '[''Peripheral dependent oedema (dose-dependent precapillary vasodilation)'', ''Avoid grapefruit juice (massively increases felodipine bioavailability and hypotension)'', ''Gingival hyperplasia with prolonged therapy (maintain good oral hygiene)'', ''Do NOT crush or chew extended-release tablets'']', '[''Peripheral oedema (ankle swelling)'', ''Headache'', ''Facial flushing'', ''Dizziness'', ''Palpitations'']', '[''Severe symptomatic hypotension / syncope'', ''Paradoxical worsening of angina in severe obstructive CAD'', ''Severe gingival enlargement'']', '[''Grapefruit juice (drastically inhibits intestinal CYP3A4, doubling felodipine levels; avoid completely)'', ''CYP3A4 inhibitors (cimetidine, erythromycin, ketoconazole - increase felodipine exposure)'', ''CYP3A4 inducers (carbamazepine, phenytoin, rifampin - reduce efficacy)'']', '[''Blood pressure and heart rate'', ''Inspection of lower extremities for pedal oedema'', ''Dental examination for gingival hyperplasia'']', 'Category C; teratogenic in animal studies; avoid during pregnancy unless benefit clearly outweighs risk.', 'Excreted in human milk; compatible with caution or alternative agent.', 'Safety and efficacy not established in pediatric patients.', 'Initiate at 2.5 mg ER once daily; elderly patients exhibit higher plasma levels due to decreased clearance.', 'No dosage adjustment required in renal impairment or hemodialysis.', 'Initiate with 2.5 mg once daily in patients with hepatic impairment (metabolized by CYP3A4).', '[''100-fold vascular selectivity ensures safe blood pressure reduction without depressing heart muscle pump function'', ''True 24-hour extended-release formulation provides consistent blood pressure control'', ''Safe in patients with asthma, diabetes, and gout'']', '[''High rate of ankle pedal oedema at higher doses (10 mg ER)'', ''Severe food interaction with grapefruit juice'']', '[''Take once daily in the morning; swallow whole and never crush or chew the tablet'', ''Never drink grapefruit juice while taking felodipine'']', 'FELO-dipine: Fully Extended 24h release; Leaves Myocardium alone (100:1 vascular selectivity); Outlaw Grapefruit.', '-dipine', 'fe-LOE-di-peen', 'फ़ेलो-डिपिन', 'active', 'verified', NULL, NULL),
('nitrendipine', 'Nitrendipine', 'Nitrendipine', 'Nitrendipine', 'Nitrendipine', 'Cardiovascular', 'A classical dihydropyridine calcium channel blocker proven in the landmark Syst-Eur trial to reduce stroke by 42% and vascular dementia by 50% in elderly patients with isolated systolic hypertension.', '[''10 mg'', ''20 mg'']', '[''Tablet'']', '[''Oral'']', 'Inhibits L-type calcium channel current in vascular smooth muscle, decreasing intracellular calcium availability and producing arteriolar vasodilation and reduced total peripheral resistance.', 'Reduces systolic and diastolic blood pressure, improves arterial compliance, and preserves cerebral blood flow; landmark Syst-Eur trial proved a 42% reduction in stroke and a 50% reduction in vascular dementia in seniors.', 'Rapidly absorbed (approx. 80%); extensive hepatic first-pass metabolism limits bioavailability to 10-20%; peak plasma level in 1 to 2 hours.', 'Widely distributed; 98% bound to plasma albumin.', 'Extensively metabolized in the liver by CYP3A4 via oxidation to inactive metabolites.', 'Excreted predominantly in urine (approx. 75% as metabolites) and faeces (approx. 10%).', '10% to 20%', '8 to 12 hours', '98%', '1 to 2 hours', '12 to 24 hours', '[''Isolated systolic hypertension in elderly patients (Syst-Eur trial proven)'', ''Essential hypertension in adults'', ''Prevention of cerebrovascular events in senior hypertensives'']', '[''Hypersensitivity to nitrendipine or dihydropyridines'', ''Severe cardiogenic shock or advanced aortic stenosis'', ''Unstable angina'']', '[''Peripheral oedema and flushing'', ''Avoid grapefruit juice (CYP3A4 inhibition)'', ''Dose reduction in hepatic cirrhosis'']', '[''Headache'', ''Facial flushing'', ''Peripheral oedema'', ''Palpitations'', ''Dizziness'']', '[''Severe hypotension'', ''Paradoxical myocardial ischemia'', ''Allergic hepatitis (rare)'']', '[''CYP3A4 inhibitors (ketoconazole, erythromycin - increase levels)'', ''CYP3A4 inducers (rifampin, carbamazepine)'', ''Beta-blockers (synergistic hypotensive effect)'']', '[''Blood pressure sitting and standing'', ''Cognitive evaluation in elderly patients'', ''Ankle inspection for oedema'']', 'Avoid in pregnancy; insufficient human safety data; use labetalol or nifedipine.', 'Excreted in breast milk in trace amounts; avoid breastfeeding.', 'Safety and efficacy not established in children.', 'First-line agent in elderly patients with isolated systolic hypertension (Syst-Eur trial demonstrated 42% stroke reduction).', 'No dosage adjustment required in renal impairment.', 'Dose reduction required in severe hepatic impairment (start at 5-10 mg daily).', '[''Landmark Syst-Eur trial proven: 42% reduction in stroke and 50% reduction in dementia in elderly patients'', ''Mild intrinsic natriuretic action reduces the need for high-dose diuretics'', ''Preserves cerebral blood flow in senior hypertensives'']', '[''Short half-life may require twice-daily dosing in some patients'', ''High incidence of flushing and ankle oedema'']', '[''Proven to cut stroke risk by 42% and dementia risk by 50% in elderly patients (Syst-Eur trial)'', ''Take once or twice daily with water; avoid grapefruit juice'']', 'NITREN-dipine: Notable In The Reduction of Elderly Neurological events (stroke & dementia - Syst-Eur).', '-dipine', 'nye-TREN-di-peen', 'नाइट्रेन-डिपिन', 'active', 'verified', NULL, NULL),
('metolazone', 'Metolazone', 'Metolazone', 'Metolazone', 'Metolazone', 'Cardiovascular', 'A potent quinazoline-sulfonamide diuretic that acts on the proximal and distal tubules, uniquely retaining efficacy even in advanced renal failure (eGFR < 30 mL/min) and creating massive synergy with loop diuretics.', '[''2.5 mg'', ''5 mg'']', '[''Tablet'']', '[''Oral'']', 'Inhibits sodium and chloride reabsorption in the cortical diluting segment of the distal convoluted tubule and proximal tubule; unique quinazoline structure allows it to remain active at low glomerular filtration rates.', 'Produces potent natriuresis, chloruresis, and diuresis; when combined with loop diuretics (furosemide/torsemide), creates ''sequential nephron blockade'', overcoming refractory diuretic resistance in severe heart failure and nephrotic syndrome.', 'Slowly and incompletely absorbed (approx. 65%); peak plasma concentration in 2 to 4 hours; bioavailability varies significantly between formulations.', 'Distributes into extracellular water and erythrocytes; 95% bound to plasma proteins.', 'Minimal hepatic metabolism; not cleared by CYP450 enzymes.', 'Excreted predominantly unchanged in urine via active secretion (approx. 80-90%); remainder eliminated in bile.', 'Approximately 65%', '8 to 14 hours (terminal half-life prolonged up to 20 hours)', '95%', 'Diuresis begins within 1 hour; peak effect in 2 to 4 hours', '12 to 24 hours', '[''Diuretic resistance in congestive heart failure (sequential nephron blockade combined with loop diuretics)'', ''Oedema associated with renal disease, including nephrotic syndrome and chronic renal failure (eGFR < 30 mL/min)'', ''Essential hypertension (second-line add-on)'']', '[''Anuria'', ''Hepatic coma or pre-coma'', ''Known hypersensitivity to metolazone or sulfonamides'', ''Severe uncorrected electrolyte depletion (hypokalemia, hyponatremia)'']', '[''PROFOUND ELECTROLYTE COLLAPSE: Sequential nephron blockade with loop diuretics can produce massive volume depletion, life-threatening hypokalemia (<2.5 mEq/L), and acute renal failure within 48 hours (monitor daily in hospital)'', ''Hyperuricemia and acute gout precipitation'', ''Hyperglycemia in diabetics'']', '[''Hypokalemia (very common)'', ''Hyponatremia'', ''Hypochloremic alkalosis'', ''Dizziness / orthostatic hypotension'', ''Hyperuricemia'']', '[''Life-threatening hypokalemic cardiac arrhythmias'', ''Severe volume depletion / circulatory shock'', ''Acute kidney injury'', ''Stevens-Johnson syndrome'']', '[''Loop diuretics (furosemide, bumetanide, torsemide - dramatic synergistic diuresis; start with tiny 2.5 mg metolazone doses)'', ''Digoxin (hypokalemia massively increases digitalis toxicity and arrhythmias)'', ''Lithium (decreases lithium clearance, causing toxicity)'', ''NSAIDs'']', '[''Serum electrolytes (potassium, sodium, chloride) daily during combination therapy'', ''BUN and serum creatinine daily during acute diuresis'', ''Daily weight and strict fluid balance'', ''Blood pressure'']', 'Category B; diuretics are generally avoided in pregnancy due to maternal hypovolemia and placental insufficiency.', 'Excreted in breast milk; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Extreme sensitivity to volume depletion; start with 2.5 mg every other day or twice weekly.', 'EFFECTIVE IN SEVERE RENAL FAILURE (eGFR < 30 mL/min), unlike traditional thiazide diuretics; monitor electrolytes closely.', 'Use with extreme caution; minor electrolyte shifts can precipitate hepatic encephalopathy.', '[''Uniquely effective at low GFR (eGFR < 30 mL/min) where traditional thiazides fail completely'', ''Gold standard booster for loop diuretic resistance in refractory heart failure (sequential nephron blockade)'', ''Long 24-hour duration of action'']', '[''Massive risk of life-threatening hypokalemia and dehydration when combined with loop diuretics'', ''Requires hospital-level daily electrolyte monitoring during initiation'']', '[''Secret weapon for refractory fluid overload: pairs with furosemide to overcome diuretic resistance'', ''DANGER: Can cause massive potassium loss; check potassium and kidney function within 48 hours'']', 'METOLA-zone: Magnificent Extra-strength Tubule Overload Lifter; Active in Low GFR; Beware Potassium.', '-zone', 'me-TOE-la-zone', 'मेटोला-ज़ोन', 'active', 'verified', NULL, NULL),
('acetazolamide', 'Acetazolamide', 'Acetazolamide', 'Acetazolamide', 'Acetazolamide', 'Cardiovascular', 'A prototypical carbonic anhydrase inhibitor that blocks bicarbonate reabsorption in the proximal tubule, used for acute mountain sickness, glaucoma, metabolic alkalosis, and idiopathic intracranial hypertension.', '[''250 mg'', ''500 mg SR'', ''500 mg IV vial'']', '[''Tablet'', ''Extended-Release Capsule'', ''Powder for Injection'']', '[''Oral'', ''Intravenous'']', 'Non-competitively and reversibly inhibits carbonic anhydrase (predominantly CA-II and CA-IV) in the renal proximal tubule, ciliary body of the eye, and choroid plexus; blocks H+ ion exchange for Na+, promoting urinary excretion of bicarbonate, sodium, potassium, and water.', 'Produces hyperchloremic metabolic acidosis, stimulating central chemoreceptors to increase ventilation (countering periodic breathing at high altitude); decreases aqueous humor production (lowers IOP) and reduces CSF production.', 'Rapidly and well absorbed from GI tract (approx. 90-100%); peak plasma concentrations in 1 to 3 hours (oral tablet).', 'Concentrates heavily in erythrocytes and renal cortex (binds to carbonic anhydrase); crosses blood-brain barrier and placenta; 90-95% bound to plasma proteins.', 'Not metabolized by the liver; excreted unaltered by the kidneys.', 'Excreted entirely unchanged in urine via tubular secretion and filtration (approx. 90-100% within 24 hours).', '90% to 100%', '6 to 9 hours (tablets); 12 hours (sustained release)', '90% to 95%', 'Oral: 1 to 1.5 hours; IV: 2 minutes', 'Oral: 8 to 12 hours; IV: 4 to 5 hours', '[''Prevention and treatment of acute mountain sickness (AMS / altitude sickness: 125-250 mg BID starting 24h before ascent)'', ''Open-angle glaucoma and acute angle-closure glaucoma (lowers intraocular pressure)'', ''Idiopathic intracranial hypertension (pseudotumor cerebri)'', ''Severe metabolic alkalosis (restores bicarbonate excretion)'', ''Absence seizures (refractory adjuvant)'']', '[''Severe hypersensitivity to acetazolamide or sulfonamides'', ''Severe renal impairment (eGFR < 10 mL/min)'', ''Severe hepatic disease / cirrhosis (induces hepatic encephalopathy by preventing ammonia clearance)'', ''Marked hypokalemia or hyponatremia'', ''Chronic non-congestive closed-angle glaucoma'', ''Hyperchloremic acidosis'']', '[''Hyperchloremic metabolic acidosis and severe hypokalemia'', ''Sulfonamide allergy cross-reactivity (Stevens-Johnson syndrome, blood dyscrasias)'', ''Calcium phosphate kidney stones (due to reduced urinary citrate and alkaline urine)'', ''Drowsiness and paresthesias in extremities'']', '[''Paresthesias (numbness and tingling in fingers, toes, and lips - very common)'', ''Dysgeusia (carbonated drinks taste flat/metallic due to tongue carbonic anhydrase inhibition)'', ''Polyuria'', ''Fatigue'', ''Dizziness'', ''Anorexia'']', '[''Severe hyperchloremic metabolic acidosis'', ''Aplastic anaemia / agranulocytosis'', ''Stevens-Johnson syndrome / TEN'', ''Calcium phosphate nephrolithiasis'', ''Hepatic encephalopathy in cirrhotics'']', '[''High-dose aspirin / salicylates (severe toxicity: metabolic acidosis causes aspirin to enter brain)'', ''Lithium (increases lithium excretion, reducing efficacy)'', ''Topiramate (additive carbonic anhydrase inhibition and stone risk)'', ''Quinidine, amphetamines'']', '[''Serum electrolytes (potassium, bicarbonate) at baseline and periodically'', ''Complete blood counts (screen for bone marrow suppression)'', ''Urinalysis for crystals / stone formation'']', 'Category C; teratogenic in animal models; avoid during first trimester; use for altitude sickness only if clearly needed.', 'Excreted in breast milk in low concentrations; compatible with caution.', 'Approved in children for glaucoma and epilepsy (8 to 30 mg/kg/day divided every 8 hours).', 'Higher risk of metabolic acidosis and hypokalemia; reduce dose based on eGFR.', 'Dose adjustment required based on eGFR: eGFR 10-50 mL/min: dose every 12 hours; eGFR < 10 mL/min: contraindicated.', 'Strictly contraindicated in severe hepatic disease (triggers ammonia-mediated hepatic coma).', '[''Gold standard preventive drug for acute mountain sickness (AMS) and high-altitude pulmonary/cerebral oedema'', ''Rapidly lowers intraocular pressure in acute glaucoma emergencies'', ''Corrects metabolic alkalosis in ICU patients with COPD'']', '[''Characteristic tingling in fingers/toes and makes soda/carbonated beverages taste flat'', ''Risk of calcium kidney stones and metabolic acidosis'']', '[''Start 125 mg twice daily 24 hours before climbing above 8,000 feet to prevent altitude sickness'', ''Tell patients that tingling in fingers and flat-tasting soda are normal, harmless side effects'']', 'ACETA-ZOLAMIDE: Altitude sickness Altitude climb; Carbonic anhydrase block; Eyes (glaucoma); Tingling toes; Acidosis.', '-zolamide', 'a-see-ta-ZOLE-a-mide', 'एसिटा-ज़ोलामाइड', 'active', 'verified', NULL, NULL),
('isosorbide-mononitrate', 'Isosorbide Mononitrate (ISMN)', 'Isosorbide Mononitrate Sustained Release', 'Isosorbide mononitrate', 'Isosorbide mononitrate', 'Cardiovascular', 'An active organic nitrate vasodilator with 100% oral bioavailability and zero hepatic first-pass metabolism, providing predictable long-term prophylaxis for stable coronary artery disease.', '[''20 mg'', ''30 mg SR'', ''60 mg SR'']', '[''Tablet'', ''Sustained-Release Tablet'']', '[''Oral'']', 'Denitrated intracellularly in vascular smooth muscle to release nitric oxide (NO); NO stimulates soluble guanylyl cyclase, increasing cyclic GMP (cGMP), leading to dephosphorylation of myosin light chains and marked venodilation.', 'Dilates systemic veins (reducing venous return, preload, and left ventricular wall tension) and epicardial coronary arteries, substantially decreasing myocardial oxygen demand; does NOT develop tolerance when an eccentric dosing schedule is used.', 'Rapidly and completely absorbed from GI tract; 100% absolute oral bioavailability; zero hepatic first-pass metabolism; food does not affect absorption.', 'Apparent volume of distribution approx. 0.6 L/kg; minimal plasma protein binding (<5%).', 'Metabolized in the liver by denitration to inactive isosorbide and by glucuronidation to isosorbide mononitrate glucuronide.', 'Excreted almost entirely in urine as inactive metabolites (approx. 93%); less than 2% unchanged in urine.', '100% (predictable, unlike isosorbide dinitrate)', '5 hours (immediate release); extended release delivers therapeutic levels over 12 hours with a mandatory 12-hour nitrate-free interval', '<5%', 'Immediate release: 30 to 60 minutes; SR: 2 to 4 hours', 'Immediate release: 6 to 8 hours; SR: 12 to 14 hours', '[''Prophylaxis of chronic stable angina pectoris (coronary artery disease)'', ''Adjunct therapy in chronic congestive heart failure (combined with hydralazine)'', ''Secondary prevention in post-myocardial infarction angina'']', '[''Concurrent use of phosphodiesterase-5 (PDE5) inhibitors (sildenafil, tadalafil, vardenafil - FATAL HYPOTENSION)'', ''Concurrent use of soluble guanylyl cyclase stimulators (riociguat)'', ''Severe hypotension (systolic BP < 90 mmHg) or severe hypovolemia'', ''Hypertrophic obstructive cardiomyopathy (HOCM)'', ''Constrictive pericarditis or cardiac tamponade'']', '[''FATAL INTERACTION WITH PDE5 INHIBITORS: Co-administration with sildenafil or tadalafil can cause catastrophic, refractory circulatory collapse and fatal myocardial infarction'', ''NITRATE TOLERANCE: Continuous 24-hour exposure causes complete loss of antianginal efficacy; a mandatory 10- to 12-hour nitrate-free interval every day is required'', ''Severe nitrate headache during initial days (treat with paracetamol; do not stop therapy)'']', '[''Throbbing headache (very common during first 1-2 weeks)'', ''Flushing'', ''Dizziness / postural hypotension'', ''Weakness'', ''Nausea'']', '[''Severe refractory hypotension / syncope'', ''Paradoxical bradycardia'', ''Precipitation of myocardial ischemia from reflex tachycardia in severe CAD'']', '[''PDE5 inhibitors (sildenafil within 24h, tadalafil within 48h - STRICTLY CONTRAINDICATED)'', ''Riociguat (contraindicated)'', ''Alcohol (severe orthostatic hypotension and syncope)'', ''Antihypertensives (additive hypotension)'']', '[''Blood pressure and heart rate sitting and standing'', ''Frequency of angina episodes and sublingual nitroglycerin use'', ''Compliance with the nitrate-free interval'']', 'Category C; use during pregnancy only if clearly needed and benefits justify potential fetal risks.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Safety and efficacy not established in pediatric patients.', 'Higher risk of orthostatic dizziness and falls; start with 30 mg SR once daily in the morning.', 'No dosage adjustment required in renal impairment.', 'No dosage adjustment required in mild to moderate hepatic impairment.', '[''100% oral bioavailability with zero first-pass metabolism guarantees predictable antianginal blood levels'', ''Once-daily extended-release tablet (taken in morning) automatically provides the required overnight nitrate-free window to prevent tolerance'', ''Proven reduction in angina frequency and exercise tolerance'']', '[''Throbbing nitrate headache occurs in up to 50% during initiation'', ''Strictly contraindicated with Viagra/Cialis (lethal hypotension)'']', '["Take once daily in the MORNING so the body has an overnight ''nitrate-free'' window to prevent tolerance", ''NEVER take with sildenafil (Viagra) or tadalafil (Cialis)—combination can be fatal'']', 'ISMN: 100% Bioavailable; Single Morning dose; Mandatory 12h nitrate-free window; No PDE5 inhibitors.', '-nitrate', 'eye-soe-SOR-bide mon-oh-NYE-trate', 'आइसोसोरबाइड मोनोनाइट्रेट', 'active', 'verified', NULL, NULL),
('isosorbide-dinitrate', 'Isosorbide Dinitrate (ISDN)', 'Isosorbide Dinitrate', 'Isosorbide dinitrate', 'Isosorbide dinitrate', 'Cardiovascular', 'An organic nitrate vasodilator used sublingually for acute angina relief and orally combined with hydralazine (BiDil) to significantly reduce mortality in Black patients with heart failure (A-HeFT trial).', '[''5 mg sublingual'', ''10 mg'', ''20 mg'', ''40 mg SR'']', '[''Sublingual Tablet'', ''Immediate-Release Tablet'', ''Sustained-Release Tablet'']', '[''Sublingual'', ''Oral'']', 'Releases free nitric oxide in vascular smooth muscle, stimulating guanylyl cyclase to produce cGMP; selectively dilates venous capacitance vessels to decrease preload, and dilates large epicardial coronary arteries.', 'Relieves acute myocardial ischemia; combined with hydralazine, provides nitric oxide donation while hydralazine prevents nitrate tolerance and scavenges free radicals (A-HeFT trial mortality reduction in African Americans).', 'Sublingual: rapidly absorbed into systemic circulation (peak in 10-15 minutes); Oral: heavily metabolized by hepatic first-pass (bioavailability 20-25%).', 'Widely distributed; active metabolites 5-ISMN and 2-ISMN distribute to vascular tissues; <28% protein bound.', 'Extensively metabolized in the liver to two active metabolites: isosorbide-5-mononitrate (5-ISMN, longer-acting) and isosorbide-2-mononitrate (2-ISMN).', 'Excreted in urine (approx. 80-90% as glucuronide metabolites and free mononitrates).', 'Sublingual: 40-50%; Oral: 20-25% (due to high hepatic first-pass clearance)', 'Parent ISDN: 1 hour; active 5-ISMN metabolite: 5 hours', '<28%', 'Sublingual: 2 to 5 minutes; Oral: 20 to 40 minutes', 'Sublingual: 1 to 2 hours; Oral: 4 to 6 hours', '[''Treatment and prevention of acute angina pectoris (sublingual formulation)'', ''Adjunct treatment of heart failure with reduced ejection fraction in Black patients, combined with hydralazine (A-HeFT trial: 43% reduction in mortality)'', ''Chronic angina prophylaxis (oral formulation)'']', '[''Concurrent use of PDE5 inhibitors (sildenafil, tadalafil - LETHAL HYPOTENSION)'', ''Severe hypotension (systolic BP < 90 mmHg)'', ''Severe hypovolemia or cardiogenic shock'', ''Constrictive pericarditis and cardiac tamponade'']', '[''Fatal hypotension with PDE5 inhibitors (sildenafil within 24h, tadalafil within 48h)'', ''Nitrate tolerance: require 14-hour nitrate-free interval for chronic oral dosing (e.g., dose at 7 AM, 12 PM, 5 PM, none overnight)'', ''Severe throbbing nitrate headache'']', '[''Headache'', ''Lightheadedness'', ''Flushing'', ''Postural hypotension'', ''Tachycardia'']', '[''Severe life-threatening hypotension / syncope'', ''Paradoxical bradycardia'', ''Reflex myocardial ischemia'']', '[''PDE5 inhibitors (sildenafil, tadalafil, vardenafil - contraindicated)'', ''Riociguat (contraindicated)'', ''Alcohol (severe hypotension)'', ''Antihypertensives'']', '[''Blood pressure and heart rate'', ''Angina attack frequency'', ''Compliance with TID eccentric schedule (7 AM, 12 PM, 5 PM)'']', 'Category C; use during pregnancy only if clearly needed.', 'Excretion in human milk unknown; use caution.', 'Safety and efficacy not established in pediatric patients.', 'Start at lowest dose (5-10 mg TID); high risk of orthostatic falls.', 'No dosage adjustment required in renal impairment.', 'Dose titration required in severe hepatic cirrhosis (reduced first-pass clearance elevates ISDN levels).', '[''Sublingual form acts within 2 to 5 minutes for acute angina relief'', ''Landmark A-HeFT trial proven: combined with hydralazine, cuts heart failure mortality by 43% in Black patients'', ''Cost-effective, established cardiovascular therapy'']', '[''Low and erratic oral bioavailability compared to isosorbide mononitrate'', ''Requires complex TID eccentric dosing (7 AM - 12 PM - 5 PM) to prevent tolerance'']', '[''Sublingual tablet dissolves under the tongue in 2 minutes for chest pain relief'', ''If taking oral tablets 3 times daily, space them at 7 AM, 12 PM, and 5 PM so night is nitrate-free'']', 'ISDN: Immediate Sublingual Dissolution for Need; Needs nitrate-free night; Never mix with PDE5 inhibitors.', '-nitrate', 'eye-soe-SOR-bide dye-NYE-trate', 'आइसोसोरबाइड डाइनाइट्रेट', 'active', 'verified', NULL, NULL),
('nitroglycerin', 'Nitroglycerin (Glyceryl Trinitrate - GTN)', 'Nitroglycerin (Glyceryl Trinitrate)', 'Nitroglycerin', 'Nitroglycerin', 'Cardiovascular', 'The foundational rapid-acting organic nitrate vasodilator used sublingually for immediate termination of acute angina attacks and intravenously for acute heart failure, pulmonary oedema, and hypertensive emergencies.', '[''0.4 mg (400 mcg) sublingual tablet'', ''0.4 mg/metered dose sublingual spray'', ''5 mg/mL (5 mL, 10 mL IV ampoules)'', ''2.5 mg, 6.5 mg sustained release'', ''5 mg/24h, 10 mg/24h transdermal patch'', ''2% ointment'']', '[''Sublingual Tablet'', ''Sublingual Aerosol Spray'', ''Solution for Injection / Infusion'', ''Transdermal Patch'', ''Topical Ointment'']', '[''Sublingual'', ''Intravenous'', ''Transdermal'', ''Topical'']', 'Denitrated in vascular smooth muscle by mitochondrial aldehyde dehydrogenase (ALDH-2) to release nitric oxide (NO); stimulates guanylyl cyclase, increasing intracellular cGMP and causing profound venous dilation, lowering preload and ventricular wall stress; dilates coronary collaterals.', 'Rapidly aborts acute myocardial ischemia within 1 to 3 minutes; decreases left ventricular end-diastolic pressure and pulmonary capillary wedge pressure, relieving acute cardiogenic pulmonary oedema.', 'Sublingual: rapidly and completely absorbed through oral mucosa directly into systemic circulation (bypasses hepatic first-pass); Oral swallowed: >99% destroyed by hepatic first-pass metabolism (bioavailability <1%).', 'Widely distributed; volume of distribution approx. 3 L/kg; 60% bound to plasma proteins.', 'Extensively metabolized by red blood cell and liver glutathione-dependent organic nitrate reductase into dinitrate and mononitrate metabolites with much lower vasodilator activity.', 'Excreted in urine as inactive glucuronide conjugates.', 'Sublingual: approx. 40%; Transdermal: 75%; Oral: <1%', '1 to 4 minutes (ultra-short half-life enables minute-to-minute IV titration)', '60%', 'Sublingual: 1 to 3 minutes; IV: immediate (1 to 2 minutes); Transdermal: 30 to 60 minutes', 'Sublingual: 20 to 30 minutes; IV: 3 to 5 minutes after stopping infusion; Patch: 12 hours (remove for 12h daily)', '[''Immediate relief of acute angina pectoris attacks (0.4 mg sublingual tablet or spray every 5 minutes up to 3 doses)'', ''Prophylaxis of angina taken 5 to 10 minutes prior to physical exertion or emotional stress'', ''Acute decompensated heart failure with pulmonary oedema (IV continuous infusion)'', ''Unstable angina and acute myocardial infarction (IV infusion)'', ''Hypertensive emergency with acute left ventricular failure'']', '[''Concurrent use of PDE5 inhibitors (sildenafil/vardenafil within 24 hours, tadalafil within 48 hours - LETHAL HYPOTENSION)'', ''Severe hypotension (systolic BP < 90 mmHg or >30 mmHg below baseline)'', ''Severe bradycardia (<50 bpm) or marked tachycardia (>100 bpm in absence of heart failure)'', ''Right ventricular myocardial infarction (inferior MI with RV involvement - profound drop in preload precipitates cardiogenic shock)'', ''Increased intracranial pressure or cerebral hemorrhage'', ''Severe aortic stenosis or obstructive cardiomyopathy'']', '[''CRITICAL RULE: Never administer in suspected RIGHT VENTRICULAR INFARCTION (leads to catastrophic shock due to preload dependence)'', ''FATAL INTERACTION WITH PDE5 INHIBITORS (Viagra/Cialis)'', ''Call emergency medical services (ambulance) if chest pain is not relieved or worsens 5 minutes after the first sublingual dose'', ''Transdermal patches must be removed for 10-12 hours daily (usually at bedtime) to avoid complete nitrate tolerance'', ''Glass bottles and non-PVC infusion tubing required for IV infusion (absorbs into regular PVC plastic bags)'']', '[''Throbbing headache (very common)'', ''Facial flushing'', ''Dizziness / lightheadedness'', ''Postural hypotension'', ''Reflex tachycardia'']', '[''Severe catastrophic circulatory collapse / refractory shock'', ''Paradoxical bradycardia and syncope'', ''Severe methemoglobinemia (rare with high-dose prolonged IV infusions)'']', '[''Phosphodiesterase-5 inhibitors (sildenafil, tadalafil, vardenafil - ABSOLUTELY CONTRAINDICATED)'', ''Riociguat (contraindicated)'', ''Alcohol (severe hypotension)'', ''Antihypertensives, beta-blockers, calcium channel blockers (additive hypotension)'']', '[''Blood pressure and heart rate before and 5 minutes after each sublingual dose'', ''Continuous arterial pressure and telemetry during IV infusion'', ''Keep sublingual tablets in original amber glass bottle tightly capped (evaporates and loses potency in plastic pillboxes)'']', 'Category C; widely used in maternal hypertensive emergencies and acute pulmonary oedema with close fetal monitoring.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Safety and efficacy established in pediatric intensive care for afterload reduction (0.5-5 mcg/kg/min IV).', 'Extreme susceptibility to orthostatic hypotension and syncope; patient must always sit down before taking sublingual dose.', 'No dosage adjustment required in renal failure.', 'No dosage adjustment required in hepatic disease.', '[''World standard first-line emergency rescue medication for acute angina attacks, relieving pain within 1 to 3 minutes'', ''Minute-to-minute titratability via IV infusion makes it the premier agent for acute cardiogenic pulmonary oedema'', ''Multiple delivery routes (sublingual tablets, spray, transdermal patch, IV)'']', '[''Volatile drug: sublingual tablets lose potency rapidly if exposed to air, moisture, or plastic pillboxes'', ''Continuous exposure causes total nitrate tolerance within 24-48 hours'', ''Contraindicated in right ventricular infarction'']', '[''Sit down before taking sublingual nitroglycerin to prevent fainting; dissolve under the tongue without swallowing'', ''If chest pain persists 5 minutes after the first dose, CALL AN AMBULANCE immediately before taking a second dose'', ''Keep tablets in the original amber glass bottle; replace every 6 months after opening'']', 'NITRO-glycerin: Number 1 In Terminating angina Rapidly; Outlawed in Right-ventricular MI; Sit down before dosing.', '-glycerin', 'nye-troe-GLIS-er-in', 'नाइट्रो-ग्लिसरीन', 'active', 'verified', NULL, NULL),
('nicorandil', 'Nicorandil', 'Nicorandil', 'Nicorandil', 'Nicorandil', 'Cardiovascular', 'A dual-action potassium channel opener and organic nitrate donor that provides balanced arterial and venous dilation without developing nitrate tolerance, proven to reduce major coronary events (IONA study).', '[''5 mg'', ''10 mg'']', '[''Scored Tablet'']', '[''Oral'']', 'Dual mechanism: opens ATP-sensitive potassium channels (K-ATP) in arterial smooth muscle causing hyperpolarization and arteriolar dilation (reduces afterload and mimics ischemic preconditioning), AND contains a nitrate moiety that donates nitric oxide (NO) causing venodilation (reduces preload) and coronary vasodilation.', 'Improves coronary collateral blood flow, reduces myocardial oxygen demand, prevents myocardial stunning, and confers ischemic preconditioning; does NOT develop classical nitrate tolerance (IONA study: 17% reduction in major coronary events).', 'Rapidly and completely absorbed from GI tract (approx. 75-80% bioavailability); peak plasma concentration in 30 to 60 minutes; unaffected by food.', 'Apparent volume of distribution approx. 1.0 to 1.4 L/kg; low plasma protein binding (approx. 25%).', 'Extensively metabolized in the liver mainly by denitration into inactive nicotinamide and subsequent incorporation into NAD/NADP pathways.', 'Excreted predominantly in urine (approx. 20% as metabolites within 24 hours); less than 1% unchanged drug.', '75% to 80%', '1 hour (effective therapeutic duration 12 hours)', '25%', '30 to 60 minutes', '12 hours (dosed twice daily)', '[''Prevention and long-term treatment of chronic stable angina pectoris (second-line add-on to beta-blockers/CCBs)'', ''Refractory angina pectoris when conventional therapies are insufficient or contraindicated'', ''Microvascular angina'']', '[''Concurrent use of phosphodiesterase-5 (PDE5) inhibitors (sildenafil, tadalafil - FATAL HYPOTENSION)'', ''Concurrent use of soluble guanylyl cyclase stimulators (riociguat)'', ''Severe hypotension or cardiogenic shock'', ''Acute pulmonary oedema'']', '[''GASTROINTESTINAL AND CUTANEOUS ULCERATION: Nicorandil can cause severe, refractory, persistent aphthous ulcers in the mouth, stomach, small intestine, colon, anus, and cornea; ulcers DO NOT HEAL until nicorandil is completely discontinued'', ''Risk of intestinal perforation and severe GI bleeding from ulcers'', ''Headache during first week of therapy'']', '[''Headache (very common during initial therapy, diminishes over time)'', ''Dizziness'', ''Cutaneous flushing'', ''Nausea'', ''Mouth ulcers'']', '[''Severe gastrointestinal ulceration / intestinal perforation'', ''Refractory anal and perianal ulceration'', ''Corneal ulceration'', ''Severe hypotension'']', '[''PDE5 inhibitors (sildenafil, tadalafil - strictly contraindicated due to lethal hypotension)'', ''Riociguat (contraindicated)'', ''Corticosteroids, NSAIDs, or aspirin (greatly increase risk of severe GI ulceration and perforation)'', ''Antihypertensives (additive blood pressure lowering)'']', '[''Careful inspection for persistent mouth ulcers, skin ulcers, or perianal ulceration (stop drug immediately if found)'', ''Complete blood count and stool for occult blood'', ''Blood pressure sitting and standing'']', 'Avoid in pregnancy; insufficient human safety data; use only if potential benefit justifies potential risk.', 'Excretion in breast milk unknown; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Initiate at 5 mg twice daily; titrate up to 10-20 mg twice daily.', 'No dosage adjustment required in renal impairment.', 'No dosage adjustment required in hepatic disease.', '[''Dual-action potassium channel opener and nitric oxide donor providing comprehensive preload and afterload reduction'', ''Does not develop classical nitrate tolerance'', ''Proven 17% reduction in major coronary events in chronic angina (IONA trial)'']', '[''Causes refractory gastrointestinal and mucosal ulceration that only resolves after stopping the drug'', ''Strictly contraindicated with PDE5 inhibitors'']', '[''Dual-action antianginal that opens potassium channels and releases nitric oxide'', ''STOP THE DRUG IMMEDIATELY if you develop persistent mouth ulcers, stomach pain, or anal sores'']', 'NICOR-andil: Nitrate and K-channel opener; Increases collateral flow; Caution: Causes Cavity/mouth ulcers.', '-andil', 'nye-KOR-an-dil', 'निकोरा-न्डिल', 'active', 'verified', NULL, NULL),
('ranolazine', 'Ranolazine', 'Ranolazine Extended-Release', 'Ranolazine', 'Ranolazine', 'Cardiovascular', 'A first-in-class late inward sodium current (INa-late) inhibitor that reduces intracellular calcium overload in ischemic cardiomyocytes, improving myocardial perfusion without lowering heart rate or blood pressure.', '[''500 mg ER'', ''1000 mg ER'']', '[''Extended-Release Tablet'']', '[''Oral'']', 'Selectively inhibits the late inward sodium current (late INa) in ischemic myocardial cells, preventing sodium accumulation, reversing reverse Na+/Ca2+ exchange, and attenuating intracellular calcium overload; reduces diastolic wall tension and mechanical compression of microvascular coronary vessels.', 'Improves myocardial perfusion during diastole and reduces anginal symptoms and nitrate consumption without reducing heart rate, inotropic contractility, or systemic blood pressure; causes mild dose-dependent QTc prolongation.', 'Variable absorption; 73% systemic availability of extended-release tablet; peak plasma concentration in 2 to 5 hours; food does not affect absorption.', 'Apparent volume of distribution approx. 85 to 180 L; 62% bound to human plasma proteins (predominantly alpha-1 acid glycoprotein).', 'Extensively metabolized in the liver (>80%) primarily by CYP3A4, and to a lesser extent by CYP2D6; multiple metabolites.', 'Excreted in urine (approx. 75%, with <5% unchanged) and faeces (approx. 25%).', 'Approximately 73% (extended release)', '7 hours', '62%', 'Steady state reached within 3 days', '12 hours (dosed twice daily)', '[''Chronic stable angina pectoris refractory to or intolerant of first-line agents (beta-blockers, CCBs, nitrates)'', ''Angina in patients with baseline bradycardia or low blood pressure who cannot tolerate heart-rate lowering medications'', ''Microvascular angina'']', '[''Preexisting clinically significant QTc prolongation (congenital long QT syndrome)'', ''Severe hepatic impairment (Child-Pugh Class C)'', "Concurrent use of strong CYP3A4 inhibitors (ketoconazole, clarithromycin) or inducers (rifampin, carbamazepine, St. John''s wort)"]', '[''Dose-dependent QTc prolongation (mean increase of 6 ms at 1000 mg BID; risk of Torsades de pointes in susceptible patients)'', ''Acute renal failure reported in patients with severe renal impairment (eGFR < 30 mL/min)'', ''Do not crush, break, or chew extended-release tablets'']', '[''Dizziness'', ''Constipation (very common)'', ''Headache'', ''Nausea'', ''Asthenia'']', '[''Torsades de pointes / ventricular arrhythmias (rare)'', ''Acute renal failure (in patients with preexisting severe renal disease)'', ''Syncope'']', '[''Strong CYP3A4 inhibitors (ketoconazole, clarithromycin - contraindicated)'', ''Moderate CYP3A4 inhibitors (diltiazem, verapamil, fluconazole - limit ranolazine to 500 mg BID)'', ''Strong CYP3A4 inducers (rifampin, phenytoin - contraindicated)'', ''P-glycoprotein substrates (ranolazine increases digoxin levels; reduce digoxin by 50%)'', ''Simvastatin (do not exceed 20 mg simvastatin daily)'']', '[''Baseline and periodic ECG to assess QTc interval (especially when combining with other drugs)'', ''Renal function (BUN and creatinine) in patients with eGFR < 60 mL/min'', ''Frequency of weekly angina attacks'']', 'Category C; use during pregnancy only if potential benefit justifies potential risk.', 'Excretion in human milk unknown; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'No dosage adjustment required based on age alone; monitor for constipation and dizziness.', 'If eGFR < 60 mL/min, monitor renal function and discontinue if acute renal failure occurs; contraindicated if eGFR < 30 mL/min.', 'Contraindicated in severe hepatic cirrhosis; dose reduction in moderate impairment.', '[''Relieves chronic angina WITHOUT lowering heart rate or blood pressure, making it ideal for patients with baseline bradycardia or borderline hypotension'', ''Does not cause erectile dysfunction, bronchospasm, or fatigue'', ''Improves glycemic control (modest 0.5-0.7% HbA1c reduction in diabetic patients)'']', '[''High incidence of constipation'', ''Prolongs the QTc interval by 6 ms, requiring baseline ECG and drug interaction screening'', ''High acquisition cost'']', '[''Antianginal medication that does NOT lower your heart rate or blood pressure'', ''Swallow extended-release tablets whole; do not chew or crush; take twice daily'']', 'RANOL-azine: Reduces Acute Na+ Overload; Leaves heart-rate and BP unchanged; Beware QTc & Constipation.', '-azine', 'ra-NOE-la-zeen', 'रानोला-ज़ीन', 'active', 'verified', NULL, NULL),
('trimetazidine', 'Trimetazidine', 'Trimetazidine Modified Release', 'Trimetazidine dihydrochloride', 'Trimetazidine dihydrochloride', 'Cardiovascular', 'A cellular anti-ischemic metabolic agent that shifts myocardial energy metabolism from fatty acid oxidation to glucose oxidation, protecting cardiomyocytes against ischemia without hemodynamic effects.', '[''20 mg'', ''35 mg MR'', ''80 mg OD'']', '[''Film-coated Tablet'', ''Modified-Release Tablet'']', '[''Oral'']', 'Selectively inhibits mitochondrial long-chain 3-ketoacyl-CoA thiolase (3-KAT), suppressing fatty acid beta-oxidation; shifts cellular energy production toward glucose oxidation, which requires less oxygen per ATP molecule produced, optimizing cardiomyocyte energy during ischemia.', 'Maintains intracellular ATP levels, preserves cellular ionic homeostasis (prevents intracellular calcium and sodium overload), and limits acidosis during myocardial ischemia without altering heart rate, blood pressure, or coronary blood flow.', 'Rapidly absorbed from GI tract; modified-release (MR) formulation provides peak levels in 5 hours; food does not affect bioavailability.', 'Widely distributed into tissues; low protein binding (approx. 16%); volume of distribution approx. 4.8 L/kg.', 'Minimal hepatic metabolism; excreted predominantly unaltered.', 'Excreted predominantly unchanged in urine via glomerular filtration (approx. 60%).', 'Approximately 90%', '6 hours (immediate release); 7 to 12 hours (modified release)', '16%', '1 to 2 hours', '12 hours (35 mg MR dosed twice daily)', '[''Add-on therapy for the symptomatic treatment of chronic stable angina pectoris in patients inadequately controlled by or intolerant of first-line antianginal therapies'', ''Adjuvant therapy in ischemic cardiomyopathy'']', '["Parkinson''s disease, parkinsonism, tremors, restless legs syndrome, and other movement disorders", ''Severe renal impairment (creatinine clearance < 30 mL/min)'', ''Known hypersensitivity to trimetazidine'']', '[''PARKINSONIAN SYMPTOMS: Can cause or aggravate parkinsonian symptoms (tremor, rigidity, bradykinesia, gait instability), especially in elderly patients; symptoms are usually reversible upon discontinuation'', ''Must be discontinued permanently if movement disorders develop'', ''Not indicated for acute angina attacks'']', '[''Dizziness'', ''Headache'', ''Abdominal pain'', ''Diarrhoea'', ''Dyspepsia'', ''Nausea'', ''Pruritus / rash'']', '[''Drug-induced parkinsonism / extrapyramidal symptoms'', ''Agranulocytosis / thrombocytopenia (rare)'', ''Severe gait instability and falls'']', '[''No clinically significant pharmacokinetic cytochrome P450 interactions reported'', ''Additive CNS effects with dopamine antagonists'']', '[''Regular screening for movement disorders (tremor, slow movements, gait unsteadiness)'', ''Renal function (creatinine clearance) at baseline and annually'', ''Angina attack frequency'']', 'Avoid during pregnancy due to limited human safety data.', 'Excretion in breast milk unknown; breastfeeding not recommended.', 'Safety and efficacy in children under 18 years not established.', 'Higher risk of drug-induced parkinsonism and falls in senior patients; monitor closely for resting tremor.', 'Dose reduction required: if CrCl 30-60 mL/min, reduce dose by 50% (give 35 mg MR once daily in the morning); contraindicated if CrCl < 30 mL/min.', 'No dosage adjustment required in hepatic disease.', '[''Pure metabolic cytoprotective mechanism that optimizes oxygen efficiency without affecting heart rate or blood pressure'', ''Can be combined safely with any hemodynamic antianginal (beta-blockers, CCBs, nitrates)'', ''Reduces myocardial injury during angioplasty and cardiac surgery'']', '["Risk of drug-induced Parkinson''s symptoms (tremor, gait freezing) in elderly patients", ''Not approved in the United States (extensively used in Europe, Asia, and India)'']', '[''Metabolic heart protector that makes heart muscle use oxygen more efficiently'', ''Stop the medication and inform your doctor immediately if you notice finger tremors or walking stiffness'']', 'TRIMETA-zidine: Thiolase (3-KAT) Inhibitor; Metabolic Energy optimizer; Tremor/Parkinson risk.', '-zidine', 'trye-MET-a-zi-deen', 'ट्राइमेटा-ज़िडीन', 'active', 'verified', NULL, NULL),
('daclatasvir', 'Daclatasvir', 'Daclatasvir Dihydrochloride', 'Daclatasvir dihydrochloride', 'Daclatasvir dihydrochloride', 'Antivirals', 'A potent direct-acting antiviral targeting HCV non-structural protein 5A (NS5A), combined with sofosbuvir for pan-genotypic Hepatitis C cures.', '[''30 mg'', ''60 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Binds to the N-terminus of Domain I of the HCV NS5A replication complex, inhibiting both viral RNA replication and virion assembly.', 'Rapid decline in HCV RNA viral load; pan-genotypic activity against genotypes 1 through 6.', 'Rapidly absorbed; peak plasma concentration in 1 to 2 hours; high oral bioavailability (67%).', 'Volume of distribution approx. 47 L; 99% bound to plasma proteins.', 'Metabolized in the liver by CYP3A4 to inactive metabolites.', 'Excreted predominantly in faeces (approx. 88%) via biliary elimination; less than 7% in urine.', '67%', '12 to 15 hours', '99%', 'Rapid viral load suppression within days', '24 hours (once daily)', '[''Chronic Hepatitis C virus infection genotypes 1, 2, 3, 4, and 6 (combined with sofosbuvir)'', ''HCV in patients with HIV-1 co-infection'', ''HCV in liver transplant recipients'']', '["Concurrent use with strong CYP3A4 inducers (carbamazepine, rifampin, St. John''s wort)"]', '[''Risk of Hepatitis B reactivation during HCV clearance (screen for HBV prior to therapy)'', ''Dose adjustment required with moderate CYP3A4 inhibitors (reduce to 30 mg) or inducers (increase to 90 mg)'']', '[''Headache'', ''Fatigue'', ''Nausea'', ''Diarrhoea'']', '[''Hepatitis B reactivation / acute liver failure'', ''Severe bradycardia (when combined with sofosbuvir and amiodarone)'']', '[''CYP3A4 inhibitors (reduce daclatasvir to 30 mg daily)'', ''CYP3A4 inducers (increase daclatasvir to 90 mg daily)'', ''Amiodarone (fatal bradycardia risk)'']', '[''HBsAg and anti-HBc before starting therapy'', ''HCV RNA at baseline, week 4, end of treatment, and week 12 (SVR12)'', ''Liver enzymes'']', 'Category B; if paired with ribavirin, ribavirin category X contraindication applies.', 'Excreted in animal milk; use caution.', 'Safety and efficacy in pediatric patients under 18 years not established.', 'No dose adjustment based on age.', 'No dosage adjustment required in any degree of renal impairment.', 'No dosage adjustment required in mild, moderate, or severe hepatic impairment.', '[''Pan-genotypic NS5A inhibitor paired successfully with sofosbuvir'', ''No dose adjustment in severe renal impairment'', ''High cure rates (>95% SVR12)'']', '[''CYP3A4 interactions require dose titration to 30 mg or 90 mg'', ''Requires combination therapy; cannot be used alone'']', '[''Standard dose is 60 mg once daily with sofosbuvir 400 mg for 12 weeks'', ''Adjust dose to 30 mg with CYP3A4 inhibitors, or 90 mg with CYP3A4 inducers'']', 'DACLA-tasvir: Direct-Acting Cure Linking with Sofosbuvir for All HCV genotypes.', '-asvir', 'da-KLA-tas-veer', 'डाक्ला-टासविर', 'active', 'verified', NULL, NULL),
('tenofovir-alafenamide', 'Tenofovir Alafenamide (TAF)', 'Tenofovir Alafenamide Fumarate', 'Tenofovir alafenamide fumarate', 'Tenofovir alafenamide fumarate', 'Antivirals', 'A targeted nucleotide reverse transcriptase inhibitor (NRTI) prodrug delivering higher intracellular levels with 90% lower systemic tenofovir exposure, reducing renal and bone toxicities.', '[''25 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Hydrolyzed intracellularly by carboxylesterase 1 (CES1) and cathepsin A in PBMCs and hepatocytes to tenofovir, which is diphosphorylated to tenofovir diphosphate; inhibits HBV reverse transcriptase and HIV-1 reverse transcriptase by chain termination.', 'Potent suppression of Hepatitis B virus DNA replication with negligible renal tubular or bone mineral density toxicity compared to TDF.', 'Rapidly absorbed; peak plasma concentration in 0.5 hours; take with food to optimize bioavailability.', 'High intracellular uptake into hepatocytes and lymphocytes; 80% plasma protein binding.', 'Intracellularly cleaved to tenofovir; minor CYP3A4 metabolism of parent drug.', 'Excreted predominantly in faeces (>31%) and urine (<1% parent drug).', 'High intracellular delivery', 'Plasma half-life 0.5 hours; intracellular tenofovir diphosphate half-life 150-180 hours', '80%', 'Rapid onset of viral suppression', '24 hours', '[''Chronic Hepatitis B virus (HBV) infection in adults and pediatric patients ≥12 years with compensated liver disease'', ''HIV-1 infection (in combination antiretroviral regimens)'']', '[''Hypersensitivity to tenofovir alafenamide'']', '[''Black box warning: Severe acute exacerbations of hepatitis B after discontinuation (monitor liver function for several months post-cessation)'', ''Lactic acidosis and severe hepatomegaly with steatosis'', ''HIV resistance testing required before treatment'']', '[''Headache'', ''Abdominal pain'', ''Fatigue'', ''Cough'', ''Nausea'']', '[''Severe acute exacerbation of HBV after discontinuation'', ''Lactic acidosis / hepatic steatosis'', ''Proximal renal tubulopathy (rare compared to TDF)'']', '[''P-gp inducers (rifampin, carbamazepine - avoid combination)'', ''P-gp inhibitors (increase TAF absorption)'']', '[''Serum HBV DNA viral load'', ''ALT and AST regularly'', ''Renal function (eGFR, serum creatinine, urine protein) at baseline and periodically'']', 'Favorable safety profile; pregnancy registry data shows no increase in birth defects.', 'Compatible with breastfeeding.', 'Approved for pediatric patients 12 years and older weighing ≥35 kg.', 'No dose adjustment based on age alone.', 'No dosage adjustment required if CrCl ≥ 15 mL/min; safe on chronic hemodialysis (administer post-dialysis).', 'No dosage adjustment in mild hepatic impairment; not recommended in decompensated cirrhosis.', '[''90% lower systemic plasma tenofovir exposure than older tenofovir disoproxil (TDF)'', ''Significantly lower incidence of renal tubular dysfunction and bone mineral loss'', ''Safe in patients with mild-to-moderate renal impairment without dose modification'']', '[''Higher cost than generic TDF'', ''Slightly more weight gain and LDL cholesterol elevation than TDF'']', '[''First-line oral treatment for chronic Hepatitis B (25 mg once daily with food)'', ''Protects kidneys and bones much better than older tenofovir disoproxil'']', 'TAF: Targeted Alafenamide Formulation; Thwarts HBV; Tremendous Avoidance of Fractures/nephropathy.', '-fovir', 'te-NOE-foe-veer a-la-FEN-a-mide', 'टीनोफ़ोविर अलाफ़ेनामाइड', 'active', 'verified', NULL, NULL),
('adefovir', 'Adefovir Dipivoxil', 'Adefovir Dipivoxil', 'Adefovir dipivoxil', 'Adefovir dipivoxil', 'Antivirals', 'An oral acyclic nucleotide analogue used for chronic Hepatitis B, particularly effective against lamivudine-resistant YMDD mutant HBV strains.', '[''10 mg'']', '[''Tablet'']', '[''Oral'']', 'Diester prodrug converted intracellularly by esterases to adefovir, which is phosphorylated to adefovir diphosphate; competitively inhibits HBV DNA polymerase and causes chain termination.', 'Antiviral suppression of wild-type and lamivudine-resistant (YMDD motif mutant) HBV; low potency compared to entecavir and tenofovir.', 'Rapidly absorbed; peak plasma concentration in 1.75 hours; 59% oral bioavailability.', 'Low protein binding (<4%); distributes widely into total body water.', 'Not metabolized by CYP450 enzymes; prodrug de-esterified to parent adefovir.', 'Excreted predominantly unchanged in urine via active tubular secretion and glomerular filtration (approx. 45% in 24 hours).', '59%', '7.5 hours (elimination half-life)', '<4%', '1 to 2 hours', '24 hours', '[''Chronic Hepatitis B in adults with evidence of active viral replication and persistent transaminitis'', ''Lamivudine-resistant HBV infection'']', '[''Hypersensitivity to adefovir dipivoxil'']', '[''Black box warning: Nephrotoxicity (proximal tubular dysfunction, Fanconi syndrome, hypophosphatemia) with prolonged use'', ''Severe acute exacerbations of hepatitis B after discontinuation'', ''Lactic acidosis and severe hepatomegaly with steatosis'', ''HIV resistance risk if undiagnosed HIV co-infection exists'']', '[''Asthenia'', ''Headache'', ''Abdominal pain'', ''Nausea'', ''Flatulence'']', '[''Renal tubular toxicity / Fanconi syndrome (hypophosphatemia, glycosuria, proteinuria)'', ''Acute kidney injury'', ''Lactic acidosis'']', '[''Nephrotoxic drugs (aminoglycosides, NSAIDs, cyclosporine - additive renal toxicity)'', ''Drugs eliminated by active tubular secretion'']', '[''Serum creatinine and eGFR at baseline and every 3 months'', ''Serum phosphorus every 3 months (screen for Fanconi syndrome)'', ''HBV DNA viral load and ALT'']', 'Category C; use during pregnancy only if potential benefit justifies potential risk.', 'Excretion in human milk unknown; avoid breastfeeding.', 'Safety and efficacy in pediatric patients under 12 years not established.', 'Monitor renal clearance closely.', 'Strict dose reduction mandatory: CrCl 30-49 mL/min: 10 mg q48h; CrCl 10-29 mL/min: 10 mg q72h; hemodialysis: 10 mg every 7 days post-dialysis.', 'No dosage adjustment required in hepatic impairment.', '[''Active against lamivudine-resistant YMDD mutant HBV strains'', ''Fewer gastrointestinal side effects than interferon'']', '[''Dose-dependent nephrotoxicity and Fanconi syndrome with prolonged therapy'', ''Much lower antiviral potency than tenofovir or entecavir'']', '[''Largely superseded by tenofovir, but useful historical salvage for lamivudine resistance'', ''Check serum creatinine and phosphorus every 3 months (Fanconi syndrome risk)'']', 'ADEFO-vir: Alternative Drug for Entecavir/lamivudine failure; Danger: Fanconi''s Osmotic wasting.', '-fovir', 'a-DEF-oh-veer', 'अडेफ़ो-विर', 'active', 'verified', NULL, NULL),
('lamivudine', 'Lamivudine (3TC)', 'Lamivudine', 'Lamivudine', 'Lamivudine', 'Antivirals', 'A classical cytidine nucleoside reverse transcriptase inhibitor (NRTI) used in combination regimens for HIV-1 infection and as a lower-dose agent for chronic Hepatitis B.', '[''100 mg (HBV)'', ''150 mg'', ''300 mg (HIV)'', ''10 mg/mL oral solution'']', '[''Film-coated Tablet'', ''Oral Solution'']', '[''Oral'']', 'Phosphorylated intracellularly to lamivudine 5''-triphosphate, which competitively inhibits HIV-1 reverse transcriptase and HBV DNA polymerase, causing viral DNA chain termination.', 'Potent suppression of HIV-1 and HBV viral replication; low genetic barrier to resistance (M184V mutation in HIV; M204I/V YMDD mutation in HBV).', 'Rapidly absorbed; peak plasma concentration in 1 hour; 86% oral bioavailability; food does not affect absorption.', 'Distributes into total body water; crosses into CSF (CSF/plasma ratio approx. 0.12); <36% bound to plasma albumin.', 'Minor hepatic metabolism (<10%) to a trans-sulfoxide metabolite; cleared predominantly as unchanged drug.', 'Excreted predominantly unchanged in urine via active organic cation transport and glomerular filtration (approx. 70%).', '86%', '5 to 7 hours in plasma; intracellular triphosphate half-life 16 to 19 hours', '<36%', '1 hour', '12 to 24 hours', '[''HIV-1 infection (in combination with other antiretroviral agents: 300 mg once daily or 150 mg twice daily)'', ''Chronic Hepatitis B infection (100 mg once daily)'', ''Post-exposure prophylaxis (PEP) for occupational and non-occupational HIV exposure'']', '[''Hypersensitivity to lamivudine'']', '[''Black box warning: Do NOT use the 100 mg HBV dose in HIV-coinfected patients (causes rapid emergence of M184V HIV resistance)'', ''Severe acute exacerbation of hepatitis B after discontinuation'', ''Lactic acidosis and severe hepatomegaly with steatosis'']', '[''Headache'', ''Nausea'', ''Fatigue'', ''Diarrhoea'', ''Nasal symptoms / cough'']', '[''Lactic acidosis / hepatic steatosis'', ''Acute exacerbation of HBV on cessation'', ''Pancreatitis (especially in pediatric patients)'', ''Severe peripheral neuropathy'']', '[''Co-trimoxazole (trimethoprim increases lamivudine levels by 40%)'', ''Emtricitabine (same cytidine analogue mechanism; do not combine)'', ''Cladribine (antagonizes phosphorylation)'']', '[''HIV RNA viral load and CD4 count'', ''HBV DNA viral load and ALT in Hepatitis B'', ''Renal function (adjust dose for CrCl < 50 mL/min)'']', 'Category C; reassuring registry data; widely used in maternal prevention of mother-to-child HIV transmission.', 'Excreted in breast milk; compatible with caution where breastfeeding with viral suppression is practiced.', 'Approved for pediatric patients 3 months and older; dosed by body weight.', 'Monitor renal function; adjust dosing interval in renal impairment.', 'Dose reduction required: CrCl 30-49 mL/min: 150 mg once daily; CrCl 15-29 mL/min: 150 mg day 1 then 100 mg once daily; CrCl 5-14 mL/min: 150 mg day 1 then 50 mg once daily; CrCl < 5 mL/min: 50 mg day 1 then 25 mg once daily.', 'No dosage adjustment required in hepatic impairment.', '[''Cornerstone antiretroviral with unmatched safety and tolerability over 25 years'', ''Available in numerous low-cost fixed-dose combination generic tablets'', ''Safe in pregnancy and across pediatric age groups'']', '[''Low genetic barrier to resistance (single M184V point mutation confers total resistance)'', ''High rate of YMDD mutation in Hepatitis B (>70% resistance at 5 years)'']', '[''100 mg daily for Hepatitis B; 300 mg daily for HIV (never use 100 mg if patient has HIV)'', ''Adjust dose when kidney function (CrCl) drops below 50 mL/min'']', 'LAMI-vudine: Low-toxicity Anti-HIV/HBV Medicine; Mutation (M184V) is the main weakness.', '-vudine', 'la-MI-vyoo-deen', 'लैमी-व्युडीन', 'active', 'verified', NULL, NULL),
('praziquantel', 'Praziquantel', 'Praziquantel', 'Praziquantel', 'Praziquantel', 'Antiparasitics', 'The global broad-spectrum anthelmintic of choice for schistosomiasis, liver and lung flukes, and cestode (tapeworm) infections including neurocysticercosis.', '[''600 mg'']', '[''Film-coated Scored Tablet'']', '[''Oral'']', 'Increases cell membrane permeability to calcium ions in platyhelminths, producing rapid calcium influx, massive muscular contraction, paralysis, and tegumental vacuolization; dislodges parasites, exposing them to host immune attack.', 'Lethal against all human Schistosoma species (S. haematobium, S. mansoni, S. japonicum), food-borne trematodes (Clonorchis, Opisthorchis, Paragonimus), and cestodes (Taenia solium, Taenia saginata, Hymenolepis nana).', 'Rapidly absorbed (approx. 80%); undergoes substantial hepatic first-pass metabolism; food significantly increases bioavailability.', 'Widely distributed into tissues and crosses the blood-brain barrier (effective for neurocysticercosis); 80% bound to plasma proteins.', 'Extensively metabolized in the liver by CYP3A4 to inactive hydroxylated metabolites.', 'Excreted predominantly in urine (approx. 70-80% as metabolites within 24 hours); approx. 15-35% in faeces.', 'Approximately 80% absorbed; systemic bioavailability lower due to extensive first-pass metabolism', '0.8 to 1.5 hours (parent); active metabolites 4 to 5 hours', '80%', 'Paralysis of parasites within minutes', '4 to 6 hours', '[''Schistosomiasis (bilharzia) caused by all Schistosoma species (single dose 40-60 mg/kg)'', ''Neurocysticercosis caused by the larval form of Taenia solium (pork tapeworm)'', ''Intestinal tapeworm infections (Taenia saginata, Taenia solium, Hymenolepis nana)'', ''Clonorchiasis, opisthorchiasis, and paragonimiasis (liver and lung flukes)'']', '[''Ocular cysticercosis (destroying parasites in the eye triggers inflammatory blindness)'', ''Concomitant use of strong CYP inducers (rifampin drastically reduces efficacy)'']', '[''In neurocysticercosis, killing cysticerci causes local cerebral inflammation, seizures, and cerebral oedema (always co-administer corticosteroids)'', ''Avoid chewing tablets due to an extremely bitter taste that triggers vomiting'', ''Somnolence: avoid driving on treatment days'']', '[''Dizziness'', ''Headache'', ''Abdominal discomfort'', ''Nausea'', ''Drowsiness'', ''Urticaria / pruritus'']', '[''Seizures / intracranial hypertension (during neurocysticercosis treatment)'', ''Severe hypersensitivity / anaphylaxis'', ''Cardiac arrhythmias (rare)'']', '[''CYP3A4 inducers (rifampin, carbamazepine, phenytoin - reduce praziquantel levels up to 80-99%)'', ''CYP3A4 inhibitors (cimetidine, ketoconazole - increase praziquantel levels)'', ''Dexamethasone (reduces levels, but necessary in neurocysticercosis)'']', '[''Stool examination for ova and parasites at 4 to 6 weeks post-treatment'', ''Neurological examination and MRI/CT in neurocysticercosis'', ''Liver function tests in severe hepatic disease'']', 'Category B; widely used in pregnant women in endemic schistosomiasis regions with high safety profile.', 'Excreted in low levels in breast milk; avoid breastfeeding on the day of treatment and for 72 hours thereafter.', 'Approved for pediatric schistosomiasis and tapeworm infections; tablets can be crushed and mixed with sweet food.', 'No specific dose adjustments; assess hepatic function.', 'No dosage adjustment required in renal impairment.', 'Dose reduction and caution required in severe liver disease (portal hypertension reduces first-pass clearance).', '[''Single-dose curative efficacy for schistosomiasis (40 mg/kg single day treatment)'', ''Pan-fluke and pan-tapeworm coverage against virtually all flatworms'', ''World Health Organization essential medicine for global neglected disease control'']', '[''Extremely bitter taste causes gagging and vomiting if chewed'', ''Requires mandatory corticosteroid co-administration for neurocysticercosis'']', '[''Drug of choice for schistosomiasis and tapeworms'', ''Never chew the tablets (extremely bitter); swallow whole with a full glass of water with food'']', 'PRAZI-quantel: Paralyzes flatworms with Rapid Calcium Influx; Swallowed whole with food.', '-quantel', 'pra-zi-KWAN-tel', 'प्राज़ी-क्वांटेल', 'active', 'verified', NULL, NULL),
('ornidazole', 'Ornidazole', 'Ornidazole', 'Ornidazole', 'Ornidazole', 'Antiparasitics', 'A 5-nitroimidazole derivative with a longer half-life (14 hours) and lower neurotoxicity than metronidazole, widely used in India for amoebiasis, giardiasis, and anaerobic infections.', '[''500 mg'', ''500 mg/100 mL IV infusion'']', '[''Film-coated Tablet'', ''Solution for Infusion'']', '[''Oral'', ''Intravenous'']', 'Enters microbial cells by passive diffusion; nitro group is reduced by ferredoxin oxidoreductase into toxic free radicals that bind to bacterial and protozoan DNA, causing strand breakage and cell death.', 'Potent antiprotozoal activity against Entamoeba histolytica, Giardia lamblia, and Trichomonas vaginalis; bactericidal against anaerobic bacteria (Bacteroides, Clostridium).', 'Rapidly and almost completely absorbed from GI tract (>90% bioavailability); peak plasma concentration in 2 to 3 hours.', 'Widely distributed into tissues, CSF, and body fluids; less than 15% bound to plasma proteins.', 'Metabolized in the liver (approx. 85%) mainly by conjugation and hydroxylation to active and inactive metabolites.', 'Excreted in urine (approx. 60-70%) and faeces (approx. 20-25%) as metabolites; less than 4% unchanged.', '>90%', '12 to 14 hours (longer half-life than metronidazole, allowing twice-daily or once-daily dosing)', '<15%', '1 to 2 hours', '12 to 24 hours', '[''Amoebiasis (intestinal and hepatic amoebic liver abscess)'', ''Giardiasis'', ''Trichomoniasis of genitourinary tract'', ''Anaerobic bacterial infections and surgical prophylaxis'']', '[''Hypersensitivity to ornidazole or nitroimidazoles'', ''Preexisting active central nervous system diseases (epilepsy, multiple sclerosis)'']', '[''Central nervous system toxicity (dizziness, tremor, ataxia, convulsions, peripheral neuropathy with prolonged use)'', ''Disulfiram-like ethanol intolerance (milder than metronidazole, but avoid alcohol)'', ''Severe hepatic impairment requires 50% dose reduction'']', '[''Metallic taste in mouth'', ''Nausea'', ''Epigastric distress'', ''Dizziness'', ''Headache'', ''Somnolence'']', '[''Peripheral neuropathy (numbness, paresthesias in extremities)'', ''Epileptiform seizures'', ''Encephalopathy / cerebellar ataxia'', ''Leukopenia'']', '[''Alcohol / ethanol (mild disulfiram-like flushing, nausea, tachycardia)'', ''Coumarin anticoagulants / warfarin (potentiates anticoagulant effect)'', ''Phenobarbital (decreases ornidazole half-life)'', ''Lithium'']', '[''Complete blood counts in courses exceeding 10 days'', ''Neurological evaluation for paresthesias or ataxia'', ''Stool microscopy for cysts/trophozoites'']', 'Avoid in first trimester of pregnancy; use in 2nd and 3rd trimesters only if clearly indicated.', 'Excreted in breast milk; withhold breastfeeding during therapy and for 48 hours after final dose.', 'Approved for pediatric amoebiasis and giardiasis (dosed at 30-40 mg/kg/day once daily for 3 days).', 'Assess renal and hepatic function; monitor for dizziness.', 'No dosage adjustment required in mild to moderate renal failure; dose post-hemodialysis.', 'Extend dosing interval to 24 hours in severe hepatic cirrhosis (half-life prolonged to 22 hours).', '[''Longer half-life (14 hours) allows convenient once-daily or twice-daily dosing compared to metronidazole TID'', ''Significantly lower incidence of metallic taste, nausea, and vomiting than metronidazole'', ''Better patient compliance for amoebiasis and giardiasis'']', '[''Risk of peripheral neuropathy and ataxia with prolonged courses'', ''Cross-allergenicity with metronidazole'']', '[''Superior tolerability to metronidazole with twice-daily dosing (500 mg BID for 5 days in amoebiasis)'', ''Avoid alcohol during and for 48 hours after completing the course'']', 'ORNI-dazole: One-or-two doses daily (14h half-life); Outperforms metronidazole in gut tolerability.', '-dazole', 'or-NI-da-zole', 'ओर्निडा-ज़ोल', 'active', 'verified', NULL, NULL),
('pyrantel-pamoate', 'Pyrantel Pamoate', 'Pyrantel Pamoate', 'Pyrantel pamoate', 'Pyrantel pamoate', 'Antiparasitics', 'A depolarizing neuromuscular blocking anthelmintic that paralyzes pinworms, roundworms, and hookworms in the intestinal lumen, expelled safely by normal peristalsis.', '[''250 mg'', ''50 mg/mL oral suspension'']', '[''Chewable Tablet'', ''Oral Suspension'']', '[''Oral'']', 'Acts as a depolarizing neuromuscular junction blocker and nicotinic acetylcholine receptor agonist in nematodes; causes persistent muscular depolarization, spastic paralysis, and detachment from the intestinal wall.', 'Paralyzes Enterobius vermicularis (pinworm), Ascaris lumbricoides (roundworm), and Ancylostoma duodenale / Necator americanus (hookworms); completely inactive against whipworm (Trichuris) and flukes.', 'Poorly absorbed from the gastrointestinal tract (<15%); acts locally within the intestinal lumen.', 'Confined primarily to the gut lumen; absorbed trace amounts are bound to plasma proteins.', 'Partially metabolized in the liver; bulk of drug passes through gut unaltered.', 'Excreted predominantly unchanged in faeces (>50%); trace absorbed fraction eliminated in urine (<7%).', '<15% (desirable for luminal parasite clearance)', '1.75 hours (absorbed fraction)', 'Low', 'Paralysis of intestinal worms occurs within 2 to 4 hours', '24 hours', '[''Enterobiasis (pinworm / threadworm infection - single dose of 11 mg/kg, repeat in 2 weeks)'', ''Ascariasis (common roundworm infection - single dose)'', ''Ancylostomiasis and necatoriasis (hookworm infection - daily for 3 days)'']', '[''Hypersensitivity to pyrantel pamoate'', ''Severe preexisting liver impairment'']', '[''Pinworm eggs survive in household dust: treat ALL household members simultaneously to prevent reinfection'', ''Repeat dose after 2 weeks in pinworm infections to eradicate newly hatched larvae'', ''Stains stools bright red/orange'']', '[''Abdominal cramps'', ''Nausea'', ''Vomiting'', ''Diarrhoea'', ''Transient headache'']', '[''Transient elevation in AST/ALT'', ''Severe hypersensitivity rash (rare)'']', '[''Piperazine (directly antagonizes pyrantel pamoate mechanism of action; do not co-administer)'']', '[''Visual inspection of stool or perianal cellophane tape test (Scotch tape test) for pinworm eggs'']', 'Category C; use in pregnancy only if clearly needed (prefer mebendazole/albendazole in 2nd/3rd trimester).', 'Minimal systemic absorption; compatible with breastfeeding.', 'Approved for children 2 years of age and older (11 mg/kg single dose, max 1 g); pleasant-tasting suspension.', 'No dosage adjustment required.', 'No dosage adjustment required (luminal agent).', 'Use with caution in patients with preexisting severe hepatic disease.', '[''Acts locally in the gut lumen with minimal (<15%) systemic absorption, providing exceptional safety'', ''Single-dose cure for pinworms and roundworms'', ''Available as pleasant chewable tablets and liquid suspensions ideal for children'']', '[''Completely ineffective against Trichuris trichiura (whipworm) and tapeworms'', ''Must repeat dose in 2 weeks for pinworms to break the autoinfection cycle'']', '[''First-line over-the-counter treatment for pinworms in children and families'', ''Treat the entire family simultaneously, wash bedsheets in hot water, and repeat in 2 weeks'']', 'PYRANTEL: Paralyzes Pinworms; Yields Rapid expulsion; Repeat After 2 weeks; Never mix with Piperazine.', '-antel', 'pye-RAN-tel PAM-oh-ate', 'पायरेन्टेल पैमोएट', 'active', 'verified', NULL, NULL),
('ciclopirox', 'Ciclopirox', 'Ciclopirox Olamine', 'Ciclopirox olamine', 'Ciclopirox olamine', 'Antifungals', 'A broad-spectrum hydroxypyridone antifungal with a unique metal ion-chelating mechanism, anti-inflammatory and antibacterial activity, used for onychomycosis, seborrheic dermatitis, and tinea.', '[''8% nail lacquer'', ''1% cream'', ''1% shampoo'', ''0.77% gel'']', '[''Nail Lacquer'', ''Topical Cream'', ''Medicated Shampoo'', ''Topical Gel'']', '[''Topical'']', 'Chelates polyvalent cations (Fe3+ and Al3+), inhibiting metal-dependent enzymes (cytochromes, catalase, peroxidase) in fungal mitochondria; disrupts membrane transport and electron transport chains.', 'Fungicidal against dermatophytes (Trichophyton, Microsporum), Candida, and Malassezia; intrinsic antibacterial activity against Gram-positive and Gram-negative bacteria; anti-inflammatory activity via 5-lipoxygenase inhibition.', 'Nail lacquer penetrates deep through keratinized nail plate; minimal systemic absorption (<5%).', 'Concentrates heavily in the stratum corneum, hair follicles, and nail plate; negligible systemic distribution.', 'Minimal systemically absorbed drug is metabolized in the liver by glucuronidation.', 'Excreted in urine (approx. 1-2% of applied topical dose) as glucuronide conjugate.', '<5% systemic absorption', 'Systemic elimination half-life 1.7 hours', '94% to 97%', 'Symptomatic improvement in skin within 1 week; nail cure requires 6 to 12 months', '24 hours (applied daily)', '[''Mild to moderate onychomycosis of fingernails and toenails without lunula involvement (8% nail lacquer)'', ''Seborrheic dermatitis of the scalp (1% shampoo twice weekly)'', ''Tinea pedis, tinea cruris, and tinea corporis (cream or gel)'', ''Cutaneous candidiasis and tinea versicolor'']', '[''Hypersensitivity to ciclopirox or olamine components'', ''Ophthalmic or intravaginal application'']', '[''Nail lacquer: apply daily over previous coats, remove with alcohol every 7 days, and trim nails monthly'', ''Avoid open flames during lacquer application (flammable solvent)'', ''Local irritation and periungual erythema'']', '[''Application site burning or stinging'', ''Periungual erythema'', ''Local pruritus'', ''Nail shape changes / brittle nails'']', '[''Allergic contact dermatitis'', ''Severe periungual blistering (rare)'']', '[''No clinically significant drug interactions reported due to minimal systemic absorption'']', '[''Clinical examination of nail growth from nail fold'', ''Scalp inspection for reduction in scaling and erythema'']', 'Category B; minimal systemic absorption, safe for localized topical use in pregnancy.', 'Excreted in human milk in trace amounts; compatible with breastfeeding (avoid applying to breast).', 'Approved for pediatric patients 10 years and older for onychomycosis; 16 years and older for seborrheic dermatitis.', 'No dosage adjustment required.', 'No dosage adjustment required (topical).', 'No dosage adjustment required (topical).', '[''Unique metal chelation mechanism prevents development of fungal cross-resistance with azoles'', ''Triple antifungal, antibacterial, and anti-inflammatory action ideal for seborrheic dermatitis'', ''Non-toxic alternative to oral antifungals for superficial nail fungus'']', '[''Requires daily nail lacquer application for up to 48 weeks for complete cure'', ''Lower mycological cure rates than oral terbinafine for thick toenails'']', '[''Apply 8% nail lacquer daily to infected nails for 6-12 months; wipe off with alcohol every 7 days'', ''1% shampoo used twice weekly clears stubborn dandruff and seborrheic dermatitis'']', 'CICLO-pirox: Chelates Iron; Cleans Out nail fungus; Calms Itchy Seborrheic Scalp.', '-pirox', 'sye-kloe-PEER-ox', 'सिक्लो-पिरॉक्स', 'active', 'verified', NULL, NULL),
('nystatin', 'Nystatin', 'Nystatin', 'Nystatin', 'Nystatin', 'Antifungals', 'A classical polyene macrolide antifungal not absorbed from the gastrointestinal tract, serving as the gold standard topical and oral suspension treatment for oral candidiasis (thrush).', '[''100,000 units/mL oral suspension'', ''100,000 units/g topical cream'', ''100,000 units vaginal tablet'']', '[''Oral Suspension'', ''Topical Cream'', ''Topical Ointment'', ''Vaginal Tablet'']', '[''Oral (Topical Swish and Swallow)'', ''Topical'', ''Vaginal'']', 'Binds irreversibly to ergosterol in the fungal cell membrane, forming transmembrane pores and barrel-like channels that leak potassium and essential cellular constituents, causing fungal cell death.', 'Fungicidal and fungistatic against Candida albicans and other Candida species; completely inactive against bacteria, viruses, and dermatophytes.', 'Not absorbed from intact skin, mucous membranes, or the gastrointestinal tract; acts purely locally.', 'Confined entirely to the lumen of the gastrointestinal tract or the site of topical application; zero systemic distribution.', 'Not metabolized; passes through the gastrointestinal tract unchanged.', 'Excreted 100% unchanged in the faeces following oral administration.', '0% (negligible gastrointestinal absorption)', 'Not applicable (not absorbed systemically)', 'Not applicable', 'Local antifungal relief within 24 to 48 hours', '6 hours (administered 4 times daily)', '["Oral candidiasis (oral thrush in infants, children, and adults - ''swish and swallow'')", ''Denture stomatitis and angular cheilitis'', ''Cutaneous candidiasis (diaper dermatitis, intertrigo)'', ''Vulvovaginal candidiasis (topical ovules)'']', '[''Hypersensitivity to nystatin or formulation excipients'']', '["Oral suspension should be retained in the mouth as long as possible before swallowing (''swish and swallow'')", ''In infants, apply half dose to each side of the mouth after feeding'', ''Not for the treatment of systemic fungal infections'']', '[''Nausea'', ''Diarrhoea (with large oral doses)'', ''Vomiting'', ''Oral irritation'', ''Mild skin burning'']', '[''Severe hypersensitivity / contact dermatitis (rare)'', ''Stevens-Johnson syndrome (extremely rare)'']', '[''No systemic drug-drug interactions because the drug is not absorbed into the bloodstream'']', '[''Visual inspection of oral cavity for resolution of white plaques (curds)'']', 'Category C; virtually zero systemic absorption, widely considered safe in pregnancy for oral and vaginal thrush.', 'Compatible with breastfeeding; not absorbed into maternal circulation.', 'First-line treatment of choice for neonatal and pediatric oral thrush (100,000 units four times daily).', 'No dosage adjustment required; excellent safety in elderly denture wearers.', 'No dosage adjustment required in renal failure (not absorbed).', 'No dosage adjustment required in hepatic disease (not absorbed).', '[''Zero systemic absorption guarantees an exceptional safety profile with zero organ toxicity'', ''First-line gold standard for infant oral thrush and denture stomatitis'', ''Virtually zero emergence of fungal resistance despite decades of use'']', '[''Completely ineffective for systemic fungal infections'', ''Requires frequent dosing (four times daily) and must be swished in the mouth'']', '["First-line treatment for oral thrush: ''Swish and swallow'' 4 times daily for 7 to 14 days", ''Safe in newborns and elderly patients because it is not absorbed into the blood'']', 'NYSTATIN: New York State lab discovery; No Systemic absorption; Treats All Thrush In Neonates.', '-statin', 'nye-STAT-in', 'नाइस्टैटिन', 'active', 'verified', NULL, NULL),
('favipiravir', 'Favipiravir', 'Favipiravir', 'Favipiravir', 'Favipiravir', 'Antivirals', 'An oral pyrazinecarboxamide antiviral prodrug that selectively inhibits viral RNA-dependent RNA polymerase (RdRp), approved for novel or re-emerging pandemic influenza strains.', '[''200 mg'', ''400 mg'', ''800 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Phosphoribosylated intracellularly to active favipiravir ribofuranosyltriphosphate (favipiravir-RTP), which selectively inhibits viral RNA-dependent RNA polymerase (RdRp) or incorporates into viral RNA, causing chain termination and lethal mutagenesis.', 'Broad antiviral activity against RNA viruses including Influenza A, B, and C viruses, Arenaviruses, Bunyaviruses, Filoviruses (Ebola), and Coronaviruses.', 'Rapidly absorbed; peak plasma concentration in 1 hour; 97% oral bioavailability; food slightly delays absorption.', 'Apparent volume of distribution approx. 15 to 20 L; 54% bound to plasma proteins.', 'Metabolized in the liver primarily by aldehyde oxidase (AO) and to a lesser extent by xanthine oxidase to inactive T-705M1; not cleared by CYP enzymes.', 'Excreted almost entirely in urine (approx. 90%) as the inactive hydroxylated metabolite T-705M1.', '97%', '2 to 5.5 hours (dose-dependent saturable kinetics)', '54%', '1 hour', '12 hours (dosed twice daily after loading dose)', '[''Treatment of novel or re-emerging pandemic influenza virus infections refractory to standard neuraminidase inhibitors'', ''Investigational use in severe emerging RNA virus outbreaks (Ebola, Lassa fever)'']', '[''Hypersensitivity to favipiravir'', ''Pregnancy and lactation (STRICTLY CONTRAINDICATED due to high teratogenic and embryotoxic risk)'', ''Severe hepatic failure'']', '[''Black box warning: Teratogenicity and early embryonic lethality; verified negative pregnancy test mandatory; reliable contraception required for women and men during and for 7 days post-treatment'', ''Hyperuricemia: elevates blood uric acid levels substantially (use caution in gout)'', ''Elevated liver transaminases (ALT/AST)'']', '[''Hyperuricemia (increased serum uric acid in up to 15-20% of patients)'', ''Diarrhoea'', ''Elevated ALT and AST'', ''Nausea'', ''Decreased neutrophil count'']', '[''Severe teratogenic fetal malformations'', ''Acute gouty arthritis attack'', ''Drug-induced hepatitis / jaundice'']', '[''Theophylline (favipiravir increases theophylline blood levels)'', ''Pyrazinamide (additive hyperuricemic effect)'', ''Repaglinide (CYP2C8 inhibition increases repaglinide levels)'']', '[''Serum pregnancy test prior to initiation in all females of reproductive potential'', ''Serum uric acid at baseline and during therapy'', ''Liver function tests (ALT/AST)'']', 'Strictly contraindicated (Category X); produces severe fetal anatomical malformations, limb defects, and embryo-fetal death.', 'Contraindicated; excreted into breast milk.', 'Safety and efficacy in pediatric patients not established.', 'Dose reduction and close monitoring required due to age-related renal and hepatic clearance changes.', 'Uric acid accumulates in renal impairment; monitor serum uric acid and eGFR.', 'Dose reduction required in moderate hepatic impairment; contraindicated in severe cirrhosis.', '[''Broad antiviral activity against diverse RNA virus families that carry resistant RdRp mutations'', ''Near 100% oral bioavailability with rapid cellular uptake'', ''Effective against oseltamivir-resistant influenza strains'']', '[''Severe teratogenicity restricts use to emergency pandemic situations'', ''Substantial elevations in blood uric acid trigger acute gout'']', '[''Oral antiviral for pandemic influenza resistant to Tamiflu'', ''STRICTLY CONTRAINDICATED IN PREGNANCY (causes severe birth defects); raises uric acid'']', 'FAVI-piravir: Fast Acting Viral RdRp Inhibitor; Fatal to Fetus (teratogenic); Avoid In gout.', '-piravir', 'fa-vi-PEER-a-veer', 'फ़ावि-पिराविर', 'active', 'verified', NULL, NULL),
('amiodarone', 'Amiodarone', 'Amiodarone Hydrochloride', 'Amiodarone hydrochloride', 'Amiodarone hydrochloride', 'Antiarrhythmics', 'A broad-spectrum Class III antiarrhythmic with electrophysiologic properties spanning all four Vaughan Williams classes, widely used for refractory ventricular and supraventricular arrhythmias.', '[''100 mg'', ''200 mg'', ''150 mg/3 mL IV ampoule'']', '[''Tablet'', ''Solution for Injection'']', '[''Oral'', ''Intravenous'']', 'Predominantly blocks myocardial outward potassium currents (IKr, IKs), prolonging action potential duration and refractory period; additionally blocks inactivated sodium channels (Class I), non-competitively blocks beta receptors (Class II), and inhibits L-type calcium channels (Class IV).', 'Suppresses ectopic ventricular and supraventricular pacemakers, slows sinus rate and AV nodal conduction, and terminates re-entrant tachycardias; minimal negative inotropy allows safe use in heart failure with reduced ejection fraction.', 'Slow and erratic oral absorption (30-50%); high-fat meals increase absorption by 2- to 3-fold; peak plasma concentration in 3 to 7 hours.', 'Enormous volume of distribution (approx. 60 L/kg); accumulates extensively in adipose tissue, lungs, liver, and skin; 96% bound to plasma albumin.', 'Extensively metabolized in the liver by CYP3A4 and CYP2C8 to active desethylamiodarone (DEA); undergoes enterohepatic recycling.', 'Excreted predominantly in bile and faeces via hepatic elimination; urinary excretion of parent drug is negligible (<1%).', '30% to 50%', '26 to 107 days (mean terminal elimination half-life approx. 50 days; tissue effects persist for months post-discontinuation)', '96%', 'Oral: 2 to 3 days (with loading dose); IV: within hours', 'Weeks to months after stopping', '[''Recurrent ventricular fibrillation (VF) and hemodynamically unstable ventricular tachycardia (VT) refractory to other therapy'', ''Advanced cardiac life support (ACLS) in pulseless VT/VF cardiac arrest'', ''Maintenance of sinus rhythm in symptomatic atrial fibrillation (especially with heart failure or left ventricular hypertrophy)'']', '[''Severe sinus node dysfunction causing marked sinus bradycardia'', ''Second- or third-degree AV block without a functioning pacemaker'', ''Cardiogenic shock'', ''Known hypersensitivity to amiodarone or iodine (contains 37% iodine by weight)'']', '[''Black box warning: Fatal pulmonary toxicity (hypersensitivity pneumonitis or alveolar fibrosis in up to 10-17% on chronic high doses)'', ''Hepatotoxicity: elevated serum transaminases and fulminant cirrhosis'', ''Thyroid dysfunction: iodine-induced hypothyroidism (common, treatable with levothyroxine) or hyperthyroidism (AIT type 1 or 2)'', ''Corneal microdeposits (present in virtually 100% on chronic therapy) and optic neuropathy/blindness'', ''Skin blue-gray slate pigmentation (ceruloderma) on sun-exposed areas'']', '[''Corneal microdeposits (benign vortex keratopathy in almost all patients)'', ''Photosensitivity and skin sunburn'', ''Nausea and anorexia'', ''Tremor and ataxia'', ''Constipation'']', '[''Fatal pulmonary fibrosis / interstitial pneumonitis'', ''Severe hepatotoxicity / cirrhosis'', ''Amiodarone-induced thyrotoxicosis (AIT)'', ''Optic neuropathy / permanent visual impairment'', ''Severe symptomatic bradycardia / complete AV block'']', '[''Warfarin (potent CYP2C9 inhibition doubles INR; immediately reduce warfarin dose by 33-50%)'', ''Digoxin (P-glycoprotein inhibition doubles serum digoxin levels; halve digoxin dose)'', ''Statins (simvastatin/atorvastatin - risk of severe rhabdomyolysis; cap simvastatin at 20 mg)'', ''QT-prolonging drugs (macrolides, fluoroquinolones - additive QT risk)'']', '[''Baseline and annual chest X-ray and pulmonary function tests (PFTs including DLCO)'', ''Baseline and every 6-month thyroid function tests (TSH, free T4)'', ''Baseline and every 6-month liver function tests (AST, ALT, alkaline phosphatase)'', ''Annual ophthalmologic examination (slit lamp and fundoscopy)'', ''Continuous ECG during IV infusion; 12-lead ECG every 3-6 months'']', 'Category D; strictly avoided in pregnancy unless life-threatening arrhythmias (causes fetal hypothyroidism, goiter, and growth restriction).', 'Excreted in significant quantities in breast milk; breastfeeding is strictly contraindicated.', 'Weight-adjusted dosing in pediatric resuscitation (5 mg/kg IV bolus in cardiac arrest).', 'Elderly patients are at heightened risk of pulmonary fibrosis, thyroid toxicity, and severe bradycardia; use the lowest effective maintenance dose (100-200 mg daily).', 'No dosage adjustment required in renal impairment or hemodialysis (negligible renal clearance).', 'Close monitoring and dose reduction recommended in severe hepatic disease (primary elimination organ).', '[''Most effective antiarrhythmic for suppressing ventricular tachycardia and maintaining sinus rhythm in atrial fibrillation'', ''Safe in heart failure with reduced ejection fraction (does not worsen cardiac mortality, unlike Class I antiarrhythmics)'', ''First-line ACLS medication for shock-refractory pulseless VT/VF'']', '[''Severe multiorgan toxicities (lungs, liver, thyroid, eyes, skin) requiring lifelong monitoring'', ''Extremely long 50-day half-life means side effects and drug interactions persist for months after stopping'']', '[''Halve digoxin and warfarin doses immediately when starting amiodarone'', ''Requires regular checks of thyroid function, liver enzymes, and chest X-rays due to iodine accumulation'']', 'AMIODARONE: Action spans all classes; Massive volume of distribution; Iodine overload (thyroid); Organ toxicities (lung/liver); Decreases Warfarin dose.', '-arone', 'a-MEE-oh-da-rone', 'एमियोडा-रोन', 'active', 'verified', NULL, NULL),
('flecainide', 'Flecainide', 'Flecainide Acetate', 'Flecainide acetate', 'Flecainide acetate', 'Antiarrhythmics', 'A potent Class IC antiarrhythmic with marked sodium channel blockade and slow dissociation kinetics, used as the first-line ''pill-in-the-pocket'' for paroxysmal atrial fibrillation in structurally normal hearts.', '[''50 mg'', ''100 mg'', ''150 mg'']', '[''Tablet'']', '[''Oral'']', 'Markedly blocks open fast inward voltage-gated sodium channels (Nav1.5) with slow dissociation kinetics; significantly slows phase 0 depolarization and His-Purkinje conduction velocity; also blocks cardiac ryanodine receptor (RyR2), suppressing spontaneous calcium release from sarcoplasmic reticulum.', 'Produces marked prolongation of PR and QRS intervals with minimal effect on action potential duration (APD) or QTc; terminates and prevents supraventricular and catecholaminergic polymorphic ventricular tachycardias (CPVT).', 'Rapidly and almost completely absorbed (approx. 90-95%); peak plasma concentrations in 2 to 3 hours; food does not impair absorption.', 'Apparent volume of distribution approx. 8 to 10 L/kg; 40% bound to plasma proteins.', 'Metabolized in the liver by CYP2D6 to meta-O-dealkylated flecainide and its lactam metabolite (minor activity); subject to genetic polymorphism.', 'Eliminated equally by renal excretion of unchanged drug (approx. 30-40%) and urinary excretion of hepatic metabolites; excretion decreases in alkaline urine.', 'Approximately 90% to 95%', '12 to 20 hours (mean 14 hours; extended up to 30 hours in renal failure or severe heart failure)', '40%', '1 to 2 hours', '12 to 24 hours (dosed twice daily)', '[''Maintenance of normal sinus rhythm in paroxysmal atrial fibrillation or flutter in STRUCTURALLY NORMAL HEARTS'', ''Paroxysmal supraventricular tachycardias (AVNRT, AVRT / Wolff-Parkinson-White syndrome)'', ''Pill-in-the-pocket acute termination of recent-onset atrial fibrillation (200-300 mg single oral dose)'', ''Catecholaminergic polymorphic ventricular tachycardia (CPVT) refractory to beta-blockers'']', '[''STRUCTURAL HEART DISEASE (prior myocardial infarction, coronary artery disease, heart failure with reduced or preserved EF - CAST trial: 2.5x increase in cardiac mortality)'', ''Preexisting second- or third-degree AV block or bifascicular block without pacemaker'', ''Cardiogenic shock'', ''Concurrent use of other Class I antiarrhythmics'']', '[''Black box warning: STRICTLY CONTRAINDICATED in patients with prior myocardial infarction or structural heart disease (CAST trial demonstrated increased mortality from lethal ventricular proarrhythmia)'', ''Atrial flutter: flecainide can slow atrial flutter rate to 200 bpm allowing 1:1 AV conduction and life-threatening ventricular rates of 200 bpm (ALWAYS co-administer an AV nodal blocker like a beta-blocker or verapamil)'', ''Narrow therapeutic index: monitor plasma levels (0.2 to 1.0 mcg/mL)'']', '[''Dizziness'', ''Visual disturbances (blurred vision, difficulty focusing, spots before eyes)'', ''Dyspnea'', ''Headache'', ''Nausea'', ''Fatigue'']', '[''Lethal ventricular proarrhythmia / polymorphic VT (in ischemic or scarred myocardium)'', ''1:1 AV conduction in atrial flutter with hemodynamic collapse'', ''Sinus arrest or severe heart block'', ''Congestive heart failure decompensation'']', '[''CYP2D6 inhibitors (fluoxetine, paroxetine, quinidine - elevate flecainide to toxic proarrhythmic levels)'', ''Amiodarone (doubles flecainide levels; cut flecainide dose by 50%)'', ''Digoxin and beta-blockers (additive negative dromotropy; flecainide increases digoxin levels by 15-25%)'']', '[''Baseline 12-lead ECG: verify QRS duration (<120 ms) and check for Q-waves or ischemia'', ''Pre-treatment echocardiogram or stress test: RULE OUT coronary artery disease and heart failure'', ''Trough serum flecainide levels (therapeutic range: 0.2 to 1.0 mcg/mL; toxicity > 1.0 mcg/mL)'', ''Renal function tests (BUN and serum creatinine)'']', 'Category C; use only if potential benefit justifies potential risk.', 'Excreted in high concentrations in breast milk; breastfeeding not recommended.', 'Approved in pediatric patients for refractory SVT and CPVT (dosed by body surface area: 50-100 mg/m2/day).', 'Age-related decline in renal clearance increases toxicity risk; start with 50 mg twice daily.', 'Strict dose reduction required if CrCl < 35 mL/min: start with 50 mg every 12 to 24 hours; monitor plasma levels closely.', 'Dose reduction required in severe hepatic impairment; monitor plasma levels.', '["Gold standard oral ''pill-in-the-pocket'' for terminating paroxysmal atrial fibrillation outside the hospital", ''Exceptional efficacy in terminating and preventing AVNRT, AVRT, and Wolff-Parkinson-White arrhythmias in healthy hearts'', ''Unique RyR2 receptor inhibition makes it life-saving in CPVT'']', '[''LETHAL in patients with heart disease, previous heart attacks, or heart failure (CAST trial)'', ''Can trigger 1:1 atrial flutter with rapid ventricular rates unless combined with a beta-blocker'']', '[''CRITICAL RULE: Safe ONLY in structurally normal hearts (NO prior heart attack, CAD, or heart failure)'', ''Always prescribe a beta-blocker with flecainide to prevent dangerous 1:1 heart racing in atrial flutter'']', 'FLECA-inide: First Line for structurally Empty Cardiac Anatomy (normal hearts only); Avoid in Ischemia/infarct (CAST trial).', '-inide', 'FLEK-a-nide', 'फ्लेके-नाइड', 'active', 'verified', NULL, NULL),
('propafenone', 'Propafenone', 'Propafenone Hydrochloride', 'Propafenone hydrochloride', 'Propafenone hydrochloride', 'Antiarrhythmics', 'A Class IC antiarrhythmic with intrinsic mild beta-blocking and local anesthetic properties, used for maintaining sinus rhythm in atrial fibrillation and supraventricular tachycardias.', '[''150 mg'', ''300 mg'', ''225 mg SR'', ''325 mg SR'', ''425 mg SR'']', '[''Film-coated Tablet'', ''Extended-Release Capsule'']', '[''Oral'']', 'Blocks fast inward sodium channels (Class IC) with slow recovery kinetics, slowing phase 0 depolarization; structurally similar to propranolol, exerting mild non-selective beta-adrenergic blockade (approx. 1/40th the potency of propranolol).', 'Slows intraventricular and AV nodal conduction, prolongs PR and QRS intervals, suppresses ectopic atrial triggers, and prevents re-entrant tachycardias; mild beta-blocking action helps prevent 1:1 AV conduction in atrial flutter.', 'Rapidly and completely absorbed (>95%); undergoes extensive saturable (non-linear) hepatic first-pass metabolism; bioavailability ranges from 5% to 50% depending on CYP2D6 metabolizer status; take with food to improve absorption.', 'Widely distributed; apparent volume of distribution approx. 2 to 4 L/kg; 97% bound to plasma alpha-1 acid glycoprotein.', 'Extensively metabolized in the liver by CYP2D6 to active 5-hydroxypropafenone (which possesses equal sodium-blocking activity and less beta-blocking activity) and by CYP3A4 to N-depropylpropafenone.', 'Excreted in faeces (approx. 53% via biliary route) and urine (approx. 38% as glucuronide and sulfate metabolites); less than 1% unchanged drug in urine.', '5% to 50% (non-linear, saturable first-pass kinetics)', 'Extensive metabolizers: 2 to 10 hours; Poor metabolizers: 10 to 32 hours', '97%', '1 to 2 hours', '8 hours (IR tablet dosed TID); 12 hours (SR capsule dosed BID)', '[''Maintenance of sinus rhythm in patients with paroxysmal atrial fibrillation/flutter in the absence of structural heart disease'', ''Prevention of paroxysmal supraventricular tachycardias (PSVT), AVNRT, and AVRT'', "''Pill-in-the-pocket'' conversion of recent-onset atrial fibrillation (450-600 mg single oral dose)"]', '[''Structural heart disease (coronary artery disease, previous myocardial infarction, reduced left ventricular ejection fraction)'', ''Severe bronchospasm, asthma, or severe COPD (due to intrinsic beta-blocking activity)'', ''Severe bradycardia, sick sinus syndrome, or second/third-degree AV block without pacemaker'', ''Cardiogenic shock or severe hypotension'']', '[''Black box warning: CONTRAINDICATED in structural heart disease (Class IC proarrhythmia risk as demonstrated in the CAST trial)'', ''Non-linear pharmacokinetics: doubling the dose can increase serum drug concentrations by 300%'', ''Intrinsic beta-blocker effect can trigger acute asthma attacks or worsen heart failure'']', '[''Metallic or bitter taste (characteristic side effect in up to 15-20%)'', ''Dizziness'', ''Nausea and vomiting'', ''Constipation'', ''Fatigue / weakness'', ''Bradycardia'']', '[''Ventricular proarrhythmia / ventricular tachycardia'', ''Severe bronchospasm in asthmatic patients'', ''Complete AV heart block / sinus arrest'', ''Agranulocytosis (rare)'']', '[''CYP2D6 inhibitors (fluoxetine, paroxetine - substantially increase propafenone levels and beta-blockade)'', ''Warfarin (propafenone inhibits warfarin metabolism, increasing INR; reduce warfarin dose)'', ''Digoxin (increases serum digoxin levels by 35-85%; reduce digoxin dose)'', ''CYP3A4 inhibitors/inducers'']', '[''Baseline 12-lead ECG (monitor PR and QRS prolongation; discontinue if QRS widens >25% over baseline)'', ''Baseline echocardiogram: strictly exclude ischemic heart disease and ventricular dysfunction'', ''Liver function tests and complete blood count'']', 'Category C; use during pregnancy only if potential benefit justifies potential risk.', 'Excreted in human milk; compatible with caution or alternative agent.', 'Safety and efficacy in pediatric patients not established.', 'Higher plasma levels due to reduced first-pass clearance; start with 150 mg twice daily.', 'No primary dosage adjustment required in mild to moderate renal disease; monitor ECG.', 'Dose must be reduced by 50% in hepatic cirrhosis due to saturable first-pass metabolism.', '[''Dual Class IC sodium blockade and mild beta-adrenergic blockade provides built-in AV nodal protection against 1:1 flutter'', "Proven oral ''pill-in-the-pocket'' option for terminating acute episodes of atrial fibrillation at home", ''Extended-release formulation enables convenient twice-daily dosing'']', '[''Characteristic metallic taste in the mouth'', ''Non-linear pharmacokinetics make dose titration unpredictable'', ''Strictly contraindicated in heart disease and asthma'']', '[''Safe only in hearts free of prior heart attacks or weakness (structurally normal hearts)'', ''Leaves a strange metallic taste in the mouth that is harmless; take with meals'']', 'PROPA-fenone: Prototypic IC sodium blocker; Propranolol-like beta-blockade; Avoid In Asthma & Infarct; Metallic taste.', '-fenone', 'proe-pa-FEN-one', 'प्रोपा-फ़ेनोन', 'active', 'verified', NULL, NULL),
('dronedarone', 'Dronedarone', 'Dronedarone Hydrochloride', 'Dronedarone hydrochloride', 'Dronedarone hydrochloride', 'Antiarrhythmics', 'A non-iodinated benzofuran derivative of amiodarone designed to reduce multiorgan thyroid and pulmonary toxicities, used to maintain sinus rhythm in paroxysmal or persistent atrial fibrillation.', '[''400 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Exhibits multichannel antiarrhythmic activity across all four Vaughan Williams classes (blocks IKr, IKs, INa, ICa, and possesses non-competitive antiadrenergic activity); lacks the iodine moieties of amiodarone and incorporates a methane-sulfonyl group to reduce lipophilicity.', 'Reduces sinus heart rate, slows AV nodal conduction, prolongs myocardial refractory periods, and reduces cardiovascular hospitalizations and mortality in patients with non-permanent atrial fibrillation (ATHENA trial).', 'Poorly absorbed in fasting state (bioavailability approx. 4%); food dramatically increases absorption to approx. 15% (must be taken with morning and evening meals).', 'Apparent volume of distribution approx. 1400 L; highly bound to human plasma proteins (>98%), predominantly albumin.', 'Extensively metabolized in the liver by CYP3A4 to an active N-debutyl metabolite (approx. 1/10th the potency of dronedarone).', 'Excreted predominantly in faeces (approx. 84%) via biliary elimination; approx. 6% excreted in urine as metabolites; zero unchanged drug in urine.', 'Approximately 15% (with meals); 4% (fasting)', '25 to 30 hours (substantially shorter than amiodarone''s 50-day half-life)', '>98%', 'Steady state reached within 4 to 8 days', '12 hours (dosed 400 mg twice daily with meals)', '[''Reduction of the risk of cardiovascular hospitalization in patients with paroxysmal or persistent atrial fibrillation who are currently in sinus rhythm or who will be cardioverted (ATHENA trial)'']', '[''PERMANENT ATRIAL FIBRILLATION (PALLAS trial: doubled mortality, stroke, and HF hospitalizations)'', ''NYHA Class IV heart failure or NYHA Class II-III heart failure with recent decompensation (ANDROMEDA trial: doubled mortality)'', ''Second- or third-degree AV block or sick sinus syndrome without a functioning pacemaker'', ''Severe hepatic impairment'', ''Concurrent use of strong CYP3A inhibitors or QT-prolonging drugs'']', '[''Black box warning: STRICTLY CONTRAINDICATED in patients with symptomatic heart failure or permanent atrial fibrillation (PALLAS and ANDROMEDA trials showed significant excess mortality)'', ''Hepatotoxicity: rare cases of acute liver failure requiring transplantation (monitor liver enzymes)'', ''Increases serum creatinine by approx. 0.1 mg/dL by inhibiting tubular secretion (OCT2) without reducing actual GFR'', ''Pulmonary toxicity: rare cases of interstitial lung disease / pneumonitis'']', '[''Diarrhoea (very common)'', ''Nausea and abdominal pain'', ''Asthenia / fatigue'', ''Mild bradycardia'', ''Elevated serum creatinine (benign tubular inhibition)'']', '[''Severe worsening of heart failure / cardiac death (in decompensated HF or permanent AF)'', ''Acute hepatic failure / fulminant hepatitis'', ''Pulmonary fibrosis / interstitial pneumonitis'', ''Torsades de pointes / QT prolongation'']', '[''Strong CYP3A4 inhibitors (ketoconazole, clarithromycin - strictly contraindicated)'', ''Dabigatran (P-gp inhibition increases dabigatran levels; reduce dabigatran dose or avoid)'', ''Digoxin (doubles digoxin levels; reduce digoxin dose by 50%)'', ''Statins (simvastatin/atorvastatin - doubles statin levels; reduce statin dose)'']', '[''Liver function tests (ALT, AST, alkaline phosphatase) prior to initiation, monthly for 6 months, then periodically'', ''ECG at baseline and every 3-6 months (verify patient remains in sinus rhythm and has not progressed to permanent AF)'', ''Serum creatinine (expect benign 0.1 mg/dL increase; verify baseline GFR)'']', 'Category X; strictly contraindicated in pregnancy due to embryotoxicity and fetal teratogenicity.', 'Excretion in human milk unknown; breastfeeding strictly contraindicated.', 'Safety and efficacy in children under 18 years not established.', 'No primary dose adjustment; monitor heart failure symptoms and ensure sinus rhythm.', 'No dosage adjustment required in renal impairment (cleared predominantly by liver).', 'Contraindicated in severe hepatic impairment; monitor liver enzymes closely.', '[''Lacks the iodine moieties of amiodarone, drastically reducing thyroid toxicity, pulmonary fibrosis, and corneal deposits'', ''Shorter half-life (30 hours vs. 50 days) allows rapid clearance if side effects occur'', ''Proven in the ATHENA trial to reduce cardiovascular hospitalizations and death in paroxysmal AF'']', '[''LETHAL in permanent atrial fibrillation or heart failure (PALLAS and ANDROMEDA trials)'', ''Low oral bioavailability (15%) and must be taken with full meals twice daily'']', '[''ONLY for intermittent (paroxysmal) atrial fibrillation; NEVER take if AF has become permanent'', ''Always take 400 mg twice daily with your morning and evening meals'']', 'DRONE-darone: De-iodinated amiodarone; Reduces hospitalizations in Non-permanent AF; Deadly in permanent AF.', '-darone', 'droe-NE-da-rone', 'ड्रोनेडा-रोन', 'active', 'verified', NULL, NULL),
('adenosine', 'Adenosine', 'Adenosine Injection', 'Adenosine', 'Adenosine', 'Antiarrhythmics', 'An endogenous purine nucleoside with an ultra-short half-life (<10 seconds) that transiently blocks AV nodal conduction, serving as the gold standard acute rescue agent for paroxysmal supraventricular tachycardia (PSVT).', '[''3 mg/mL (2 mL vial = 6 mg, 4 mL vial = 12 mg)'']', '[''Solution for Rapid IV Bolus Injection'']', '[''Intravenous (Rapid Push)'']', 'Binds to myocardial purinergic A1 receptors coupled to Gi proteins, activating inward rectifier potassium channels (IK-Ado) and inhibiting adenylate cyclase-mediated L-type calcium influx; profoundly slows AV nodal conduction velocity and prolongs AV refractory periods.', 'Terminates re-entrant circuits traversing the AV node (AVNRT and AVRT / Wolff-Parkinson-White syndrome) within 10 to 30 seconds; produces coronary arteriolar vasodilation via A2A receptors (utilized in cardiac stress testing).', 'Administered exclusively by rapid intravenous push; not active orally.', 'Rapidly taken up into erythrocytes and vascular endothelial cells by nucleoside transporters; volume of distribution approx. 10 L.', 'Rapidly metabolized intracellularly by adenosine deaminase (ADA) to inosine, and phosphorylated by adenosine kinase to AMP; not dependent on hepatic CYP450 enzymes.', 'Eliminated within seconds; metabolites are degraded to uric acid and excreted in urine.', '100% (rapid IV bolus)', 'Less than 10 seconds (cellular uptake and enzymatic breakdown occur in under 10 seconds)', 'Negligible', 'Immediate (within 10 to 20 seconds of rapid push)', 'Under 1 to 2 minutes', '[''Acute conversion of paroxysmal supraventricular tachycardia (PSVT) including AVNRT and AVRT to sinus rhythm'', ''Diagnostic unmasking of underlying atrial flutter or atrial fibrillation by transiently blocking AV conduction'', ''Pharmacologic myocardial perfusion stress imaging (vasodilator stress agent via A2A receptors)'']', '[''Second- or third-degree AV block or sick sinus syndrome (in patients without a functioning pacemaker)'', ''Severe active bronchospasm, bronchial asthma, or severe COPD (can trigger bronchospasm via A2B/A3 receptors)'', ''Known hypersensitivity to adenosine'', ''Pre-excited atrial fibrillation (Wolff-Parkinson-White with AF - risk of 1:1 ventricular conduction and VF)'']', '[''ADMINISTRATION TECHNIQUE IS CRITICAL: Half-life is <10 seconds; MUST be administered as an ultra-rapid IV push over 1 to 2 seconds directly into a large proximal vein (antecubital fossa), IMMEDIATELY followed by a rapid 20 mL normal saline flush'', ''Warn the awake patient beforehand of intense transient chest tightness, facial flushing, and impending doom (lasts 10-20 seconds)'', ''Continuous multi-lead ECG monitoring and resuscitation equipment must be at the bedside'']', '[''Facial flushing (very common, transient)'', ''Intense chest pressure / dyspnea (frightening to patient, lasts 15 seconds)'', ''Dizziness and lightheadedness'', ''Transient sinus bradycardia / asystole on ECG (lasts 2 to 5 seconds)'', ''Nausea'']', '[''Prolonged asystole / ventricular standstill requiring CPR'', ''Severe bronchospasm / status asthmaticus'', ''Atrial fibrillation or ventricular fibrillation precipitation'']', '[''Theophylline, aminophylline, caffeine (adenosine receptor antagonists: competitive inhibition blocks adenosine effect; requires higher adenosine doses)'', ''Dipyridamole (nucleoside uptake inhibitor: potentiates adenosine 4-fold; reduce adenosine dose to 3 mg)'', ''Carbamazepine (potentiates AV block; reduce dose)'']', '[''Continuous ECG rhythm strip recording during and for 5 minutes after injection'', ''Blood pressure and heart rate'', ''SpO2 and respiratory status'']', 'Category C; safe during pregnancy for maternal SVT due to ultra-short 10-second half-life and zero fetal exposure.', 'Zero infant exposure due to 10-second maternal clearance; compatible with breastfeeding.', 'Approved for pediatric PSVT (initial dose: 0.1 mg/kg rapid IV push, maximum 6 mg; second dose 0.2 mg/kg, max 12 mg).', 'Higher incidence of sinus pause and bradycardia; start with 6 mg rapid push.', 'No dosage adjustment required in renal failure (eliminated by ubiquitous cellular enzymes).', 'No dosage adjustment required in hepatic disease.', '[''Gold standard first-line medication for terminating acute SVT with a 90-95% success rate within 30 seconds'', ''Ultra-short half-life (<10 seconds) ensures any adverse side effects disappear in less than a minute'', ''Safe in pregnancy and across pediatric age groups'']', '[''Must be given as a rapid proximal IV slam with a 20 mL saline flush, or it degrades before reaching the heart'', ''Produces terrifying transient chest tightness, flushing, and brief asystole (warn the patient)'']', '[''Administer as an ultra-fast IV push into the elbow vein, instantly followed by a 20 mL saline flush'', "Warn the patient: ''You will feel intense chest tightness for 15 seconds, but it will pass quickly''"]', 'ADENO-sine: Arrests AV Node; Ultra-short half-life (<10s); Rapid IV slam; Saline flush needed; Asthmatics beware.', '-sine', 'a-DEN-oh-seen', 'एडेनो-सीन', 'active', 'verified', NULL, NULL),
('mexiletine', 'Mexiletine', 'Mexiletine Hydrochloride', 'Mexiletine hydrochloride', 'Mexiletine hydrochloride', 'Antiarrhythmics', 'An orally active Class IB antiarrhythmic and structural analogue of lidocaine, used for life-threatening ventricular arrhythmias, myotonic disorders (non-dystrophic myotonia), and neuropathic pain.', '[''150 mg'', ''200 mg'', ''250 mg'']', '[''Capsule'']', '[''Oral'']', 'Inhibits fast inward voltage-gated sodium channels (Nav1.5 in myocardium, Nav1.4 in skeletal muscle), shortening action potential duration and effective refractory period in Purkinje fibers; accelerates repolarization and blocks persistent/late sodium currents (INa-late).', 'Suppresses abnormal ventricular automaticity and triggered activity without depressing cardiac output; in skeletal muscle, blocks hyperactive sodium channels, dramatically relieving muscle stiffness in non-dystrophic myotonia.', 'Rapidly and almost completely absorbed (>90%); peak plasma concentrations in 2 to 3 hours; food does not impair total absorption.', 'Widely distributed into tissues and crosses the blood-brain barrier; volume of distribution approx. 5 to 7 L/kg; 50-60% bound to plasma proteins.', 'Extensively metabolized in the liver (approx. 90%) by CYP2D6 and CYP1A2 to inactive hydroxy and hydroxymethyl metabolites.', 'Excreted in urine (approx. 10% as unchanged drug; remainder as metabolites); renal clearance increases in acidic urine (pH < 5) and decreases in alkaline urine.', 'Approximately 90%', '10 to 12 hours (prolonged to 20-25 hours in severe liver failure or heart failure)', '50% to 60%', '1 to 2 hours', '8 hours (dosed 3 times daily with food)', '[''Documented life-threatening ventricular arrhythmias (sustained ventricular tachycardia)'', ''Non-dystrophic myotonia (myotonia congenita and paramyotonia congenita - FDA/EMA orphan drug of choice)'', ''Long QT syndrome type 3 (LQT3 - selectively blocks late sodium current)'', ''Refractory diabetic peripheral neuropathic pain (second-line)'']', '[''Preexisting second- or third-degree AV block without a functioning pacemaker'', ''Cardiogenic shock'', ''Known hypersensitivity to mexiletine or local anesthetics of the amide type'']', '[''Narrow therapeutic window: therapeutic plasma range is 0.5 to 2.0 mcg/mL (toxicity common above 2.0 mcg/mL)'', ''Neurotoxicity: fine tremor, ataxia, nystagmus, dizziness, and paresthesias are early signs of toxicity'', ''Gastrointestinal distress: take with food or antacids to minimize nausea and heartburn'', ''Drug-induced liver injury / DRESS syndrome'']', '[''Tremor (fine hand tremor - common dose-limiting sign)'', ''Nausea and vomiting'', ''Heartburn / dyspepsia'', ''Dizziness and ataxia'', ''Nystagmus'', ''Diplopia'']', '[''Ventricular proarrhythmia / worsening of VT'', ''Convulsions / seizures (in severe toxicity)'', ''Severe drug-induced liver injury'', ''DRESS syndrome (Drug Reaction with Eosinophilia and Systemic Symptoms)'']', '[''CYP2D6 / CYP1A2 inducers (phenobarbital, phenytoin, rifampin - decrease mexiletine levels by 50%)'', ''CYP2D6 inhibitors (fluoxetine, quinidine - elevate mexiletine levels, precipitating toxicity)'', ''Cigarette smoking (induces CYP1A2, increasing mexiletine clearance)'', ''Caffeine (mexiletine inhibits caffeine metabolism, causing caffeine jitters)'']', '[''Serum mexiletine trough concentrations (therapeutic target: 0.5 to 2.0 mcg/mL)'', ''Neurological assessment for tremor, ataxia, or nystagmus at every visit'', ''Baseline and periodic 12-lead ECG'', ''Liver function tests'']', 'Category C; use during pregnancy only if potential benefit justifies potential risk.', 'Excreted in breast milk in concentrations higher than maternal plasma; breastfeeding not recommended.', 'Approved in children for non-dystrophic myotonia and congenital LQT3 (weight-based dosing: 2-8 mg/kg/day divided TID).', 'Increased susceptibility to neurological toxicity and dizziness; start at lowest dose (150 mg twice daily).', 'No dosage adjustment required in mild to moderate renal disease; in severe renal failure (CrCl < 10 mL/min), reduce dose.', 'Dose must be reduced by 50% in severe hepatic cirrhosis (clearance is heavily liver-dependent).', '[''Orally bioavailable equivalent to IV lidocaine, allowing chronic outpatient therapy for ventricular arrhythmias'', ''First-line orphan drug of choice for relieving severe muscle stiffness in myotonia congenita'', ''Specific targeted efficacy in Long QT syndrome type 3 (LQT3) by blocking late sodium current'']', '[''Narrow therapeutic window with high rate of neurological side effects (hand tremors, ataxia, dizziness)'', ''Requires dosing 3 times daily with food to prevent gastric irritation'']', '[''Oral cousin of lidocaine used for heart rhythm disturbances and muscle stiffness'', ''Always take with food or milk to prevent stomach upset; report hand tremors immediately'']', 'MEXI-letine: Modern Equivalent of eXtended-oral Lidocaine; Invaluable for Myotonia; Tremor signals Toxicity.', '-letine', 'mex-IL-e-teen', 'मेक्सिले-टिन', 'active', 'verified', NULL, NULL),
('lidocaine', 'Lidocaine (Lignocaine)', 'Lidocaine Hydrochloride 2%', 'Lidocaine hydrochloride', 'Lidocaine hydrochloride', 'Antiarrhythmics', 'The quintessential Class IB antiarrhythmic and amide local anesthetic, administered intravenously for acute ventricular arrhythmias during myocardial infarction or cardiac arrest, and topically for regional anesthesia.', '[''2% IV vial (20 mg/mL)'', ''1% IV vial (10 mg/mL)'', ''2% topical gel'', ''5% transdermal patch'', ''10% aerosol spray'']', '[''Solution for Injection'', ''Topical Gel'', ''Transdermal Patch'', ''Aerosol Spray'']', '[''Intravenous'', ''Topical'', ''Infiltration / Nerve Block'']', 'Binds to the intracellular pore of voltage-gated fast sodium channels (Nav1.5) in cardiac tissue, preferentially binding to open and inactivated channels in depolarized, ischemic, or rapidly firing myocardium; shortens action potential duration and effective refractory period.', 'Suppresses abnormal ventricular automaticity and re-entrant circuits in ischemic myocardium without depressing AV nodal conduction or cardiac contractility; topically blocks sodium channels in sensory nerve fibers, producing reversible local anesthesia.', 'Negligible oral bioavailability (<3%) due to massive hepatic first-pass metabolism; administered parenterally or topically.', 'Rapidly distributes into well-perfused organs (brain, heart, liver), followed by muscle and fat; volume of distribution approx. 1.5 L/kg; 60-80% bound to plasma alpha-1 acid glycoprotein.', 'Extensively metabolized in the liver (>95%) by CYP3A4 and CYP1A2 to active de-ethylated metabolites (monoethylglycinexylidide - MEGX, and glycinexylidide - GX) which possess convulsant and antiarrhythmic properties.', 'Excreted in urine (approx. 90% as metabolites; less than 5% as unchanged parent drug).', '<3% (oral); 100% (IV)', '1.5 to 2 hours (prolonged to 4-10 hours in heart failure, cardiogenic shock, or severe hepatic disease)', '60% to 80%', 'Immediate (IV bolus: 45 to 90 seconds)', '10 to 20 minutes after single IV bolus; requires continuous infusion', '[''Acute treatment of ventricular tachycardia (VT) and ventricular fibrillation (VF) during cardiac arrest (alternative to amiodarone)'', ''Ventricular arrhythmias complicating acute myocardial infarction or cardiac surgery'', ''Local and regional infiltration anesthesia, peripheral nerve blocks, and epidural anesthesia'', ''Post-herpetic neuralgia (5% lidocaine transdermal patch)'', ''Topical anesthesia of mucosal membranes'']', '[''Severe sinoatrial, atrioventricular, or intraventricular heart block without pacemaker'', ''Stokes-Adams syndrome or Wolff-Parkinson-White syndrome'', ''Known hypersensitivity to amide-type local anesthetics'']', '[''LOCAL ANESTHETIC SYSTEMIC TOXICITY (LAST): Accidental intravenous injection during nerve block or excessive infusion causes CNS toxicity (circumoral numbness, tinnitus, metallic taste, seizures) followed by cardiovascular collapse; treat immediately with 20% INTRAVENOUS LIPID EMULSION'', ''Hepatic clearance is blood-flow dependent: drastically reduce maintenance infusion rate in heart failure, cardiogenic shock, or cirrhosis'', ''Narrow therapeutic window: therapeutic serum levels 1.5 to 5.0 mcg/mL (toxic > 5.0 mcg/mL)'']', '[''Drowsiness / sedation'', ''Dizziness'', ''Metallic taste'', ''Circumoral paresthesias (tingling around lips and tongue - warning sign of toxicity)'', ''Tinnitus (ringing in ears)'']', '[''Grand mal seizures / convulsions'', ''Respiratory depression / arrest'', ''Cardiovascular collapse / asystole'', ''Severe malignant hyperthermia (rare)'']', '[''Beta-blockers (propranolol/metoprolol decrease hepatic blood flow, increasing lidocaine levels and toxicity)'', ''Cimetidine (inhibits CYP3A4, increasing lidocaine levels)'', ''Amiodarone (additive myocardial depression and neurotoxicity)'']', '[''Continuous ECG telemetry and automated blood pressure monitoring during IV infusion'', ''Serum lidocaine levels if infusion exceeds 24 hours (therapeutic range: 1.5 to 5.0 mcg/mL)'', ''Monitor mental status for early neurotoxicity (tinnitus, slurred speech, confusion)'']', 'Category B; widely used for epidural and infiltration anesthesia in labor and delivery with excellent safety.', 'Excreted in breast milk in low levels; compatible with breastfeeding.', 'Approved in pediatric resuscitation (1 mg/kg IV/IO initial bolus, followed by 20-50 mcg/kg/min infusion).', 'Lower volume of distribution and reduced hepatic clearance; decrease initial bolus and maintenance infusion by 50%.', 'No dosage adjustment for initial bolus; metabolites accumulate in severe renal failure with prolonged infusion (>24h).', 'Reduce maintenance infusion rate by 50% in severe hepatic disease or cardiogenic shock (decreased liver perfusion).', '[''Rapid onset within 60 to 90 seconds for acute ventricular arrhythmias in the ICU or cardiac arrest'', ''Does not worsen AV nodal conduction or reduce systemic blood pressure compared to amiodarone'', ''Universal versatile local anesthetic available in gels, sprays, patches, and injectables'']', '[''Zero oral bioavailability (requires continuous IV infusion)'', ''High risk of central nervous system toxicity and seizures with rapid infusions or overdose'']', '[''First sign of lidocaine toxicity is numbness around the lips, metallic taste, and ringing in the ears'', ''Rescue antidote for accidental overdose/cardiac arrest is 20% Intravenous Lipid Emulsion'']', 'LIDO-caine: Local & IV antiarrhythmic; Ischemic tissue preference; Danger: Overdose causes Seizures (treat with Lipids).', '-caine', 'LYE-doe-kane', 'लिडो-केन', 'active', 'verified', NULL, NULL),
('rivaroxaban', 'Rivaroxaban', 'Rivaroxaban', 'Rivaroxaban', 'Rivaroxaban', 'Anticoagulants', 'An oral direct factor Xa inhibitor (DOAC) taken once daily with the evening meal for stroke prevention in non-valvular atrial fibrillation and treatment/prevention of deep vein thrombosis and pulmonary embolism.', '[''2.5 mg'', ''10 mg'', ''15 mg'', ''20 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Selectively, reversibly, and competitively inhibits free and clot-bound factor Xa and prothrombinase activity; blocks the intrinsic and extrinsic coagulation pathways, preventing thrombin generation and fibrin clot propagation.', 'Produces predictable anticoagulation without requiring routine coagulation monitoring (INR); prolonged anti-Xa effect provides reliable 24-hour thromboprophylaxis.', 'Rapidly absorbed; peak plasma concentration in 2 to 4 hours; bioavailability for 10 mg is 80-100% (unaffected by food); bioavailability for 15 mg and 20 mg is approx. 66% fasting, but increases to near 100% WHEN TAKEN WITH FOOD (mandatory to take 15 mg and 20 mg with a meal).', 'Apparent volume of distribution approx. 50 L; high plasma protein binding (92-95%, predominantly albumin).', 'Metabolized in the liver (approx. 66%) via CYP3A4, CYP2J2, and CYP-independent hydrolysis.', 'Eliminated by dual pathways: approx. 36% excreted unchanged in urine; remainder excreted as inactive metabolites in urine (approx. 30%) and faeces (approx. 30%).', '80% to 100% (10 mg); 15 mg and 20 mg MUST BE TAKEN WITH FOOD to achieve 100% bioavailability', '5 to 9 hours in young adults; 11 to 13 hours in elderly patients', '92% to 95%', '2 to 4 hours', '24 hours', '[''Stroke and systemic embolism prevention in non-valvular atrial fibrillation (20 mg once daily with the evening meal)'', ''Treatment of deep vein thrombosis (DVT) and pulmonary embolism (PE) (15 mg BID with food for 21 days, then 20 mg once daily with food)'', ''Secondary prevention of recurrent DVT and PE (10 mg or 20 mg once daily)'', ''Prophylaxis of DVT/PE following elective hip or knee replacement surgery (10 mg once daily)'', ''Reduction of major cardiovascular events in stable CAD or PAD (2.5 mg twice daily combined with aspirin - COMPASS trial)'']', '[''Active clinically significant pathological bleeding (intracranial hemorrhage, active GI bleed)'', ''Lesion or condition carrying significant risk of major bleeding (recent gastrointestinal ulceration, brain neoplasm)'', ''Concomitant treatment with other anticoagulants'', ''Hepatic disease associated with coagulopathy and clinically relevant bleeding risk (Child-Pugh B and C)'', ''Pregnancy and breastfeeding'', ''Prosthetic mechanical heart valves or moderate-to-severe mitral stenosis'']', '[''Black box warning: Premature discontinuation of rivaroxaban in atrial fibrillation increases the risk of thrombotic stroke (always provide bridge coverage if discontinued)'', ''Black box warning: Epidural or spinal hematomas can occur in patients receiving neuraxial anesthesia or spinal puncture, leading to long-term or permanent paralysis (delay catheter removal based on drug half-life)'', ''FOOD REQUIREMENT: The 15 mg and 20 mg tablets MUST be taken with food; fasting drops bioavailability by 35%, leading to under-anticoagulation and stroke'']', '[''Bleeding (epistaxis, gingival bleeding, bruising, hematuria, gastrointestinal bleeding)'', ''Nausea'', ''Dyspepsia'', ''Headache'', ''Elevated transaminases'']', '[''Fatal or major intracranial hemorrhage'', ''Retroperitoneal or gastrointestinal bleeding'', ''Spinal / epidural hematoma with paralysis'', ''Severe thrombocytopenia (rare)'']', '[''Combined P-gp and strong CYP3A4 inhibitors (ketoconazole, itraconazole, ritonavir - avoid combination due to high bleeding risk)'', ''Combined P-gp and strong CYP3A4 inducers (rifampin, carbamazepine, phenytoin - reduce rivaroxaban levels by 50%; avoid)'', ''Antiplatelets, NSAIDs, SSRIs (significantly increase gastrointestinal bleeding risk)'']', '[''Renal function (creatinine clearance via Cockcroft-Gault equation) at baseline and at least annually'', ''Complete blood count (hemoglobin and hematocrit) to detect occult bleeding'', ''Specific reversal agent: Andexanet alfa (approved for life-threatening Factor Xa bleeding)'']', 'Contraindicated in pregnancy; crosses placenta; causes maternal bleeding and fetal harm.', 'Contraindicated during breastfeeding; excreted in human breast milk.', 'Approved for treatment of venous thromboembolism in pediatric patients (weight-adjusted oral suspension).', 'Higher plasma levels due to age-related decline in renal function; evaluate bleeding risk.', 'Dose adjustment based on CrCl: CrCl 15-50 mL/min: reduce dose to 15 mg once daily with the evening meal; CrCl < 15 mL/min: avoid use.', 'Contraindicated in Child-Pugh B and C hepatic impairment or any liver disease with preexisting coagulopathy.', '[''Convenient once-daily dosing with the evening meal for atrial fibrillation'', ''Does not require routine INR blood monitoring or dietary vitamin K restrictions (unlike warfarin)'', ''Lower risk of fatal intracranial hemorrhage compared to warfarin in clinical trials'', ''Specific reversal agent (Andexanet alfa) available for emergencies'']', '[''The 15 mg and 20 mg doses MUST be taken with food or absorption drops drastically'', ''Slightly higher rate of gastrointestinal bleeding than dabigatran or apixaban'']', '[''CRITICAL RULE: The 15 mg and 20 mg tablets MUST be taken with dinner (food is required for absorption)'', ''Never stop this medication without consulting your doctor (sudden stopping causes strokes)'']', 'RIVAROXA-ban: Reversible Inactivator of Xa; Administer with evening Meal; Beware stopping suddenly.', '-xaban', 'ri-va-ROX-a-ban', 'रिवारोक्सा-बैन', 'active', 'verified', NULL, NULL),
('apixaban', 'Apixaban', 'Apixaban', 'Apixaban', 'Apixaban', 'Anticoagulants', 'An oral direct factor Xa inhibitor (DOAC) taken twice daily, proven in the landmark ARISTOTLE trial to be superior to warfarin in reducing stroke, major bleeding, and all-cause mortality in atrial fibrillation.', '[''2.5 mg'', ''5 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Potent, reversible, direct, and highly selective inhibitor of free and clot-bound factor Xa and prothrombinase; decreases thrombin generation and prevents fibrin thrombus development.', 'Reduces stroke, systemic embolism, and mortality in non-valvular atrial fibrillation (ARISTOTLE trial: 21% stroke reduction, 31% major bleeding reduction, 11% all-cause mortality reduction compared to warfarin); safest bleeding profile among oral anticoagulants.', 'Rapidly absorbed; peak plasma concentration in 3 to 4 hours; 50% absolute oral bioavailability; absorption is completely unaffected by food.', 'Apparent volume of distribution approx. 21 L; 87% bound to human plasma proteins.', 'Metabolized in the liver (approx. 25%) primarily by CYP3A4/5, with minor contributions from CYP1A2, 2C8, 2C9, 2C19, and sulfotransferases.', 'Eliminated by multiple pathways: renal excretion accounts for approx. 27% of total clearance; biliary and direct intestinal excretion account for approx. 73% in faeces.', 'Approximately 50% (unaffected by food)', '12 hours (terminal half-life 8 to 15 hours)', '87%', '3 to 4 hours', '12 hours (dosed twice daily)', '[''Stroke and systemic embolism prevention in non-valvular atrial fibrillation (5 mg twice daily; 2.5 mg BID if dose-reduction criteria met)'', ''Treatment of deep vein thrombosis (DVT) and pulmonary embolism (PE) (10 mg BID for 7 days, then 5 mg BID)'', ''Prevention of recurrent DVT and PE (2.5 mg twice daily after 6 months of initial therapy)'', ''Deep vein thrombosis prophylaxis after elective hip or knee replacement surgery (2.5 mg BID)'']', '[''Active clinically significant pathological bleeding'', ''Severe hepatic disease with coagulopathy (Child-Pugh Class C)'', ''Hypersensitivity to apixaban'', ''Prosthetic mechanical heart valves'']', '[''Black box warning: Premature discontinuation increases the risk of thrombotic events and stroke'', ''Black box warning: Epidural or spinal hematomas leading to permanent paralysis in patients undergoing neuraxial procedures'', ''DOSE REDUCTION RULE: Reduce dose to 2.5 mg twice daily if the patient meets at least TWO of the following three criteria: (1) Age ≥ 80 years, (2) Body weight ≤ 60 kg, (3) Serum creatinine ≥ 1.5 mg/dL (133 micromol/L)'']', '[''Bleeding (epistaxis, hematoma, hematuria, gingival bleeding)'', ''Anemia'', ''Nausea'', ''Minor skin bruising'']', '[''Life-threatening intracranial hemorrhage (much lower rate than warfarin)'', ''Severe gastrointestinal bleeding'', ''Spinal/epidural hematoma with permanent paraplegia'']', '[''Combined strong CYP3A4 and P-gp inhibitors (ketoconazole, itraconazole, ritonavir - reduce apixaban to 2.5 mg BID, or avoid if already on 2.5 mg)'', "Combined strong CYP3A4 and P-gp inducers (rifampin, carbamazepine, St. John''s wort - avoid combination)", ''Aspirin, NSAIDs, antiplatelets (additive major bleeding risk)'']', '[''Renal function (serum creatinine) at baseline and annually'', ''Body weight (check for ≤ 60 kg threshold)'', ''Complete blood count (hemoglobin/hematocrit)'', ''Specific reversal agent: Andexanet alfa for life-threatening bleeding'']', 'Contraindicated in pregnancy; risk of maternal and fetal bleeding.', 'Excreted in breast milk; breastfeeding is not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Evaluate for the dose reduction criteria (Age ≥ 80 years); lowest bleeding risk DOAC in the elderly.', 'Only 27% renally eliminated: dose reduction to 2.5 mg BID applies if serum creatinine ≥ 1.5 mg/dL combined with age ≥80 or weight ≤60 kg; safe in end-stage renal disease / hemodialysis at 5 mg BID (or 2.5 mg BID if elderly/low weight).', 'Contraindicated in Child-Pugh C cirrhosis; no adjustment needed in Child-Pugh A or B without coagulopathy.', '[''Landmark ARISTOTLE trial proven: ONLY DOAC to demonstrate superior stroke reduction, superior bleeding safety, AND a statistically significant reduction in all-cause mortality compared to warfarin'', ''Safest gastrointestinal bleeding profile among all direct oral anticoagulants'', ''Lowest renal clearance dependency (only 27%), making it the safest DOAC for chronic kidney disease and hemodialysis'']', '[''Requires twice-daily dosing (morning and evening), requiring good patient compliance'', ''High prescription cost compared to generic warfarin'']', '[''Safest blood thinner for the brain and stomach; take one tablet every 12 hours with or without food'', ''Dose is reduced to 2.5 mg twice daily only if you meet 2 of 3 rules: Age 80+, Weight 60 kg or less, Creatinine 1.5+'']', 'APIXA-ban: All-cause mortality reduced (ARISTOTLE); Preferred in Impaired kidneys; Xa blocker; Age/weight/creatinine dose rules.', '-xaban', 'a-PIX-a-ban', 'अपिक्स-अ-बैन', 'active', 'verified', NULL, NULL),
('dabigatran', 'Dabigatran Etexilate', 'Dabigatran Etexilate Mesylate', 'Dabigatran etexilate mesylate', 'Dabigatran etexilate mesylate', 'Anticoagulants', 'An oral direct thrombin (Factor IIa) inhibitor prodrug proven in the RE-LY trial to reduce stroke in non-valvular atrial fibrillation, featuring the rapid specific reversal antidote idarucizumab (Praxbind).', '[''75 mg'', ''110 mg'', ''150 mg'']', '[''Capsule'']', '[''Oral'']', 'Converted by systemic and hepatic esterases to active dabigatran, a potent, competitive, reversible, direct inhibitor of free and clot-bound thrombin (factor IIa); blocks thrombin-mediated cleavage of fibrinogen to fibrin monomers and inhibits thrombin-induced platelet aggregation.', 'Produces rapid, predictable anticoagulation without requiring routine coagulation monitoring; landmark RE-LY trial proved 150 mg BID was superior to warfarin in preventing ischemic stroke and systemic embolism.', 'Rapidly absorbed; peak plasma concentration in 1 to 2 hours; absolute oral bioavailability is low (3-7%); capsules contain tartaric acid pellets to maintain acidic microenvironment; bioavailability INCREASES BY 75% IF CAPSULE IS OPENED (NEVER open, chew, or crush capsules).', 'Apparent volume of distribution approx. 50 to 70 L; low plasma protein binding (approx. 35%).', 'Prodrug dabigatran etexilate is hydrolyzed by esterases to active dabigatran; active dabigatran undergoes glucuronidation (approx. 20%) to active acylglucuronides; zero CYP450 metabolism.', 'Eliminated predominantly unchanged by the kidneys via glomerular filtration (approx. 80-85%); remainder in faeces.', '3% to 7% (low oral bioavailability)', '12 to 17 hours (prolonged up to 28-34 hours in severe renal failure)', '35%', '1 to 2 hours', '12 hours (dosed twice daily)', '[''Stroke and systemic embolism prevention in non-valvular atrial fibrillation (150 mg BID; 110 mg BID or 75 mg BID based on renal function)'', ''Treatment and secondary prevention of deep vein thrombosis and pulmonary embolism following 5-10 days of parenteral anticoagulation'', ''DVT and PE prophylaxis following total hip or knee replacement surgery'']', '[''Active clinically significant bleeding'', ''Prosthetic mechanical heart valves (RE-ALIGN trial showed increased thromboembolism and bleeding with dabigatran)'', ''Severe renal impairment (CrCl < 15 mL/min)'', ''Known hypersensitivity to dabigatran etexilate'']', '[''Black box warning: Premature discontinuation increases the risk of stroke'', ''Black box warning: Epidural or spinal hematomas leading to permanent paralysis'', ''CAPSULE INTEGRITY RULE: NEVER open, break, crush, or chew the capsules; taking the pellets outside the capsule shell increases bioavailability by 75% and causes massive bleeding'', ''Dyspepsia and GERD (tartaric acid core causes epigastric burning in up to 10-15% of patients)'', ''HEAVILY RENALLY ELIMINATED (80%): contraindication or major accumulation in renal failure'']', '[''Dyspepsia (heartburn, epigastric burning, indigestion in up to 15% due to tartaric acid core)'', ''Gastritis / abdominal pain'', ''Bleeding (epistaxis, bruising, GI bleeding)'', ''Nausea'']', '[''Major gastrointestinal hemorrhage (higher rate than warfarin or apixaban)'', ''Fatal intracranial hemorrhage (substantially lower than warfarin)'', ''Spinal/epidural hematoma with paralysis'']', '[''P-glycoprotein inhibitors (dronedarone, ketoconazole - significantly increase dabigatran levels; reduce dose or avoid)'', "P-glycoprotein inducers (rifampin, carbamazepine, St. John''s wort - drastically decrease dabigatran levels by 65%; avoid)", ''Aspirin, NSAIDs, antiplatelets (major gastrointestinal bleeding risk)'']', '[''Renal function (creatinine clearance via Cockcroft-Gault equation) at baseline and every 6-12 months'', ''Complete blood counts'', ''Specific antidote available: Idarucizumab (Praxbind - humanized antibody fragment reverses dabigatran in minutes)'']', 'Contraindicated in pregnancy; crosses placenta; causes fetal bleeding risks.', 'Excretion in breast milk unknown; breastfeeding not recommended.', 'Approved for treatment of venous thromboembolism in pediatric patients (age-adjusted pellets).', 'Higher risk of bleeding due to age-related decline in creatinine clearance; consider 110 mg BID in patients ≥80 years.', 'CrCl 30-50 mL/min: 150 mg BID or 110 mg BID (reduce to 75 mg BID if taking P-gp inhibitor); CrCl 15-30 mL/min: 75 mg BID; CrCl < 15 mL/min: contraindicated.', 'No dosage adjustment required in mild to moderate hepatic impairment (not metabolized by CYP enzymes).', '[''Landmark RE-LY trial proved 150 mg BID is superior to warfarin in preventing ischemic stroke'', ''Possesses the fastest, most specific reversal antidote: Idarucizumab (Praxbind) reverses anticoagulation within minutes for emergency surgery'', ''Does not interact with cytochrome P450 enzymes'']', '[''80% eliminated by kidneys; dangerous drug accumulation in acute kidney injury'', ''Highest rate of dyspepsia/heartburn (10-15%) and gastrointestinal bleeding among DOACs'', ''Capsules are sensitive to moisture: must be stored in original bottle or blister pack'']', '[''Swallow capsules whole with a full glass of water; NEVER open, chew, or crush the capsules'', ''Specific antidote Praxbind (idarucizumab) can completely reverse this blood thinner in minutes for emergency surgery'']', 'DABIGA-tran: Direct Anti-thrombin IIa; Best stroke reduction (RE-LY 150mg); Idarucizumab reversal; Gut burning (dyspepsia); Avoid crushing.', '-gatran', 'da-bi-GA-tran', 'डाबिगा-ट्रान', 'active', 'verified', NULL, NULL),
('edoxaban', 'Edoxaban', 'Edoxaban Tosylate', 'Edoxaban tosylate', 'Edoxaban tosylate', 'Anticoagulants', 'A once-daily oral direct factor Xa inhibitor proven in the ENGAGE AF-TIMI 48 trial for stroke prevention in atrial fibrillation and treatment of venous thromboembolism.', '[''15 mg'', ''30 mg'', ''60 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Selectively and competitively inhibits factor Xa, blocking the conversion of prothrombin to thrombin; inhibits both free and clot-associated factor Xa activity, suppressing coagulation cascades.', 'Reduces stroke, systemic embolism, and major bleeding compared to warfarin (ENGAGE AF-TIMI 48 trial); demonstrates a unique upper limit of renal function (decreased efficacy in super-normal renal clearance).', 'Rapidly absorbed; peak plasma concentration in 1 to 2 hours; 62% oral bioavailability; unaffected by food.', 'Apparent volume of distribution approx. 107 L; 55% bound to plasma proteins.', 'Metabolized minimally by CYP3A4 (<10%) and hydrolysis; primary circulating moiety is unchanged edoxaban (>90%).', 'Eliminated by both renal excretion (approx. 50%) and biliary/intestinal excretion (approx. 50%).', '62%', '10 to 14 hours', '55%', '1 to 2 hours', '24 hours (once daily)', '[''Stroke and systemic embolism prevention in non-valvular atrial fibrillation (60 mg once daily; reduce to 30 mg OD if CrCl 15-50 mL/min, weight ≤ 60 kg, or with certain P-gp inhibitors)'', ''Treatment of deep vein thrombosis (DVT) and pulmonary embolism (PE) following 5-10 days of initial parenteral anticoagulation'']', '[''Active clinically significant bleeding'', ''Mechanical prosthetic heart valves'', ''Severe hepatic impairment with coagulopathy'', ''CrCl > 95 mL/min for the atrial fibrillation indication (FDA black box warning)'']', '[''Black box warning: REDUCED EFFICACY IN ATRIAL FIBRILLATION PATIENTS WITH CrCl > 95 mL/min (super-normal renal clearance clears edoxaban too rapidly, resulting in higher ischemic stroke rates compared to warfarin; do not use if CrCl > 95 mL/min)'', ''Black box warning: Premature discontinuation increases the risk of stroke'', ''Black box warning: Epidural or spinal hematomas leading to permanent paralysis'']', '[''Bleeding (epistaxis, hematuria, skin hematoma)'', ''Anemia'', ''Rash'', ''Elevated liver enzymes'']', '[''Major gastrointestinal or intracranial bleeding'', ''Spinal / epidural hematoma with paralysis'', ''Acute interstitial nephritis (rare)'']', '[''P-gp inhibitors (cyclosporine, dronedarone, erythromycin, ketoconazole - reduce edoxaban dose to 30 mg OD)'', ''P-gp inducers (rifampin, carbamazepine - avoid combination)'', ''Antiplatelets, NSAIDs (elevate bleeding risk)'']', '[''Creatinine clearance via Cockcroft-Gault equation mandatory prior to initiation (must be ≤ 95 mL/min for AF indication)'', ''Complete blood count and hemoglobin'', ''Liver function tests'']', 'Contraindicated in pregnancy; risk of maternal and fetal hemorrhage.', 'Excreted in animal milk; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Evaluate renal clearance and body weight; reduce dose to 30 mg OD if weight ≤ 60 kg.', 'UNIQUE RENAL RULE: Do NOT use in AF if CrCl > 95 mL/min; if CrCl 15-50 mL/min, reduce dose to 30 mg once daily; contraindicated if CrCl < 15 mL/min.', 'Contraindicated in Child-Pugh Class B and C hepatic impairment.', '[''Convenient once-daily dosing for both atrial fibrillation and DVT/PE treatment'', ''Lower rates of major bleeding and cardiovascular mortality compared to warfarin in ENGAGE AF'', ''Balanced 50:50 renal and biliary elimination'']', '[''Black box warning against use in patients with high renal function (CrCl > 95 mL/min) due to excessive clearance and stroke'', ''Requires 5 days of parenteral heparin bridging before starting in DVT/PE'']', '[''Take once daily with or without food'', ''Do NOT take this drug for atrial fibrillation if your kidney clearance is over 95 mL/min (it clears too fast to protect against strokes)'']', 'EDOXA-ban: Eliminates Xa Once daily; Danger: Ineffective if CrCl > 95 mL/min; Appropriate 50:50 dual clearance.', '-xaban', 'e-DOX-a-ban', 'एडोक्सा-बैन', 'active', 'verified', NULL, NULL),
('fondaparinux', 'Fondaparinux', 'Fondaparinux Sodium', 'Fondaparinux sodium', 'Fondaparinux sodium', 'Anticoagulants', 'A synthetic pentasaccharide that selectively binds antithrombin III to inhibit factor Xa, providing parenteral anticoagulation without causing heparin-induced thrombocytopenia (HIT).', '[''2.5 mg/0.5 mL'', ''5 mg/0.4 mL'', ''7.5 mg/0.6 mL'', ''10 mg/0.8 mL prefilled syringes'']', '[''Solution for Subcutaneous Injection'']', '[''Subcutaneous'']', 'Synthetic pentasaccharide sequence that selectively and irreversibly binds to antithrombin III (ATIII), inducing a conformational change that accelerates ATIII-mediated neutralization of factor Xa by 300-fold; does NOT inactivate thrombin (factor IIa) and does NOT bind to platelet factor 4 (PF4).', 'Produces potent, dose-dependent inhibition of factor Xa, suppressing thrombin generation and clot formation; completely lacks cross-reactivity with HIT antibodies, making it the premier non-heparin parenteral anticoagulant for HIT.', 'Rapidly and completely absorbed following subcutaneous injection; 100% absolute bioavailability; peak plasma concentration in 2 hours.', 'Volume of distribution is small (approx. 7 to 11 L); highly bound to antithrombin III in plasma (>94%).', 'Not metabolized by the liver; does not inhibit or induce CYP450 enzymes.', 'Excreted almost entirely unchanged in urine via glomerular filtration (approx. 64-77% within 72 hours).', '100% (subcutaneous)', '17 to 21 hours (allows convenient once-daily subcutaneous administration)', '>94% (to antithrombin)', '2 hours', '24 hours', '[''Prophylaxis of deep vein thrombosis in patients undergoing hip fracture surgery, hip/knee replacement, or abdominal surgery (2.5 mg SC once daily)'', ''Treatment of acute deep vein thrombosis and pulmonary embolism (combined with warfarin or oral transition: 5 mg if <50 kg, 7.5 mg if 50-100 kg, 10 mg if >100 kg)'', ''Acute coronary syndromes (unstable angina, NSTEMI, STEMI - OASIS-5 and OASIS-6 trials: lower bleeding and mortality than enoxaparin)'', ''Off-label treatment of Heparin-Induced Thrombocytopenia (HIT)'']', '[''Severe renal impairment (creatinine clearance < 30 mL/min - strictly contraindicated due to fatal accumulation)'', ''Active major clinically significant bleeding or bacterial endocarditis'', ''Body weight < 50 kg for thromboprophylaxis in surgical patients (increased major bleeding risk)'', ''Severe thrombocytopenia or hypersensitivity to fondaparinux'']', '[''Black box warning: Epidural or spinal hematomas leading to long-term or permanent paralysis in patients undergoing neuraxial anesthesia'', ''STRICT CONTRAINDICATION IN CrCl < 30 mL/min (exclusively cleared by kidneys; half-life extends to 40 hours with major bleeding)'', ''Catheter thrombosis risk during percutaneous coronary intervention (PCI): requires unfractionated heparin adjunct during PCI'', ''No specific antidote exists (protamine sulfate does NOT reverse fondaparinux)'']', '[''Bleeding / hematoma at injection site'', ''Anemia'', ''Hypokalemia'', ''Fever'', ''Nausea'']', '[''Major life-threatening hemorrhage'', ''Spinal / epidural hematoma with paraplegia'', ''Severe thrombocytopenia (rare; does NOT cause HIT)'']', '[''Antiplatelet agents, NSAIDs, oral anticoagulants (drastically increase bleeding risk)'', ''Thrombolytics (tissue plasminogen activators - extreme hemorrhage risk)'']', '[''Renal function (creatinine clearance via Cockcroft-Gault) prior to EVERY course (contraindicated if CrCl < 30 mL/min)'', ''Complete blood count (hemoglobin and hematocrit)'', ''Anti-Xa fondaparinux assay (if monitoring required in special situations)'']', 'Category B; does not cross placenta in significant amounts; safe alternative for heparin-allergic pregnant women.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Approved for treatment of pediatric venous thromboembolism (0.1 mg/kg once daily SC).', 'Higher risk of drug accumulation and bleeding due to reduced GFR; monitor CrCl closely.', 'STRICTLY CONTRAINDICATED if CrCl < 30 mL/min; use with caution if CrCl 30-50 mL/min.', 'No dosage adjustment required in hepatic impairment (cleared 100% by kidneys).', '[''Synthetic pentasaccharide structure does NOT bind platelet factor 4, meaning ZERO risk of Heparin-Induced Thrombocytopenia (HIT)'', ''Landmark OASIS-5 trial in acute coronary syndromes proved 50% lower major bleeding and lower 30-day mortality compared to enoxaparin'', ''Once-daily subcutaneous dosing with prefilled syringes without requiring routine laboratory monitoring'']', '[''Protamine sulfate DOES NOT reverse fondaparinux (no specific antidote)'', ''Strictly contraindicated if kidney clearance is under 30 mL/min'']', '[''Synthetic non-heparin injection that will NOT cause low platelet reactions (HIT)'', ''Strictly contraindicated if your kidney function is below 30 mL/min; inject subcutaneously once daily'']', 'FONDA-parinux: Factor Xa Only Neutralized via antithrombin; Does not cause HIT; Avoid if CrCl < 30.', '-parinux', 'fon-da-PAR-i-nux', 'फ़ोन्डा-पैरिनक्स', 'active', 'verified', NULL, NULL),
('heparin', 'Heparin (Unfractionated Heparin - UFH)', 'Heparin Sodium Injection', 'Heparin sodium', 'Heparin sodium', 'Anticoagulants', 'A classical parenteral glycosaminoglycan anticoagulant that binds antithrombin III to inactivate thrombin and factor Xa, serving as the gold standard titratable agent for cardiopulmonary bypass, hemodialysis, and acute thromboembolism.', '[''1,000 units/mL'', ''5,000 units/mL'', ''10,000 units/mL'', ''25,000 units/mL vials'']', '[''Solution for Injection / Infusion'']', '[''Intravenous'', ''Subcutaneous'']', 'Binds via a unique pentasaccharide sequence to antithrombin III (ATIII), accelerating ATIII-mediated inactivation of thrombin (factor IIa) and factor Xa by 1,000-fold; requires a long polysaccharide chain (at least 18 saccharide units) to form a ternary bridge complex with thrombin.', 'Rapidly halts thrombus propagation, prevents fibrin formation, and prolongs the activated partial thromboplastin time (aPTT); immediate onset of anticoagulation allows acute surgical and interventional procedures.', 'Not absorbed orally (large negatively charged polysaccharide); administered exclusively by IV infusion or deep subcutaneous injection.', 'Confined primarily to the intravascular compartment; binds extensively to plasma proteins (macrophages, endothelial cells, PF4, vitronectin); volume of distribution approx. 0.06 L/kg (plasma volume).', 'Cleared by a rapid, saturable cellular uptake mechanism (reticuloendothelial system and endothelial cells), followed by slower, non-saturable first-order renal clearance.', 'Degraded products excreted in urine; non-renal cellular clearance predominates at therapeutic doses.', '100% (IV); approx. 30% (subcutaneous)', '30 to 90 minutes (dose-dependent: 30 min at 25 units/kg; 60 min at 100 units/kg; 150 min at 400 units/kg)', 'Extensive (to plasma proteins, endothelial cells, and PF4)', 'Immediate (IV bolus); 20 to 30 minutes (subcutaneous)', '2 to 6 hours after stopping IV infusion', '[''Prophylaxis and treatment of venous thromboembolism (deep vein thrombosis and pulmonary embolism)'', ''Anticoagulation during cardiopulmonary bypass surgery and percutaneous coronary intervention (PCI)'', ''Anticoagulation during hemodialysis and extracorporeal circulation'', ''Unstable angina and acute myocardial infarction'', ''Disseminated intravascular coagulation (DIC) with consumptive coagulopathy'']', '[''Severe thrombocytopenia or history of Heparin-Induced Thrombocytopenia (HIT Type II)'', ''Active uncontrollable bleeding (except when due to DIC)'', ''Suspected intracranial hemorrhage or recent eye/brain/spinal surgery'', ''Severe uncontrolled malignant hypertension'']', '["HEPARIN-INDUCED THROMBOCYTOPENIA (HIT Type II): Immune-mediated reaction (IgG antibodies against heparin-PF4 complex) causing catastrophic arterial and venous thrombosis (HITT / ''white clot syndrome'') with a >50% drop in platelets; STOP ALL HEPARIN IMMEDIATELY", ''Requires continuous monitoring of aPTT (target 1.5 to 2.5 times control: 60-80 seconds) or anti-Xa levels'', ''Protamine sulfate is the specific, rapid antidote (1 mg protamine reverses approx. 100 units of heparin)'', ''Osteoporosis with chronic use (>3-6 months)'']', '[''Bleeding / bruising'', ''Injection site hematoma'', ''Elevated transaminases (ALT/AST - transient, benign)'', ''Mild non-immune thrombocytopenia (HIT Type I - benign, transient)'']', '[''Heparin-Induced Thrombocytopenia with Thrombosis (HIT Type II - life-threatening)'', ''Fatal intracranial or retroperitoneal hemorrhage'', ''Osteoporotic vertebral compression fractures (chronic therapy)'', ''Severe anaphylactic shock'']', '[''Oral anticoagulants, antiplatelets, NSAIDs (dramatically increase major bleeding risk)'', ''Thrombolytics (extreme hemorrhage risk)'', ''Nitroglycerin IV infusion (may antagonize heparin effect, requiring higher doses)'']', '[''Activated partial thromboplastin time (aPTT) every 6 hours until therapeutic (target 1.5-2.5x control), then daily'', ''Platelet count at baseline and every 2 to 3 days from day 4 to 14 (screen for HIT)'', ''Hemoglobin and hematocrit daily'', ''Anti-Xa heparin assay (target 0.3 to 0.7 units/mL)'']', 'Category C; does NOT cross the placenta; historical anticoagulant of choice in pregnancy (safe for the fetus).', 'Does not pass into breast milk (large molecular weight); completely safe for breastfeeding.', 'Approved across all pediatric age groups; weight-based dosing and pediatric aPTT nomograms.', 'Higher risk of bleeding complications; lower initial bolus and cautious titration.', 'No dosage adjustment required for renal clearance at standard therapeutic doses (cellular RES clearance).', 'No specific dosage adjustment required; monitor aPTT closely.', '[''Immediate onset of action (within seconds of IV bolus) and short half-life (60-90 minutes) allow instant cessation for bleeding or urgent surgery'', ''100% completely and rapidly reversed by protamine sulfate (1 mg per 100 units)'', ''Safe in severe renal failure (eGFR < 15 mL/min) and dialysis where DOACs are contraindicated'']', '[''Requires continuous IV infusion and frequent laboratory blood draws (aPTT every 6 hours)'', ''High risk of life-threatening Heparin-Induced Thrombocytopenia (HIT Type II)'']', '[''Gold standard injectable blood thinner for hospitals, heart surgeries, and dialysis'', ''Can be immediately neutralized in seconds with protamine sulfate if bleeding occurs'']', 'HEPARIN: Halts factors IIa and Xa; Evaluated by aPTT; Platelet fall signals HIT; Antidote is Protamine; Rapid clearance; Incompatible with IM.', '-parin', 'HEP-a-rin', 'हेपारिन', 'active', 'verified', NULL, NULL),
('bivalirudin', 'Bivalirudin', 'Bivalirudin for Injection', 'Bivalirudin trifluoroacetate', 'Bivalirudin trifluoroacetate', 'Anticoagulants', 'A synthetic 20-amino acid parenteral direct thrombin inhibitor (hirudin analogue) with a 25-minute half-life, used as an alternative to heparin in percutaneous coronary intervention (PCI) and HIT.', '[''250 mg vial'']', '[''Lyophilized Powder for Solution for Injection / Infusion'']', '[''Intravenous'']', 'Binds specifically, reversibly, and directly to both the catalytic site and the anion-binding exosite I of circulating and clot-bound thrombin (factor IIa); cleavage of the bivalirudin Arg3-Pro4 bond by thrombin slowly restores thrombin active site function.', 'Inhibits thrombin-mediated fibrin clot formation, activation of factors V, VIII, and XIII, and thrombin-induced platelet aggregation; produces immediate, predictable anticoagulation measured by activated clotting time (ACT); does NOT bind PF4 (zero HIT risk).', 'Administered exclusively intravenously (IV bolus followed by continuous infusion); 100% bioavailability.', 'Confined predominantly to the intravascular extracellular space; volume of distribution approx. 0.2 L/kg; does not bind to plasma proteins.', 'Cleaved enzymatically by circulating proteases (approx. 80%) and renal degradation.', 'Eliminated by a combination of enzymatic degradation and renal excretion (approx. 20% unchanged parent drug in urine).', '100% (IV)', '25 minutes in patients with normal renal function (prolonged to 35 min in moderate renal impairment, 60 min in severe renal impairment)', '0%', 'Immediate upon IV bolus injection', '1 to 2 hours after stopping infusion', '[''Anticoagulation in adult patients undergoing percutaneous coronary intervention (PCI), including patients with heparin-induced thrombocytopenia (HIT)'', ''Patients with unstable angina / NSTEMI undergoing PCI or cardiac catheterization'', ''Alternative parenteral anticoagulant in patients with confirmed or suspected HIT undergoing cardiac surgery'']', '[''Active major bleeding'', ''Hypersensitivity to bivalirudin or hirudins'']', '[''Acute stent thrombosis risk: slightly higher incidence of acute stent thrombosis within the first 4 to 12 hours post-PCI compared to heparin + GPIIb/IIIa inhibitors (mitigate with post-PCI infusion)'', ''Dose reduction mandatory in renal impairment (infusion rate must be decreased based on GFR)'', ''No specific reversal agent exists (dialyzable; half-life is short at 25 minutes)'']', '[''Bleeding (puncture site hematoma, epistaxis, retroperitoneal bleeding)'', ''Hypotension'', ''Headache'', ''Nausea'', ''Back pain'']', '[''Major life-threatening hemorrhage'', ''Acute coronary stent thrombosis'', ''Severe anaphylactic shock (rare)'']', '[''Antiplatelets (aspirin, clopidogrel, ticagrelor - additive bleeding risk)'', ''Heparin, DOACs, warfarin (additive anticoagulation)'', ''Thrombolytic agents'']', '[''Activated Clotting Time (ACT) during PCI (target ACT 225 to 320 seconds)'', ''Renal function (serum creatinine / eGFR) to adjust continuous infusion rate'', ''Hemoglobin, hematocrit, and femoral puncture site for hematoma'']', 'Category B; limited human pregnancy data; use only if potential benefit justifies potential risk.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Safety and efficacy in pediatric patients not established.', 'Evaluate renal clearance; reduce maintenance infusion rate if GFR is diminished.', 'Dose adjustment required for continuous infusion: normal renal function: 1.75 mg/kg/h; CrCl 30-59 mL/min: 1.75 mg/kg/h (monitor ACT); CrCl 10-29 mL/min: reduce to 1.0 mg/kg/h; hemodialysis: reduce to 0.25 mg/kg/h.', 'No dosage adjustment required in hepatic disease.', '[''Direct thrombin inhibitor that does NOT require antithrombin III and does NOT cause HIT'', ''Substantially lower rates of major bleeding compared to heparin plus GPIIb/IIIa inhibitors in PCI (HORIZONS-AMI trial)'', ''Short 25-minute half-life enables rapid offset of anticoagulation without needing an antidote'']', '[''No specific reversal antidote exists (unlike heparin and protamine)'', ''Slightly higher risk of acute coronary stent thrombosis in the first few hours post-PCI'']', '[''Premier IV blood thinner for patients with heparin allergy (HIT) undergoing coronary stent procedures'', ''Clears from the body in under 1 hour after stopping the IV drip'']', 'BIVALI-rudin: Brief 25-min half-life; Invaluable for PCI; Versatile Alternative for HIT; Leaves via enzymatic & renal pathways.', '-irudin', 'bye-val-i-ROO-din', 'बाइवेली-रुडिन', 'active', 'verified', NULL, NULL),
('ticagrelor', 'Ticagrelor', 'Ticagrelor', 'Ticagrelor', 'Ticagrelor', 'Antiplatelets', 'A direct-acting, reversibly binding P2Y12 platelet inhibitor proven in the landmark PLATO trial to significantly reduce cardiovascular mortality, myocardial infarction, and stroke compared to clopidogrel.', '[''60 mg'', ''90 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Reversibly, allosterically, and non-competitively binds to the platelet P2Y12 adenosine diphosphate (ADP) receptor, locking the receptor in an inactive state; additionally inhibits equilibrative nucleoside transporter-1 (ENT1), increasing extracellular adenosine levels.', 'Produces rapid, potent, and predictable platelet inhibition (faster and more consistent than clopidogrel); extracellular adenosine elevation produces coronary vasodilation and cardioprotection (PLATO trial: 16% reduction in cardiovascular death).', 'Rapidly absorbed; peak plasma concentration in 1.5 hours; active metabolite AR-C124910XX peaks in 2.5 hours; 36% oral bioavailability; unaffected by food.', 'Apparent volume of distribution approx. 88 L; extensively bound to human plasma proteins (>99%).', 'Extensively metabolized in the liver by CYP3A4 and CYP3A5 to active metabolite AR-C124910XX (equally potent) and multiple inactive metabolites.', 'Excreted in faeces (approx. 58% via biliary route) and urine (approx. 26%, with <1% unchanged parent drug).', 'Approximately 36%', '7 hours (parent); active metabolite 9 hours (platelet function recovers within 3 to 5 days of discontinuation)', '>99%', 'Rapid antiplatelet onset within 30 to 60 minutes', '12 hours (dosed 90 mg twice daily; 60 mg BID after 1 year)', '[''Acute coronary syndromes (unstable angina, NSTEMI, STEMI - PLATO trial: 90 mg BID with low-dose aspirin)'', ''Patients undergoing percutaneous coronary intervention (PCI) with drug-eluting stents'', ''Secondary prevention in high-risk patients with prior myocardial infarction (PEGASUS-TIMI 54 trial: 60 mg twice daily)'', ''Acute ischemic stroke or high-risk TIA (combined with aspirin for 30 days - THALES trial)'']', '[''Active pathological bleeding (intracranial hemorrhage, peptic ulcer)'', ''History of intracranial hemorrhage'', ''Severe hepatic impairment'', ''Concurrent use of strong CYP3A4 inhibitors or inducers'']', '[''Black box warning: Significant bleeding risk (fatal and major hemorrhages)'', ''Black box warning: ASPIRIN DOSE RESTRICTION: Maintenance aspirin doses ABOVE 100 mg daily decrease the effectiveness of ticagrelor; ALWAYS co-prescribe with LOW-DOSE aspirin (75-100 mg once daily, NEVER 325 mg)'', ''Dyspnea: causes self-limiting sensation of shortness of breath in up to 10-15% (due to adenosine reuptake inhibition; rarely requires discontinuation)'', ''Ventricular pauses / bradycardia (sinoatrial pauses >3 seconds in initial days)'']', '[''Dyspnea (shortness of breath in 10-15% of patients due to adenosine elevation)'', ''Bleeding (epistaxis, bruising, hematoma, GI bleeding)'', ''Elevated serum uric acid (hyperuricemia / gout)'', ''Elevated serum creatinine'']', '[''Major / fatal intracranial hemorrhage'', ''Severe gastrointestinal bleeding'', ''Severe ventricular pauses / sinus bradycardia'']', '[''Aspirin: maintenance dose MUST NOT EXCEED 100 mg daily (high-dose aspirin blunts ticagrelor efficacy)'', ''Strong CYP3A4 inhibitors (ketoconazole, clarithromycin - increase ticagrelor levels; avoid)'', ''Strong CYP3A4 inducers (rifampin, carbamazepine, phenytoin - reduce ticagrelor levels; avoid)'', ''Simvastatin / lovastatin (ticagrelor increases statin levels; do not exceed 40 mg simvastatin)'']', '[''Platelet function / signs of bleeding'', ''Assess for dyspnea (distinguish benign adenosine dyspnea from pulmonary oedema / heart failure)'', ''Serum uric acid levels in patients with gout'', ''Baseline ECG for conduction pauses'']', 'Avoid in pregnancy; insufficient human safety data; use only if potential benefit justifies risk.', 'Excreted in animal milk; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Evaluate bleeding risk; no dose adjustment required based on age alone.', 'No dosage adjustment required in any degree of renal impairment (including dialysis).', 'No dosage adjustment required in mild hepatic impairment; contraindicated in severe cirrhosis.', '[''Landmark PLATO trial proven: superior to clopidogrel in reducing cardiovascular mortality, repeat heart attacks, and stent thrombosis'', ''Direct-acting and reversible: does NOT require hepatic bioactivation (unlike clopidogrel and prasugrel), eliminating CYP2C19 resistance'', ''Faster recovery of platelet function (3-5 days) before urgent surgery compared to clopidogrel (5-7 days)'']', '[''Requires twice-daily dosing (90 mg BID), risking compliance dropouts'', ''Frequent dyspnea (shortness of breath) in up to 15% of patients'', ''Strictly blunted by high-dose aspirin (>100 mg)'']', '[''Take 90 mg twice daily; MUST be paired with baby aspirin (75-100 mg), NEVER high-dose aspirin'', ''A feeling of mild shortness of breath is a common harmless side effect caused by adenosine'']', 'TICA-grelor: Twice-daily; Increases Adenosine (causes Dyspnea); Direct reversible P2Y12 block; Low-dose Aspirin only.', '-grelor', 'tye-ka-GREL-or', 'टिका-ग्रेलॉर', 'active', 'verified', NULL, NULL),
('prasugrel', 'Prasugrel', 'Prasugrel Hydrochloride', 'Prasugrel hydrochloride', 'Prasugrel hydrochloride', 'Antiplatelets', 'A potent, third-generation thienopyridine oral prodrug that irreversibly inhibits platelet P2Y12 receptors, proven in the TRITON-TIMI 38 trial to superiorly prevent stent thrombosis in acute coronary syndromes undergoing PCI.', '[''5 mg'', ''10 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Prodrug rapidly hydrolyzed by intestinal carboxylesterases to a thiolactone intermediate (R-95913), then converted in a single hepatic step by CYP3A4 and CYP2B6 to active metabolite R-138727; irreversibly binds to platelet P2Y12 ADP receptors, permanently blocking ADP-mediated GPIIb/IIIa receptor activation.', 'Produces faster, more potent, and more consistent platelet inhibition than clopidogrel (approx. 70-80% platelet inhibition compared to 30-50% with clopidogrel); eliminates the genetic CYP2C19 non-responder resistance seen with clopidogrel.', 'Rapidly absorbed (approx. 80%); peak active metabolite levels in 30 minutes; food delays peak level but does not decrease total AUC.', 'Active metabolite is highly bound to human serum albumin (>98%); volume of distribution approx. 44 to 68 L.', 'Rapidly and extensively metabolized: intestinal de-esterification followed by single-step hepatic CYP3A4/CYP2B6 oxidation to active metabolite R-138727.', 'Excreted as inactive metabolites in urine (approx. 68%) and faeces (approx. 27%); zero parent drug excreted.', 'Approximately 80% absorbed', 'Active metabolite elimination half-life is 7 hours; biological antiplatelet duration is 7 to 10 days (lifetime of the platelet)', '>98%', 'Rapid antiplatelet onset within 30 minutes', '7 to 10 days (requires 7-day discontinuation prior to elective surgery)', '[''Reduction of thrombotic cardiovascular events (including stent thrombosis) in patients with acute coronary syndrome (ACS: unstable angina, NSTEMI, STEMI) MANAGED WITH PERCUTANEOUS CORONARY INTERVENTION (PCI)'', ''Prevention of acute, subacute, and late stent thrombosis in drug-eluting stents (TRITON-TIMI 38 trial: 52% reduction in stent thrombosis)'']', '[''HISTORY OF STROKE OR TRANSIENT ISCHEMIC ATTACK (TIA - black box contraindication: TRITON trial showed significant net clinical harm and severe intracranial bleeding)'', ''Active pathological bleeding'', ''Known hypersensitivity to prasugrel or thienopyridines'']', '[''Black box warning: BLEEDING RISK: Can cause significant, sometimes fatal bleeding'', ''Black box warning: STRICTLY CONTRAINDICATED in patients with prior TIA or stroke'', ''Age ≥ 75 years: generally not recommended due to high risk of fatal intracranial bleeding (if essential, use reduced 5 mg maintenance dose)'', ''Body weight < 60 kg: requires reduced maintenance dose of 5 mg once daily (increased bleeding risk on 10 mg)'', ''Discontinue at least 7 days prior to elective coronary artery bypass graft (CABG) surgery'']', '[''Bleeding (epistaxis, hematoma, gastrointestinal bleeding, puncture site hemorrhage)'', ''Anemia'', ''Headache'', ''Nausea'', ''Rash'']', '[''Fatal intracranial hemorrhage'', ''Life-threatening gastrointestinal hemorrhage'', ''Thrombotic Thrombocytopenic Purpura (TTP - rare medical emergency)'']', '[''Warfarin, DOACs, NSAIDs, fibrinolytics (dramatically increase major bleeding risk)'', ''CYP inhibitors/inducers (minimal clinical impact because multiple CYP enzymes can form active metabolite)'']', '[''Platelet count and complete blood count (hemoglobin/hematocrit)'', ''Signs and symptoms of bleeding'', ''Assess body weight (cut to 5 mg if <60 kg) and age (avoid if ≥75 years)'']', 'Category B; use during pregnancy only if clearly needed.', 'Excretion in human milk unknown; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Generally not recommended in patients ≥75 years due to high bleeding risk; if deemed necessary, reduce dose to 5 mg once daily.', 'No dosage adjustment required in any degree of renal impairment (including end-stage renal disease).', 'No dosage adjustment required in mild to moderate hepatic impairment; not studied in severe cirrhosis.', '[''Landmark TRITON-TIMI 38 trial proven: cuts stent thrombosis in half (52% reduction) compared to clopidogrel in PCI patients'', ''Simple one-step bioactivation avoids CYP2C19 genetic resistance (works consistently in all patients)'', ''Once-daily oral tablet (10 mg daily) with rapid 30-minute onset'']', '[''STRICTLY CONTRAINDICATED in patients with prior TIA or stroke due to fatal brain bleeds'', ''Cannot be used medically for ACS unless the patient undergoes PCI'', ''Must stop 7 full days before heart bypass surgery'']', '[''Potent once-daily blood thinner specifically for patients who receive heart stents'', ''NEVER take this medication if you have EVER had a stroke or mini-stroke (TIA) in your life'']', 'PRASU-grel: Powerful Stent Thrombosis Protection; Avoid in Age ≥75; Stroke/TIA is STRICTLY Contraindicated; Under 60kg use 5mg.', '-grelor', 'PRA-soo-grel', 'प्रसु-ग्रेल', 'active', 'verified', NULL, NULL),
('cilostazol', 'Cilostazol', 'Cilostazol', 'Cilostazol', 'Cilostazol', 'Antiplatelets', 'A selective phosphodiesterase-3 (PDE3) inhibitor that suppresses platelet aggregation and produces arterial vasodilation, serving as the gold standard medical treatment for intermittent claudication.', '[''50 mg'', ''100 mg'']', '[''Tablet'']', '[''Oral'']', 'Selectively inhibits phosphodiesterase type 3 (PDE3), preventing cyclic AMP (cAMP) degradation in platelets and vascular smooth muscle; elevated cAMP activates protein kinase A (PKA), inhibiting platelet aggregation and producing potent arterial vasodilation; also inhibits vascular smooth muscle cell proliferation.', 'Significantly increases pain-free and maximal walking distance in patients with peripheral arterial disease and intermittent claudication; produces peripheral vasodilation, reduces vascular resistance, and inhibits vascular restenosis.', 'Rapidly absorbed; peak plasma concentrations in 2 to 4 hours; high-fat meals increase absorption by up to 90% (MUST BE TAKEN AT LEAST 30 MINUTES BEFORE OR 2 HOURS AFTER BREAKFAST AND DINNER).', 'Apparent volume of distribution approx. 2.4 L/kg; extensively bound to plasma proteins (95-98%, predominantly albumin).', 'Extensively metabolized in the liver by CYP3A4 and CYP2C19 to two active metabolites: 3,4-dehydrocilostazol (4-7x more potent antiplatelet) and 4''-trans-hydroxycilostazol.', 'Excreted predominantly in urine (approx. 74% as metabolites) and faeces (approx. 20%); less than 1% unchanged drug in urine.', 'Variable; high-fat meals increase Cmax by 90% (must take on an empty stomach)', '11 to 13 hours', '95% to 98%', 'Improvement in walking distance seen in 2 to 4 weeks; peak benefit at 12 weeks', '12 hours (dosed 100 mg twice daily on empty stomach)', '[''Reduction of symptoms of intermittent claudication in peripheral arterial disease (PAD - improves walking distance)'', ''Secondary prevention of non-cardioembolic ischemic stroke (established in Japan/Asia)'', ''Prevention of coronary stent restenosis (adjunct)'']', '[''CONGESTIVE HEART FAILURE OF ANY SEVERITY (black box contraindication: PDE3 inhibitors like milrinone/vesnarinone significantly increase mortality in heart failure)'', ''Known hypersensitivity to cilostazol'', ''Active pathological bleeding or hemostatic disorders'']', '[''Black box warning: CONTRAINDICATED IN HEART FAILURE OF ANY SEVERITY (decreases survival in patients with heart failure due to ventricular proarrhythmia)'', ''Take on an empty stomach (at least 30 minutes before or 2 hours after meals)'', ''Throbbing headache and palpitations during the first few weeks of therapy (titrate slowly: start 50 mg BID)'', ''Dose reduction to 50 mg BID required with CYP3A4 or CYP2C19 inhibitors'']', '[''Headache (very common: up to 30%, diminishes over time)'', ''Palpitations / tachycardia'', ''Diarrhoea and loose stools'', ''Dizziness'', ''Peripheral oedema'']', '[''Life-threatening ventricular arrhythmias (especially in underlying heart disease)'', ''Severe congestive heart failure decompensation'', ''Major bleeding (when combined with dual antiplatelets)'', ''Agranulocytosis / thrombocytopenia (rare)'']', '[''Strong CYP3A4 inhibitors (ketoconazole, itraconazole, erythromycin - reduce cilostazol to 50 mg BID)'', ''Strong CYP2C19 inhibitors (omeprazole - reduce cilostazol to 50 mg BID)'', ''Antiplatelets, anticoagulants (additive bleeding risk)'']', '[''Cardiovascular evaluation to STRICTLY RULE OUT congestive heart failure before initiating'', ''Measurement of pain-free and maximal walking distance at 12 weeks'', ''Complete blood counts (screen for leukopenia/thrombocytopenia)'']', 'Category C; teratogenic in animal models; avoid during pregnancy.', 'Excreted in animal milk; breastfeeding not recommended.', 'Safety and efficacy in pediatric patients not established.', 'Evaluate carefully for subclinical heart failure; monitor heart rate and palpitations.', 'No dosage adjustment required in mild to moderate renal failure; in severe renal impairment (CrCl < 25 mL/min), use with caution.', 'No dosage adjustment in mild hepatic impairment; use with caution in moderate to severe cirrhosis.', '[''Gold standard medical therapy for peripheral arterial disease (PAD), proven to double pain-free walking distance'', ''Dual antiplatelet and arterial vasodilator mechanisms without causing systemic hypotension'', ''Improves lipid profile (reduces triglycerides and increases HDL cholesterol)'']', '[''STRICTLY CONTRAINDICATED in congestive heart failure (causes death)'', ''High incidence of throbbing headaches and diarrhea during the first month'', ''Must be taken on an empty stomach twice daily'']', '[''Medicine to help you walk further without leg cramps (intermittent claudication)'', ''NEVER take if you have heart failure; always take 30 minutes before breakfast and dinner on an empty stomach'']', 'CILOST-azol: Claudication Improvement; Leg Oxygenation; Outlawed in heart failure; Stomach empty; Take twice daily.', '-azol', 'sye-LOE-sta-zol', 'सिलोस्टा-ज़ोल', 'active', 'verified', NULL, NULL),
('dipyridamole', 'Dipyridamole', 'Dipyridamole', 'Dipyridamole', 'Dipyridamole', 'Antiplatelets', 'A phosphodiesterase inhibitor and adenosine reuptake blocker, combined with low-dose aspirin (Aggrenox) for secondary prevention of stroke, and used intravenously as a pharmacologic stress agent.', '[''25 mg'', ''50 mg'', ''75 mg'', ''200 mg ER (combined with 25 mg aspirin)'', ''10 mg/2 mL IV ampoule'']', '[''Tablet'', ''Extended-Release Capsule'', ''Solution for Injection'']', '[''Oral'', ''Intravenous'']', 'Inhibits the uptake of adenosine into erythrocytes, platelets, and endothelial cells, increasing extracellular adenosine concentrations; also inhibits cyclic nucleotide phosphodiesterases (PDE5 and PDE3), increasing intracellular cAMP and cGMP; blocks thromboxane A2 synthesis.', 'Inhibits platelet aggregation and adhesion to damaged vascular endothelium; produces coronary arteriolar vasodilation (coronary steal phenomenon utilized in pharmacologic myocardial stress imaging); landmark ESPS-2 trial proved combined dipyridamole + aspirin reduced recurrent stroke by 37%.', 'Slow and variable oral absorption; modified-release capsules provide sustained 24-hour plasma concentrations; bioavailability approx. 37-66%; take with meals to reduce GI irritation.', 'Widely distributed; volume of distribution approx. 2 to 3 L/kg; highly bound to plasma proteins (>99%, primarily albumin and alpha-1 acid glycoprotein).', 'Extensively metabolized in the liver by glucuronidation to an inactive monoglucuronide and minor diglucuronide; undergoes substantial enterohepatic recirculation.', 'Excreted predominantly in faeces (approx. 95%) via biliary elimination; less than 1% unchanged drug in urine.', '37% to 66%', '10 to 12 hours (terminal half-life approx. 12 hours)', '>99%', 'Oral: 1 to 2 hours; IV: within minutes', '12 hours (extended-release formulation dosed twice daily)', '[''Secondary prevention of ischemic stroke and transient ischemic attack (TIA - combined with aspirin 25 mg as Aggrenox)'', ''Adjunct to coumarin anticoagulants in the prevention of postoperative thromboembolic complications of cardiac valve replacement'', ''Pharmacologic alternative to exercise in myocardial perfusion imaging (IV coronary vasodilator)'']', '[''Known hypersensitivity to dipyridamole'', ''Severe hypotension'', ''IV use contraindicated in bronchospastic lung disease / asthma'']', '[''CORONARY STEAL PHENOMENON: Dilates normal coronary vessels, potentially diverting blood flow AWAY from stenosed, ischemic myocardium (can precipitate acute angina in severe CAD)'', ''Severe throbbing vascular headache during initial therapy (titrate slowly or co-administer analgesics)'', ''Hypotension and syncope (peripheral vasodilator properties)'', ''Avoid caffeine and theophylline before IV stress testing (adenosine receptor antagonists)'']', '[''Throbbing headache (very common in first 2 weeks, occurs in up to 30-40%)'', ''Dizziness'', ''Diarrhoea and dyspepsia'', ''Facial flushing'', ''Nausea'', ''Palpitations'']', '[''Precipitation of acute myocardial ischemia / angina (coronary steal)'', ''Severe bronchospasm (during IV administration)'', ''Severe symptomatic hypotension / syncope'']', '[''Adenosine (dipyridamole significantly inhibits adenosine uptake, potentiating adenosine 4-fold; reduce adenosine IV dose to 3 mg)'', ''Cholinesterase inhibitors (dipyridamole may counteract the anticholinesterase effect in myasthenia gravis)'', ''Theophylline, caffeine (antagonize the coronary vasodilator effect of dipyridamole)'']', '[''Screening for recurrent neurological ischemic symptoms (stroke / TIA)'', ''Blood pressure and heart rate'', ''Monitor for persistent chest pain in patients with known coronary artery disease'']', 'Category B; widely used in pregnancy for thromboembolism prophylaxis with artificial heart valves.', 'Excreted in breast milk in low concentrations; compatible with caution.', 'Approved in children as an adjunct to aspirin in Kawasaki disease and thromboembolism with prosthetic valves.', 'Higher risk of orthostatic dizziness and falls; assess blood pressure.', 'No dosage adjustment required in renal impairment (cleared 95% by biliary route).', 'No dosage adjustment required in mild to moderate hepatic impairment.', '[''Landmark ESPS-2 trial proven: combined dipyridamole + aspirin cuts secondary stroke risk by 37% (superior to aspirin alone)'', ''Non-renal clearance (95% biliary) makes it safe in advanced renal disease'', ''Dual mechanism (adenosine reuptake inhibition + phosphodiesterase inhibition)'']', '[''High incidence of throbbing headaches causes up to 10-15% of patients to discontinue therapy'', ''Can induce coronary steal and chest pain in patients with severe triple-vessel coronary disease'']', '[''Used twice daily with baby aspirin to prevent second strokes (Aggrenox)'', ''Throbbing headaches are very common in the first week but usually disappear with continued use'']', 'DIPYRIDA-mole: Dual mechanism (PDE + Adenosine); Prevents recurrent stroke with Aspirin; Migraine-like headache.', '-amole', 'dye-peer-ID-a-mole', 'डिपिरिडा-मोल', 'active', 'verified', NULL, NULL),
('tranexamic-acid', 'Tranexamic Acid (TXA)', 'Tranexamic Acid Injection / Tablets', 'Tranexamic acid', 'Tranexamic acid', 'Hemostatics', 'A synthetic lysine analogue antifibrinolytic that reversibly blocks plasminogen activation, widely used to prevent and treat massive hemorrhage in trauma, surgery, and heavy menstrual bleeding.', '[''500 mg'', ''650 mg'', ''500 mg/5 mL IV ampoule'', ''1000 mg/10 mL IV ampoule'']', '[''Film-coated Tablet'', ''Solution for Injection'']', '[''Oral'', ''Intravenous'', ''Topical'']', 'Competitively and reversibly blocks the lysine-binding sites on plasminogen molecules, preventing plasminogen from binding to fibrin; inhibits the conversion of plasminogen to active plasmin and suppresses fibrin clot dissolution (fibrinolysis); at high concentrations, non-competitively inhibits plasmin.', 'Preserves the hemostatic fibrin clot, reduces surgical blood loss and transfusion requirements, and significantly reduces all-cause mortality in bleeding trauma patients when administered within 3 hours of injury (CRASH-2 trial: 15% relative reduction in mortality).', 'Moderately absorbed from GI tract (bioavailability approx. 35-50%); peak plasma concentration in 2 to 3 hours; food does not affect absorption.', 'Widely distributed into all tissues, synovial fluid, and crosses the blood-brain barrier into CSF (CSF concentration approx. 10% of plasma); 3% bound to plasma proteins (plasminogen).', 'Minimally metabolized in the liver (<5%); cleared predominantly unaltered by the kidneys.', 'Excreted almost entirely unchanged in urine via glomerular filtration (>95% within 24 hours).', '35% to 50% (oral); 100% (IV)', '2 to 3 hours (terminal elimination half-life)', '3%', 'IV: immediate (hemostatic effect within 15-30 minutes); Oral: 2 hours', '7 to 8 hours (tissue half-life up to 17 hours)', '[''Severe bleeding and traumatic hemorrhage within 3 hours of injury (CRASH-2 trial: 1 g IV bolus over 10 min, then 1 g infusion over 8 hours)'', ''Postpartum hemorrhage (WOMAN trial: 1 g IV within 3 hours of delivery)'', ''Heavy menstrual bleeding / menorrhagia (1300 mg oral TID during heavy flow days)'', ''Reduction of blood loss in major surgery (total hip/knee arthroplasty, cardiac surgery, spinal surgery)'', ''Tooth extractions in patients with hemophilia (mouthwash or oral tablets)'']', '[''Active thromboembolic disease (active DVT, pulmonary embolism, acute cerebral thrombosis)'', ''History of venous or arterial thromboembolism or active intrinsic thromboembolic risk'', ''Subarachnoid hemorrhage (risk of cerebral ischemia and hydrocephalus)'', ''Acquired defective color vision (cannot monitor optical toxicity)'', ''Severe hypersensitivity to tranexamic acid'']', '[''CRITICAL TIME WINDOW IN TRAUMA: Must be administered WITHIN 3 HOURS of injury (CRASH-2 trial showed mortality reduction when given within 3 hours, but INCREASED mortality if given after 3 hours)'', ''SEIZURES: High doses (especially in cardiac surgery) cause generalized seizures due to competitive antagonism of neuronal GABAA and glycine receptors (reduce dose in renal failure)'', ''Upper urinary tract bleeding: contraindicated in gross hematuria from kidney/ureters (risk of obstructive ureteral clot colic)'', ''Visual disturbances: baseline and periodic ophthalmologic examinations required in chronic therapy'']', '[''Nausea and vomiting'', ''Diarrhoea'', ''Abdominal pain'', ''Dizziness'', ''Headache'']', '[''Generalized tonic-clonic seizures (dose-dependent GABAA antagonism)'', ''Arterial or venous thromboembolism / pulmonary embolism'', ''Severe visual impairment / retinal vascular occlusion'', ''Anaphylactic shock'']', '[''Combined hormonal contraceptives (estrogen-containing pills/patches/rings - drastically increase thrombotic stroke and DVT risk; avoid combination)'', ''Prothrombin complex concentrates (PCC) or Factor IX (increased risk of fatal thrombosis)'', ''Thrombolytics (directly antagonize each other)'']', '[''Renal function (serum creatinine / eGFR) mandatory to adjust dose and prevent neurotoxic seizures'', ''Visual acuity, color vision, and visual fields in chronic therapy'', ''Clinical cessation of bleeding and vital signs'']', 'Category B; proven life-saving in postpartum hemorrhage (WOMAN trial); does not increase maternal or neonatal thrombosis.', 'Excreted in low levels in breast milk (approx. 1% of maternal serum); compatible with breastfeeding.', 'Approved in children for surgical and trauma bleeding (weight-adjusted dosing: 10-20 mg/kg).', 'High prevalence of reduced GFR; dose must be strictly adjusted based on serum creatinine to prevent seizures.', 'STRICT DOSE ADJUSTMENT IN RENAL IMPAIRMENT: Serum Cr 1.4-2.8 mg/dL: 50% dose reduction; Serum Cr 2.8-5.7 mg/dL: 75% dose reduction; Serum Cr > 5.7 mg/dL: 85% dose reduction.', 'No dosage adjustment required in hepatic impairment (eliminated >95% unchanged by kidneys).', '[''Landmark CRASH-2 and WOMAN trials proven: reduces mortality from trauma hemorrhage and postpartum bleeding by 15-30%'', ''Inexpensive, stable at room temperature, and versatile across multiple routes (IV, oral, topical, nebulized)'', ''Reduces transfusion requirements by 30-40% in orthopedic and cardiac surgeries'']', '[''High doses cause drug-induced seizures due to GABAA receptor blockade'', ''Must be given within 3 hours of trauma; harmful if administered after 3 hours'', ''Contraindicated with estrogen birth control pills'']', '[''World-standard clot-stabilizing drug that stops life-threatening bleeding in trauma and heavy periods'', ''In trauma or childbirth bleeding, it MUST be given within the first 3 hours to save lives'']', 'TRANEX-amic: Traps Clots (antifibrinolytic); Administer within 3 hours of trauma; No Estrogen pills; Excreted renally (seizure risk).', '-xamic', 'tran-ex-AM-ik AS-id', 'ट्रानेक्सामिक एसिड', 'active', 'verified', NULL, NULL),
('aminocaproic-acid', 'Aminocaproic Acid (Epsilon-Aminocaproic Acid - EACA)', 'Aminocaproic Acid Injection / Syrup', 'Aminocaproic acid', 'Aminocaproic acid', 'Hemostatics', 'A synthetic lysine analogue antifibrinolytic that competitively inhibits plasminogen activation, used for hyperfibrinolytic bleeding, cardiac surgery, and dental procedures in hemophiliacs.', '[''500 mg'', ''1000 mg'', ''250 mg/mL oral solution'', ''250 mg/mL (20 mL IV vial = 5 g)'']', '[''Tablet'', ''Oral Solution'', ''Solution for Injection'']', '[''Oral'', ''Intravenous'']', 'Competitively inhibits plasminogen activators (tissue plasminogen activator and urokinase) and blocks the lysine-binding sites on plasminogen, preventing its conversion to active plasmin; at high concentrations, directly inhibits plasmin.', 'Halts fibrinolysis, stabilizes formed hemostatic fibrin clots, and prevents excessive systemic or localized fibrinolytic hemorrhage; approx. 10-fold less potent than tranexamic acid on a gram-for-gram basis, requiring higher gram-scale dosing.', 'Rapidly and completely absorbed from GI tract (approx. 100% oral bioavailability); peak plasma levels in 1.2 hours; unaffected by food.', 'Distributes throughout both extravascular and intravascular compartments; volume of distribution approx. 23 to 30 L; low protein binding (approx. 10-15%).', 'Metabolized in small amounts by the liver (approx. 35% converted to adipic acid).', 'Excreted rapidly and predominantly unchanged in urine via glomerular filtration (approx. 65% within 24 hours).', '100% (oral)', '1 to 2 hours (short elimination half-life requires continuous IV infusion or frequent oral dosing)', '10% to 15%', 'Oral: 1 to 2 hours; IV: immediate', '3 to 4 hours (requires 4- to 6-hourly dosing)', '[''Excessive bleeding from systemic hyperfibrinolysis and urinary fibrinolysis'', ''Cardiac surgery / cardiopulmonary bypass (reduces perioperative bleeding and blood transfusion)'', ''Dental extractions in patients with hemophilia or on oral anticoagulants'', ''Refractory hematuria in patients with benign prostatic hyperplasia or bladder trauma'', ''Amelioration of bleeding in severe thrombocytopenia'']', '[''Active intravascular clotting / disseminated intravascular coagulation without heparin'', ''Upper urinary tract bleeding (risk of ureteral clot obstruction and hydronephrosis)'', ''Known hypersensitivity to aminocaproic acid'']', '[''RHABDOMYOLYSIS AND MYOPATHY: Prolonged administration (weeks to months) can cause severe skeletal muscle weakness, myopathy, necrosis, and rhabdomyolysis with acute myoglobinuric renal failure (monitor CPK)'', ''Rapid intravenous infusion can precipitate severe hypotension, bradycardia, and cardiac arrhythmias (infuse loading dose over at least 30-60 minutes)'', ''Never use in gross hematuria of upper urinary tract origin'']', '[''Nausea and vomiting'', ''Diarrhoea'', ''Cramping abdominal pain'', ''Nasal congestion'', ''Dizziness'', ''Headache'']', '[''Severe skeletal muscle myopathy / rhabdomyolysis'', ''Thrombosis / deep vein thrombosis / pulmonary embolism'', ''Severe hypotension / bradycardia (with rapid IV push)'', ''Renal failure'']', '[''Estrogens and oral contraceptives (markedly increase thrombotic risk)'', ''Prothrombin complex concentrates (PCC) or Factor IX (thrombosis risk)'', ''Thrombolytic agents (antagonism)'']', '[''Serum creatine phosphokinase (CPK) in patients receiving therapy for more than a few days'', ''Renal function (serum creatinine / BUN)'', ''Signs of muscle pain, tenderness, or weakness'']', 'Category C; use during pregnancy only if clearly needed.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Approved in children for hyperfibrinolytic bleeding and dental procedures (100 mg/kg loading dose, then 30-33 mg/kg/h).', 'Assess renal clearance; reduce dose in renal impairment.', 'Dose reduction required: accumulation occurs in renal insufficiency; monitor for myopathy and seizures.', 'No dosage adjustment required in hepatic impairment.', '[''100% oral bioavailability allows seamless transition from IV infusion to oral tablets/syrups'', ''Effective local hemostatic agent for mouthwashes and dental extractions in bleeding disorders'', ''Cost-effective established antifibrinolytic'']', '[''Requires large gram-scale doses (4-5 grams loading, then 1 gram every hour) due to lower potency than tranexamic acid'', ''Risk of skeletal muscle myopathy and rhabdomyolysis with prolonged use'']', '[''Injectable and oral clot protector used in open heart surgery and bleeding disorders'', ''Report any muscle soreness or dark brown urine immediately (muscle breakdown risk)'']', 'AMINO-caproic: Antifibrinolytic; Massive gram-scale dosing; Inhibits Plasminogen; Note CPK (rhabdomyolysis risk).', '-caproic', 'a-mee-noe-ka-PROE-ik AS-id', 'एमिनो-कैप्रोइक एसिड', 'active', 'verified', NULL, NULL),
('lansoprazole', 'Lansoprazole', 'Lansoprazole Delayed-Release', 'Lansoprazole', 'Lansoprazole', 'Gastrointestinal', 'A substituted benzimidazole proton pump inhibitor (PPI) that suppresses gastric acid secretion, used for GERD, peptic ulcers, and H. pylori eradication.', '[''15 mg'', ''30 mg'', ''30 mg orally disintegrating tablet (ODT)'']', '[''Delayed-Release Capsule'', ''Orally Disintegrating Tablet'']', '[''Oral'']', 'Accumulates in the acidic secretory canaliculi of parietal cells and converts to active sulfenamide; irreversibly binds via disulfide bonds to the H+/K+-ATPase proton pump, blocking the final step of acid secretion.', 'Inhibits both basal and stimulated gastric acid secretion by >80-90%; elevates intragastric pH above 4, promoting mucosal ulcer healing and enhancing antibiotic efficacy against H. pylori.', 'Rapidly absorbed; peak plasma concentration in 1.5 to 2 hours; 80-85% bioavailability on first dose; food reduces absorption by 50% (MUST BE TAKEN 30-60 MINUTES BEFORE BREAKFAST).', 'Apparent volume of distribution approx. 0.4 L/kg; 97% bound to human plasma proteins.', 'Extensively metabolized in the liver by CYP2C19 and CYP3A4 to inactive 5-hydroxylansoprazole and lansoprazole sulfone.', 'Excreted in faeces (approx. 67% via biliary elimination) and urine (approx. 33% as metabolites); zero unchanged drug in urine.', '80% to 85% (fasting; take before breakfast)', '1.5 hours in plasma; biological pump inhibition lasts 24 to 48 hours', '97%', 'Acid suppression begins within 1 to 2 hours', '24 hours', '[''Erosive esophagitis and gastroesophageal reflux disease (GERD)'', ''Gastric and duodenal ulcers'', ''Helicobacter pylori eradication (combined with clarithromycin and amoxicillin)'', ''NSAID-induced gastric ulcer healing and prevention'', ''Zollinger-Ellison syndrome (hypersecretory states)'']', '[''Known hypersensitivity to lansoprazole or substituted benzimidazoles'', ''Concomitant use with rilpivirine-containing products'']', '[''Must take 30-60 minutes before breakfast for maximal acid pump activation'', ''Long-term use risks: hypomagnesemia, vitamin B12 deficiency, Clostridioides difficile-associated diarrhoea, and bone fractures'', ''Do not crush or chew delayed-release granules (ODT tablets dissolve on tongue)'']', '[''Diarrhoea'', ''Abdominal pain'', ''Nausea'', ''Headache'', ''Constipation'', ''Flatulence'']', '[''Clostridioides difficile colitis'', ''Severe hypomagnesemia / tetany (with >1 year therapy)'', ''Acute interstitial nephritis (AIN)'', ''Subacute cutaneous lupus erythematosus (SCLE)'']', '[''Clopidogrel (CYP2C19 competition may modestly reduce active metabolite formation; lower interaction than omeprazole)'', ''Ketoconazole, itraconazole, atazanavir (reduced gastric acid impairs antifungal/antiretroviral absorption)'', ''Methotrexate (PPIs increase methotrexate levels)'']', '[''Serum magnesium levels prior to starting and annually in long-term therapy'', ''Serum vitamin B12 in chronic therapy (>2-3 years)'', ''Bone mineral density in high-risk osteoporosis patients'']', 'Category B; reassuring human pregnancy registry data; safe when clinically indicated.', 'Excreted in human milk in low amounts; compatible with breastfeeding.', 'Approved in children 1 year and older for GERD and erosive esophagitis (ODT formulation ideal for pediatric swallowing).', 'No dosage adjustment required based on age alone.', 'No dosage adjustment required in renal impairment.', 'Dose reduction to 15 mg daily recommended in severe hepatic cirrhosis.', '[''Orally disintegrating tablet (ODT) formulation dissolves on the tongue without water, ideal for pediatrics, dysphagia, and bedridden patients'', ''Highest first-dose bioavailability (80-85%) among classical PPIs'', ''Safer CYP2C19 interaction profile than omeprazole'']', '[''Requires strict pre-meal timing (30-60 minutes before breakfast)'', ''Long-term use carries risks of low magnesium, bone fractures, and gut infections'']', '[''Take 30 minutes before your morning meal for best acid relief'', ''Orally disintegrating tablet melts on the tongue without needing water'']', 'LANSO-prazole: Lasts 24 hours; Absorbs best before breakfast; Novel Orally disintegrating tablet available.', '-prazole', 'lan-SOE-pra-zole', 'लैन्सो-प्राज़ोल', 'active', 'verified', NULL, NULL),
('dexlansoprazole', 'Dexlansoprazole', 'Dexlansoprazole Dual Delayed Release', 'Dexlansoprazole', 'Dexlansoprazole', 'Gastrointestinal', 'An R-enantiomer proton pump inhibitor featuring Dual Delayed Release (DDR) technology, providing two distinct drug releases over 24 hours and flexible dosing without regard to meals.', '[''30 mg'', ''60 mg'']', '[''Dual Delayed-Release Capsule'']', '[''Oral'']', 'Pure (R)-enantiomer of lansoprazole; selectively inhibits gastric H+/K+-ATPase in parietal cells; unique Dual Delayed Release formulation contains two types of enteric-coated granules: the first release occurs in the duodenum at pH 5.5 (1-2 hours post-dose), and the second release occurs in the distal ileum at pH 6.75 (4-5 hours post-dose).', 'Produces a dual-peaked plasma concentration profile, extending the duration of acid suppression throughout the day and night; maintains intragastric pH > 4 for over 17 hours daily, effectively healing severe reflux esophagitis and relieving nocturnal heartburn.', 'Dual enteric release: first peak in 1 to 2 hours; second peak in 4 to 5 hours; CAN BE TAKEN WITHOUT REGARD TO FOOD (unique among PPIs).', 'Apparent volume of distribution approx. 40 L; highly bound to human plasma proteins (96-99%).', 'Extensively metabolized in the liver by CYP2C19 (hydroxylation) and CYP3A4 (sulfone formation).', 'Excreted in urine (approx. 51%) and faeces (approx. 48%) as inactive metabolites; zero unchanged parent drug.', 'High dual-phase bioavailability (unaffected by food)', '1 to 2 hours in plasma; dual release provides 24-hour acid suppression', '96% to 99%', 'Rapid within 1 to 2 hours', '24 hours (dual peak)', '[''Healing of all grades of erosive esophagitis (60 mg once daily for up to 8 weeks)'', ''Maintenance of healed erosive esophagitis and relief of heartburn (30 mg once daily)'', ''Treatment of symptomatic non-erosive gastroesophageal reflux disease (GERD - 30 mg once daily)'']', '[''Known hypersensitivity to dexlansoprazole or PPIs'', ''Concurrent use with rilpivirine'']', '[''Can be taken WITHOUT REGARD TO MEALS (unique convenience advantage over other PPIs)'', ''Long-term risks: hypomagnesemia, C. difficile colitis, bone fractures, vitamin B12 deficiency'', ''Capsules may be opened and sprinkled on applesauce if swallowing is difficult'']', '[''Diarrhoea (most common)'', ''Abdominal pain'', ''Nausea'', ''Upper respiratory tract infection'', ''Flatulence'']', '[''Clostridioides difficile-associated diarrhoea'', ''Hypomagnesemia / cardiac arrhythmias'', ''Bone fractures / osteoporosis (with high-dose chronic use)'', ''Acute interstitial nephritis'']', '[''Methotrexate (elevates methotrexate levels)'', ''Drugs dependent on gastric pH (ketoconazole, atazanavir, iron salts - decreased absorption)'', ''Warfarin (monitor INR)'', ''Tacrolimus'']', '[''Serum magnesium prior to starting and periodically during prolonged therapy'', ''Symptomatic relief of nocturnal heartburn and GERD'', ''Liver enzymes in hepatic impairment'']', 'Category B; animal studies show no teratogenicity; safe when clearly needed.', 'Excretion in human milk unknown; use caution during breastfeeding.', 'Approved for pediatric patients 12 years and older for GERD and erosive esophagitis.', 'No dosage adjustment required in elderly patients.', 'No dosage adjustment required in renal impairment.', 'No adjustment needed in mild hepatic impairment; maximum 30 mg daily in moderate hepatic impairment (Child-Pugh Class B); not recommended in severe cirrhosis.', '[''Only PPI with Dual Delayed Release (DDR) technology, producing two distinct plasma peaks that eliminate nocturnal acid breakthrough'', ''Dose can be taken AT ANY TIME OF DAY WITHOUT REGARD TO MEALS'', ''Superior healing rates for severe erosive esophagitis (Grade C and D)'']', '[''Higher cost than older generic omeprazole/pantoprazole'', ''Same class-wide long-term risks (low magnesium, fracture risk)'']', '[''The only acid pill you can take ANY time of day, with or without food'', ''Dual-release beads keep acid blocked all day and through the entire night'']', 'DEXLANSO-prazole: Dual Enteric X-release; Day & Night acid control; Any time dosing (no food rule).', '-prazole', 'dex-lan-SOE-pra-zole', 'डेक्सलैन्सो-प्राज़ोल', 'active', 'verified', NULL, NULL),
('ilaprazole', 'Ilaprazole', 'Ilaprazole', 'Ilaprazole', 'Ilaprazole', 'Gastrointestinal', 'A novel third-generation proton pump inhibitor with an extended plasma half-life and non-enzymatic clearance, providing superior nocturnal acid suppression and minimal CYP2C19 drug interactions.', '[''5 mg'', ''10 mg'']', '[''Enteric-Coated Tablet'']', '[''Oral'']', 'Irreversibly inhibits the gastric parietal H+/K+-ATPase pump; contains a pyrrole ring substituent that prolongs binding to sulfhydryl groups on the enzyme, conferring slow dissociation and prolonged antisecretory action.', 'Produces potent, dose-dependent, and sustained inhibition of gastric acid secretion; achieves higher 24-hour and nocturnal intragastric pH than omeprazole 20 mg; cleared predominantly by non-CYP pathways, minimizing genetic variability between extensive and poor metabolizers.', 'Rapidly absorbed from small intestine; peak plasma concentration in 3 to 4 hours; take 30 minutes before breakfast.', 'Extensively distributed into gastric mucosa; >95% bound to plasma proteins.', 'Metabolized in the liver primarily by CYP3A4/5 and non-enzymatic sulfoxidation; MINIMAL INVOLVEMENT OF CYP2C19 (eliminates genetic polymorphism differences).', 'Excreted in faeces (approx. 70%) and urine (approx. 25-30%) as metabolites.', 'Approximately 70%', '3 to 4 hours in plasma (longer than omeprazole''s 0.7h half-life)', '>95%', '1 to 2 hours', 'Over 24 hours', '[''Duodenal and gastric peptic ulcers'', ''Erosive and non-erosive gastroesophageal reflux disease (GERD)'', ''Nocturnal gastric acid breakthrough in refractory GERD patients'']', '[''Known hypersensitivity to ilaprazole or substituted benzimidazoles'', ''Concurrent use with atazanavir or rilpivirine'']', '[''Take 30 minutes before breakfast'', ''Swallow tablets whole; do not chew or crush'', ''Safe in CYP2C19 poor and rapid metabolizers due to non-CYP2C19 clearance'']', '[''Headache'', ''Dizziness'', ''Diarrhoea'', ''Nausea'', ''Abdominal distension'']', '[''Clostridioides difficile colitis'', ''Severe hypomagnesemia (chronic use)'', ''Acute interstitial nephritis (rare)'']', '[''Clopidogrel (SAFE: does NOT compete with CYP2C19, preserving clopidogrel antiplatelet activation)'', ''pH-dependent drugs (ketoconazole, iron salts - reduced absorption)'']', '[''Clinical ulcer healing on endoscopy or symptom resolution'', ''Serum magnesium in chronic therapy'']', 'Avoid in pregnancy due to limited human data; use established Category B PPIs (pantoprazole/lansoprazole).', 'Excretion in human milk unknown; avoid during breastfeeding.', 'Safety and efficacy in children not established.', 'No dosage adjustment required based on age alone.', 'No dosage adjustment required in renal impairment.', 'Use with caution in moderate to severe hepatic impairment.', '[''Minimal CYP2C19 metabolism: safe to combine with clopidogrel without impairing antiplatelet activation'', ''Longer plasma half-life (3-4 hours) provides superior nocturnal acid control'', ''Small 10 mg tablet provides potent acid suppression'']', '[''Limited availability in Western markets (widely approved in Asia, India, and China)'', ''Less long-term pregnancy safety data than omeprazole'']', '[''Advanced acid blocker that works safely with heart blood thinners like clopidogrel'', ''Take once daily 30 minutes before breakfast'']', 'ILA-prazole: Improved Long-acting Acid blocker; Independent of CYP2C19; Ideal with clopidogrel.', '-prazole', 'eye-LA-pra-zole', 'इला-प्राज़ोल', 'active', 'verified', NULL, NULL),
('roxatidine', 'Roxatidine', 'Roxatidine Acetate Hydrochloride', 'Roxatidine acetate hydrochloride', 'Roxatidine acetate hydrochloride', 'Gastrointestinal', 'A potent, competitive histamine H2-receptor antagonist with high oral bioavailability (95-100%) and zero antiandrogenic or CYP450 inhibitory actions, used for peptic ulcers and reflux esophagitis.', '[''75 mg'', ''150 mg'']', '[''Film-coated Tablet'', ''Sustained-Release Capsule'']', '[''Oral'']', 'De-acetylated in the liver and small intestine to active roxatidine, which competitively and selectively blocks histamine H2 receptors on the basolateral membrane of gastric parietal cells; prevents histamine-induced adenylate cyclase activation and cAMP-mediated gastric acid secretion.', 'Inhibits basal, nocturnal, food-stimulated, and pentagastrin-stimulated gastric acid and pepsin secretion; does NOT inhibit cytochrome P450 enzymes and does NOT possess antiandrogenic activity (zero gynecomastia or impotence).', 'Rapidly and completely absorbed from GI tract; near 100% oral bioavailability; peak plasma levels in 1 to 2 hours; food has no effect.', 'Widely distributed into tissues; low plasma protein binding (approx. 6-7%); volume of distribution approx. 1.5 L/kg.', 'Rapidly hydrolyzed in the liver by esterases to active roxatidine; minor glucuronidation.', 'Excreted predominantly in urine (approx. 90% within 24 hours, with 50-60% as active roxatidine and remainder as metabolites).', '95% to 100% (highest bioavailability in H2RA class)', '6 hours (active metabolite)', '6% to 7%', '30 to 60 minutes', '12 to 24 hours (75 mg BID or 150 mg at bedtime)', '[''Gastric and duodenal peptic ulcers'', ''Gastroesophageal reflux disease (GERD) and reflux esophagitis'', ''Prevention of stress ulcers and NSAID-associated gastropathy'', ''Zollinger-Ellison syndrome adjunct'']', '[''Hypersensitivity to roxatidine or H2-receptor antagonists'']', '[''Dose reduction mandatory in renal failure (CrCl < 50 mL/min) to prevent CNS confusion'', ''H2-receptor antagonists develop pharmacodynamic tolerance (tachyphylaxis) after 2-4 weeks of continuous use'', ''Does not interfere with liver CYP enzymes (clean drug interaction profile)'']', '[''Constipation or diarrhoea'', ''Headache'', ''Dizziness'', ''Fatigue'', ''Dry mouth'']', '[''Reversible mental confusion / hallucinations (in elderly patients with renal failure)'', ''Agranulocytosis / thrombocytopenia (rare)'', ''Cardiac arrhythmias / bradycardia (rare)'']', '[''Free of CYP450 interactions (does NOT interact with warfarin, phenytoin, or theophylline, unlike cimetidine)'', ''Drugs requiring acidic gastric pH (ketoconazole, itraconazole, atazanavir - reduced absorption)'']', '[''Renal function (creatinine clearance) prior to therapy'', ''Relief of nocturnal dyspepsia / epigastric pain'']', 'Category B; limited data; use only if clearly needed (prefer famotidine).', 'Excreted in human milk; compatible with caution or alternative H2RA.', 'Safety and efficacy in pediatric patients not established.', 'Higher susceptibility to CNS confusion; reduce dose and monitor mental status.', 'Dose reduction required: CrCl 20-50 mL/min: 75 mg once daily at bedtime; CrCl < 20 mL/min: 75 mg every other day.', 'No dosage adjustment required in mild to moderate hepatic impairment.', '[''Near 100% oral bioavailability guarantees predictable acid suppression'', ''Completely free of CYP450 drug interactions and free of antiandrogenic side effects (unlike cimetidine)'', ''Convenient single bedtime dose (150 mg) for peptic ulcer healing'']', '[''Develops tachyphylaxis (tolerance) with chronic continuous use'', ''Less potent acid suppression than proton pump inhibitors'']', '[''Safe stomach acid reducer that does not interfere with other medications or liver enzymes'', ''Take 75 mg twice daily or 150 mg once at bedtime'']', 'ROXA-tidine: Reliable 100% absorption; Outperforms cimetidine (zero CYP block); eXcellent for Night acid.', '-tidine', 'rox-A-ti-deen', 'रोक्सा-टिडीन', 'active', 'verified', NULL, NULL),
('cimetidine', 'Cimetidine', 'Cimetidine', 'Cimetidine', 'Cimetidine', 'Gastrointestinal', 'The historical prototype histamine H2-receptor antagonist, characterized by potent CYP450 enzyme inhibition and antiandrogenic properties, now largely superseded by cleaner H2 blockers.', '[''200 mg'', ''400 mg'', ''800 mg'']', '[''Film-coated Tablet'']', '[''Oral'']', 'Competitively blocks histamine H2 receptors on parietal cells, reducing basal, nocturnal, and meal-stimulated gastric acid production; also binds to imidazole receptors and inhibits cytochrome P450 monooxygenases.', 'Reduces gastric acid output; uniquely possesses antiandrogenic activity (displaces dihydrotestosterone from androgen receptors and inhibits estrogen breakdown) and stimulates cell-mediated immunity (used off-label for recalcitrant viral warts).', 'Rapidly absorbed (60-70%); peak plasma concentration in 1 to 2 hours; food slightly delays absorption.', 'Widely distributed; volume of distribution approx. 1 L/kg; crosses blood-brain barrier and placenta; 15-20% protein bound.', 'Partially metabolized in the liver (approx. 30-40%) by CYP enzymes to cimetidine sulfoxide.', 'Excreted in urine (approx. 60-70% within 24 hours as unchanged parent drug); remainder in faeces.', '60% to 70%', '2 hours (prolonged in renal failure to 5-8 hours)', '15% to 20%', '30 to 60 minutes', '4 to 8 hours (requires 2-4 times daily dosing)', '[''Gastric and duodenal ulcers (acute healing and maintenance)'', ''Gastroesophageal reflux disease (GERD)'', ''Pathological hypersecretory conditions (Zollinger-Ellison syndrome)'', ''Off-label: recalcitrant cutaneous warts in children (immunomodulatory role)'']', '[''Known hypersensitivity to cimetidine'']', '[''POTENT CYTOCHROME P450 INHIBITOR: Inhibits CYP1A2, CYP2C9, CYP2D6, and CYP3A4, causing dangerous elevations of warfarin, theophylline, phenytoin, and lidocaine'', ''ANTIANDROGENIC EFFECTS: High-dose or long-term therapy causes gynecomastia, galactorrhea, decreased libido, and erectile dysfunction in men (fully reversible)'', ''CNS toxicity (confusion, delirium, hallucinations) in elderly and renal patients'']', '[''Gynecomastia and breast tenderness in men (with chronic therapy)'', ''Decreased libido / erectile dysfunction'', ''Diarrhoea'', ''Dizziness'', ''Headache'', ''Fatigue'']', '[''Severe mental confusion / delirium in elderly patients'', ''Agranulocytosis / neutropenia (rare)'', ''Bradycardia / hypotension (with rapid IV injection)'']', '[''Warfarin (CYP2C9 inhibition doubles INR; severe bleeding risk)'', ''Theophylline (CYP1A2 inhibition causes theophylline toxicity)'', ''Phenytoin (CYP2C9 inhibition causes phenytoin toxicity)'', ''Lidocaine (increases lidocaine levels)'']', '[''Mental status in elderly or renal patients'', ''Serum creatinine and eGFR'', ''Prothrombin time (INR) if patient is taking warfarin'']', 'Category B; crosses placenta; widely used historically with no documented teratogenicity.', 'Excreted in high concentrations in breast milk; compatible with caution or prefer famotidine.', 'Approved for pediatric ulcer disease and off-label for viral warts (20-40 mg/kg/day).', 'High risk of CNS confusion and drug interactions; start at reduced dose (200-400 mg daily).', 'Dose reduction mandatory: CrCl 20-40 mL/min: 300 mg q12h; CrCl < 20 mL/min: 300 mg q24h.', 'Dose reduction required in severe hepatic cirrhosis.', '[''Historical landmark drug that revolutionized the medical treatment of peptic ulcers in 1976'', ''Immunomodulatory properties make it an effective, painless oral treatment for pediatric viral warts'', ''Multiple daily dosing options'']', '[''Potent CYP450 inhibitor causing dangerous drug interactions with warfarin, theophylline, and phenytoin'', ''Causes painful breast enlargement (gynecomastia) and impotence in men'']', '[''Historical acid blocker with many drug interactions; inform your doctor of all your other medications'', ''Can cause breast swelling or tenderness in men with long-term use'']', 'CIMET